python3 -c '
import json
with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)
for path, methods in spec["paths"].items():
    for method, op in methods.items():
        if not isinstance(op, dict): continue
        errs = {}
        for st in ["400", "403", "404", "409"]:
            if st in op["responses"]:
                errs[st] = op["responses"][st]["content"]["application/json"]["schema"]["properties"]["code"]["enum"]
        print(f"{path}: {errs}")
'

