package main

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"time"

	"github.com/google/uuid"
)

type dbLocation struct {
	LocationID          uuid.UUID
	Name                string
	Latitude            float64
	Longitude           float64
	CoverageKm          float64
	HandlingMinutes     int
	Active              bool
	FnCollectionPoint   bool
	FnTransferPoint     bool
	FnHub               bool
	FnLaboratory        bool
	CapacityUnits       int
	ReservedUnits       int
	CooledCapacityUnits int
	CooledReservedUnits int
}

type dbConnection struct {
	ConnectionID        uuid.UUID
	FromLocationID      uuid.UUID
	ToLocationID        uuid.UUID
	TravelMinutes       int
	CostUnits           float64
	Cooled              bool
	Active              bool
	CapacityUnits       int
	ReservedUnits       int
	CooledCapacityUnits int
	CooledReservedUnits int
}

type dbSampleType struct {
	SampleTypeID               uuid.UUID
	Name                       string
	QualifiedCollectorRequired bool
	RequiredQualification      string
	ContainerType              string
	TemperatureMinC            float64
	TemperatureMaxC            float64
	IncompatibleSampleTypes    []string
	RequiresCooledRoute        bool
	BatchingAllowed            bool
}

type plannedRoute struct {
	Nodes               []dbLocation
	Connections         []dbConnection
	TotalTravelMinutes  int
	TotalHandlingMins   int
	TotalCostUnits      float64
	TargetLaboratoryID  uuid.UUID
	EstimatedDeliveryAt time.Time
}

func (s *Server) recomputeServiceabilitySnapshot(ctx context.Context, q DBTx) error {
	var prevRev int
	_ = q.QueryRow(ctx, `SELECT COALESCE(MAX(network_revision), 0) FROM serviceability_snapshots`).Scan(&prevRev)
	nextRev := prevRev + 1
	now := time.Now().UTC()

	var version int
	err := q.QueryRow(ctx, `
		INSERT INTO serviceability_snapshots (status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ('computing', $1, $2, '[]'::jsonb, 0)
		RETURNING version
	`, now, nextRev).Scan(&version)
	if err != nil {
		return err
	}

	rows, err := q.Query(ctx, `
		SELECT location_id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = TRUE AND fn_collection_point = TRUE
		ORDER BY created_at ASC
	`)
	if err != nil {
		return err
	}
	defer rows.Close()

	regions := []ServiceabilityRegion{}
	for rows.Next() {
		var r ServiceabilityRegion
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err == nil {
			regions = append(regions, r)
		}
	}
	regBytes, _ := json.Marshal(regions)

	_, err = q.Exec(ctx, `
		UPDATE serviceability_snapshots
		SET status = 'complete', computed_at = $1, regions = $2, active_collection_point_count = $3
		WHERE version = $4
	`, now, regBytes, len(regions), version)
	return err
}

func (s *Server) getLatestServiceabilityVersion(ctx context.Context, q DBTx) int {
	var ver int
	err := q.QueryRow(ctx, `
		SELECT version FROM serviceability_snapshots
		WHERE status = 'complete'
		ORDER BY version DESC LIMIT 1
	`).Scan(&ver)
	if err != nil || ver < 1 {
		return 1
	}
	return ver
}

func (s *Server) loadSampleType(ctx context.Context, q DBTx, id uuid.UUID) (*dbSampleType, error) {
	var st dbSampleType
	var incBytes []byte
	err := q.QueryRow(ctx, `
		SELECT sample_type_id, name, qualified_collector_required, required_qualification,
		       container_type, temperature_min_c, temperature_max_c,
		       incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types WHERE sample_type_id = $1
	`, id).Scan(
		&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification,
		&st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC,
		&incBytes, &st.RequiresCooledRoute, &st.BatchingAllowed,
	)
	if err != nil {
		return nil, err
	}
	_ = json.Unmarshal(incBytes, &st.IncompatibleSampleTypes)
	if st.IncompatibleSampleTypes == nil {
		st.IncompatibleSampleTypes = []string{}
	}
	return &st, nil
}

func (s *Server) loadNetwork(ctx context.Context, q DBTx) (map[uuid.UUID]dbLocation, []dbConnection, map[uuid.UUID]map[uuid.UUID]bool, error) {
	locs := make(map[uuid.UUID]dbLocation)
	lRows, err := q.Query(ctx, `
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		       fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations
	`)
	if err != nil {
		return nil, nil, nil, err
	}
	defer lRows.Close()
	for lRows.Next() {
		var l dbLocation
		if err := lRows.Scan(
			&l.LocationID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.FnCollectionPoint, &l.FnTransferPoint, &l.FnHub, &l.FnLaboratory,
			&l.CapacityUnits, &l.ReservedUnits, &l.CooledCapacityUnits, &l.CooledReservedUnits,
		); err == nil {
			locs[l.LocationID] = l
		}
	}

	var conns []dbConnection
	cRows, err := q.Query(ctx, `
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units,
		       cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, nil, nil, err
	}
	defer cRows.Close()
	for cRows.Next() {
		var c dbConnection
		if err := cRows.Scan(
			&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits,
			&c.Cooled, &c.Active, &c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits,
		); err == nil {
			conns = append(conns, c)
		}
	}

	accepts := make(map[uuid.UUID]map[uuid.UUID]bool)
	aRows, err := q.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM lab_acceptances WHERE accepts = TRUE`)
	if err != nil {
		return nil, nil, nil, err
	}
	defer aRows.Close()
	for aRows.Next() {
		var labID, stID uuid.UUID
		var acc bool
		if err := aRows.Scan(&labID, &stID, &acc); err == nil && acc {
			if accepts[labID] == nil {
				accepts[labID] = make(map[uuid.UUID]bool)
			}
			accepts[labID][stID] = true
		}
	}

	return locs, conns, accepts, nil
}

func hasLocCapacity(l dbLocation, cooled bool, units int) bool {
	if cooled {
		return (l.CooledCapacityUnits - l.CooledReservedUnits) >= units
	}
	return (l.CapacityUnits - l.ReservedUnits) >= units
}

func hasConnCapacity(c dbConnection, cooled bool, units int) bool {
	if cooled {
		if !c.Cooled {
			return false
		}
		return (c.CooledCapacityUnits - c.CooledReservedUnits) >= units
	}
	return (c.CapacityUnits - c.ReservedUnits) >= units
}

// evaluateServiceability evaluates whether a request from origin (or startNodeID) for st can reach an accepting lab before deadline.
// Returns (serviceable, reason, conflictErrorCode, route)
func (s *Server) evaluateServiceability(
	ctx context.Context,
	q DBTx,
	origin Coordinate,
	originType string,
	originNodeID *uuid.UUID,
	st *dbSampleType,
	startTime time.Time,
	deadline time.Time,
	units int,
) (bool, string, string, *plannedRoute) {
	if st == nil || st.ContainerType == "" || st.TemperatureMinC > st.TemperatureMaxC {
		return false, "handling_rules_unsatisfiable", "invalid_plan", nil
	}
	if units < 1 {
		units = 1
	}

	locs, conns, accepts, err := s.loadNetwork(ctx, q)
	if err != nil {
		return false, "no_route", "no_valid_route", nil
	}

	// Step 1: Candidate start nodes
	var startNodes []dbLocation
	if originNodeID != nil {
		loc, ok := locs[*originNodeID]
		if !ok || !loc.Active {
			return false, "outside_service_coverage", "no_valid_route", nil
		}
		dist := haversineKm(origin, Coordinate{Latitude: loc.Latitude, Longitude: loc.Longitude})
		maxCov := loc.CoverageKm
		if maxCov > 5.0 {
			maxCov = 5.0
		}
		if originType == "home" && (!loc.FnCollectionPoint || dist > maxCov) {
			return false, "outside_service_coverage", "no_valid_route", nil
		}
		if dist > 5.0 && dist > maxCov+0.01 {
			return false, "outside_service_coverage", "no_valid_route", nil
		}
		startNodes = append(startNodes, loc)
	} else {
		for _, loc := range locs {
			if !loc.Active || !loc.FnCollectionPoint {
				continue
			}
			maxCov := loc.CoverageKm
			if maxCov > 5.0 {
				maxCov = 5.0
			}
			dist := haversineKm(origin, Coordinate{Latitude: loc.Latitude, Longitude: loc.Longitude})
			if dist <= maxCov && dist <= 5.0 {
				startNodes = append(startNodes, loc)
			}
		}
		sort.Slice(startNodes, func(i, j int) bool {
			di := haversineKm(origin, Coordinate{Latitude: startNodes[i].Latitude, Longitude: startNodes[i].Longitude})
			dj := haversineKm(origin, Coordinate{Latitude: startNodes[j].Latitude, Longitude: startNodes[j].Longitude})
			if math.Abs(di-dj) > 1e-6 {
				return di < dj
			}
			return startNodes[i].LocationID.String() < startNodes[j].LocationID.String()
		})
	}

	if len(startNodes) == 0 {
		return false, "outside_service_coverage", "no_valid_route", nil
	}

	// Step 2: Check accepting active laboratories
	var acceptingLabs []dbLocation
	for _, loc := range locs {
		if loc.Active && loc.FnLaboratory && accepts[loc.LocationID][st.SampleTypeID] {
			acceptingLabs = append(acceptingLabs, loc)
		}
	}
	if len(acceptingLabs) == 0 {
		return false, "no_accepting_laboratory", "no_valid_route", nil
	}
	acceptingSet := make(map[uuid.UUID]bool)
	for _, lab := range acceptingLabs {
		acceptingSet[lab.LocationID] = true
	}

	// Build adjacency list of active connections
	adj := make(map[uuid.UUID][]dbConnection)
	for _, c := range conns {
		if c.Active {
			adj[c.FromLocationID] = append(adj[c.FromLocationID], c)
		}
	}

	// Search all simple paths up to depth 8 from startNodes to acceptingSet
	type candidatePath struct {
		nodes       []dbLocation
		conns       []dbConnection
		cooledOK    bool
		capOK       bool
		cooledCapOK bool
		travelMins  int
		handleMins  int
		cost        float64
		arrival     time.Time
		deadlineOK  bool
	}

	var allPaths []candidatePath

	var dfs func(curr dbLocation, visited map[uuid.UUID]bool, pathNodes []dbLocation, pathConns []dbConnection)
	dfs = func(curr dbLocation, visited map[uuid.UUID]bool, pathNodes []dbLocation, pathConns []dbConnection) {
		if acceptingSet[curr.LocationID] && len(pathConns) > 0 {
			cp := evaluateCandidatePath(pathNodes, pathConns, st.RequiresCooledRoute, units, startTime, deadline)
			allPaths = append(allPaths, cp)
		} else if acceptingSet[curr.LocationID] && len(pathConns) == 0 {
			cp := evaluateCandidatePath(pathNodes, pathConns, st.RequiresCooledRoute, units, startTime, deadline)
			allPaths = append(allPaths, cp)
		}
		if len(pathConns) >= 6 {
			return
		}
		for _, conn := range adj[curr.LocationID] {
			if visited[conn.ToLocationID] {
				continue
			}
			nextLoc, ok := locs[conn.ToLocationID]
			if !ok || !nextLoc.Active {
				continue
			}
			// Must be transfer_point, hub, collection_point, or accepting laboratory
			if !nextLoc.FnTransferPoint && !nextLoc.FnHub && !nextLoc.FnCollectionPoint && !acceptingSet[nextLoc.LocationID] {
				continue
			}
			visited[nextLoc.LocationID] = true
			dfs(nextLoc, visited, append(append([]dbLocation{}, pathNodes...), nextLoc), append(append([]dbConnection{}, pathConns...), conn))
			delete(visited, nextLoc.LocationID)
		}
	}

	for _, sn := range startNodes {
		visited := map[uuid.UUID]bool{sn.LocationID: true}
		dfs(sn, visited, []dbLocation{sn}, nil)
	}

	if len(allPaths) == 0 {
		return false, "no_route", "no_valid_route", nil
	}

	// Filter by cooled route requirement
	var cooledPaths []candidatePath
	for _, p := range allPaths {
		if p.cooledOK {
			cooledPaths = append(cooledPaths, p)
		}
	}
	if len(cooledPaths) == 0 {
		return false, "handling_rules_unsatisfiable", "cooled_capacity_exhausted", nil
	}

	// Filter by capacity
	var capPaths []candidatePath
	for _, p := range cooledPaths {
		if p.capOK {
			capPaths = append(capPaths, p)
		}
	}
	if len(capPaths) == 0 {
		if st.RequiresCooledRoute {
			return false, "insufficient_capacity", "cooled_capacity_exhausted", nil
		}
		return false, "insufficient_capacity", "capacity_exhausted", nil
	}

	// Filter by deadline
	var validPaths []candidatePath
	for _, p := range capPaths {
		if p.deadlineOK {
			validPaths = append(validPaths, p)
		}
	}
	if len(validPaths) == 0 {
		return false, "deadline_unreachable", "delivery_deadline_exceeded", nil
	}

	// Sort validPaths by earliest arrival, then lowest cost, then fewest hops
	sort.Slice(validPaths, func(i, j int) bool {
		if !validPaths[i].arrival.Equal(validPaths[j].arrival) {
			return validPaths[i].arrival.Before(validPaths[j].arrival)
		}
		if math.Abs(validPaths[i].cost-validPaths[j].cost) > 1e-6 {
			return validPaths[i].cost < validPaths[j].cost
		}
		return len(validPaths[i].conns) < len(validPaths[j].conns)
	})

	best := validPaths[0]
	targetLab := best.nodes[len(best.nodes)-1].LocationID
	return true, "serviceable", "", &plannedRoute{
		Nodes:               best.nodes,
		Connections:         best.conns,
		TotalTravelMinutes:  best.travelMins,
		TotalHandlingMins:   best.handleMins,
		TotalCostUnits:      best.cost,
		TargetLaboratoryID:  targetLab,
		EstimatedDeliveryAt: best.arrival,
	}
}

func evaluateCandidatePath(nodes []dbLocation, conns []dbConnection, requiresCooled bool, units int, startTime, deadline time.Time) struct {
	nodes       []dbLocation
	conns       []dbConnection
	cooledOK    bool
	capOK       bool
	cooledCapOK bool
	travelMins  int
	handleMins  int
	cost        float64
	arrival     time.Time
	deadlineOK  bool
} {
	cooledOK := true
	capOK := true
	cooledCapOK := true

	for _, n := range nodes {
		if requiresCooled {
			if (n.CooledCapacityUnits - n.CooledReservedUnits) < units {
				capOK = false
				cooledCapOK = false
			}
		} else {
			if (n.CapacityUnits - n.ReservedUnits) < units {
				capOK = false
			}
		}
	}
	travelMins := 0
	cost := 0.0
	for _, c := range conns {
		travelMins += c.TravelMinutes
		cost += c.CostUnits
		if requiresCooled {
			if !c.Cooled {
				cooledOK = false
			}
			if (c.CooledCapacityUnits - c.CooledReservedUnits) < units {
				capOK = false
				cooledCapOK = false
			}
		} else {
			if (c.CapacityUnits - c.ReservedUnits) < units {
				capOK = false
			}
		}
	}
	handleMins := 0
	for _, n := range nodes {
		handleMins += n.HandlingMinutes
	}
	arrival := startTime.Add(time.Duration(travelMins+handleMins) * time.Minute)
	deadlineOK := !arrival.After(deadline)

	return struct {
		nodes       []dbLocation
		conns       []dbConnection
		cooledOK    bool
		capOK       bool
		cooledCapOK bool
		travelMins  int
		handleMins  int
		cost        float64
		arrival     time.Time
		deadlineOK  bool
	}{
		nodes:       nodes,
		conns:       conns,
		cooledOK:    cooledOK,
		capOK:       capOK,
		cooledCapOK: cooledCapOK,
		travelMins:  travelMins,
		handleMins:  handleMins,
		cost:        cost,
		arrival:     arrival,
		deadlineOK:  deadlineOK,
	}
}

// Worker selection & fairness
func isWorkerQualifiedForSampleType(quals []string, certs []Certification, st *dbSampleType, refTime time.Time) bool {
	if st == nil || !st.QualifiedCollectorRequired || st.RequiredQualification == "" {
		return true
	}
	reqQual := st.RequiredQualification
	if refTime.IsZero() {
		refTime = time.Now().UTC()
	}

	// Check certifications first if any certification matches reqQual
	foundCert := false
	for _, c := range certs {
		if strings.EqualFold(c.Code, reqQual) {
			foundCert = true
			if !c.Active {
				return false
			}
			if c.ExpiresAt != nil && *c.ExpiresAt != "" {
				if exp, err := parseTimeISO(*c.ExpiresAt); err == nil {
					if exp.Before(refTime) {
						return false
					}
				}
			}
			return true
		}
	}
	if foundCert {
		return false
	}

	for _, q := range quals {
		if strings.EqualFold(q, reqQual) {
			return true
		}
	}
	return false
}

func (s *Server) findEligibleWorkerForAssignment(
	ctx context.Context,
	q DBTx,
	kind string,
	st *dbSampleType,
	locationID *uuid.UUID,
	declinedWorkerIDs []string,
	refTime time.Time,
	usedInCycle map[uuid.UUID]int,
) (*uuid.UUID, error) {
	roleRequired := ""
	switch kind {
	case "collection":
		roleRequired = "collection_professional"
	case "transport":
		roleRequired = "delivery_partner"
	case "node":
		roleRequired = "node_handler"
	case "laboratory":
		roleRequired = "laboratory_team"
	default:
		return nil, nil
	}

	rows, err := q.Query(ctx, `
		SELECT u.user_id, u.roles, u.qualifications, u.certifications, u.assigned_location_id,
		       u.available, u.capacity_units, u.assignment_count, u.decline_count,
		       u.last_declined_at, u.last_offered_at,
		       (SELECT COUNT(*) FROM assignments a WHERE (a.worker_id = u.user_id OR a.offered_to_worker_id = u.user_id) AND a.active = TRUE AND a.status NOT IN ('completed', 'delivered', 'cancelled')) AS active_load,
		       (SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.user_id OR a.offered_to_worker_id = u.user_id) AS total_assigned
		FROM users u
		WHERE u.active = TRUE AND u.available = TRUE AND u.capacity_units > 0
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	type candidate struct {
		userID        uuid.UUID
		activeLoad    int
		totalAssigned int
		assignCount   int
		declineCount  int
		recentDecline bool
		wasDeclined   bool
		lastOffered   time.Time
	}

	var candidates []candidate
	for rows.Next() {
		var uid uuid.UUID
		var rolesB, qualsB, certsB []byte
		var assignedLoc *uuid.UUID
		var avail bool
		var capUnits, assignCnt, declineCnt, activeLoad, totalAssigned int
		var lastDeclined, lastOffered *time.Time

		if err := rows.Scan(
			&uid, &rolesB, &qualsB, &certsB, &assignedLoc,
			&avail, &capUnits, &assignCnt, &declineCnt,
			&lastDeclined, &lastOffered, &activeLoad, &totalAssigned,
		); err != nil {
			continue
		}

		var roles []string
		_ = json.Unmarshal(rolesB, &roles)
		if !hasString(roles, roleRequired) {
			continue
		}

		if (kind == "node" || kind == "laboratory") && locationID != nil {
			if assignedLoc == nil || *assignedLoc != *locationID {
				continue
			}
		}

		var quals []string
		_ = json.Unmarshal(qualsB, &quals)
		var certs []Certification
		_ = json.Unmarshal(certsB, &certs)

		if kind == "collection" && !isWorkerQualifiedForSampleType(quals, certs, st, refTime) {
			continue
		}

		extra := 0
		if usedInCycle != nil {
			extra = usedInCycle[uid]
		}
		if activeLoad+extra >= capUnits {
			continue
		}

		wasDeclined := hasString(declinedWorkerIDs, uid.String())
		recentDecl := false
		if lastDeclined != nil && refTime.Sub(*lastDeclined) < 30*time.Minute && declineCnt > 0 {
			recentDecl = true
		}
		var lo time.Time
		if lastOffered != nil {
			lo = *lastOffered
		}

		candidates = append(candidates, candidate{
			userID:        uid,
			activeLoad:    activeLoad + extra,
			totalAssigned: totalAssigned + extra,
			assignCount:   assignCnt + extra,
			declineCount:  declineCnt,
			recentDecline: recentDecl,
			wasDeclined:   wasDeclined,
			lastOffered:   lo,
		})
	}

	if len(candidates) == 0 {
		return nil, nil
	}

	// Prefer candidates who have NOT already declined this specific assignment, unless all eligible workers declined it
	nonDeclined := []candidate{}
	for _, c := range candidates {
		if !c.wasDeclined {
			nonDeclined = append(nonDeclined, c)
		}
	}
	pool := nonDeclined
	if len(pool) == 0 {
		return nil, nil
	}

	sort.Slice(pool, func(i, j int) bool {
		// 1. Recent decline penalty (temporary lower priority)
		if pool[i].recentDecline != pool[j].recentDecline {
			return !pool[i].recentDecline
		}
		// 2. Lowest total assigned / assignment count for fairness
		if pool[i].assignCount != pool[j].assignCount {
			return pool[i].assignCount < pool[j].assignCount
		}
		if pool[i].activeLoad != pool[j].activeLoad {
			return pool[i].activeLoad < pool[j].activeLoad
		}
		if pool[i].totalAssigned != pool[j].totalAssigned {
			return pool[i].totalAssigned < pool[j].totalAssigned
		}
		if !pool[i].lastOffered.Equal(pool[j].lastOffered) {
			return pool[i].lastOffered.Before(pool[j].lastOffered)
		}
		return pool[i].userID.String() < pool[j].userID.String()
	})

	chosen := pool[0].userID
	return &chosen, nil
}

