func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "configure_capacity", "administrator", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		ResourceID          *string `json:"resourceId"`
		CapacityUnits       *int    `json:"capacityUnits"`
		CooledCapacityUnits *int    `json:"cooledCapacityUnits"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.ResourceID == nil || req.CapacityUnits == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	resID, err := uuid.Parse(*req.ResourceID)
	if err != nil || *req.CapacityUnits < 0 {
		writeError(w, 400, "invalid_capacity", "Invalid capacity parameters")
		return
	}
	cooledCap := 0
	if req.CooledCapacityUnits != nil {
		if *req.CooledCapacityUnits < 0 {
			writeError(w, 400, "invalid_capacity", "Invalid cooledCapacityUnits")
			return
		}
		cooledCap = *req.CooledCapacityUnits
	}

	if auth.ActiveRole == "node_handler" || auth.ActiveRole == "laboratory_team" {
		if auth.AssignedLocationID == nil || *auth.AssignedLocationID != resID {
			s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "configure_capacity", "capacity", resID.String(), false, time.Now().UTC(), map[string]any{"reason": "unassigned_location"})
			writeError(w, 403, "forbidden", "Cannot configure capacity for unassigned location")
			return
		}
	}

	// Check if resource is a location or a connection
	var resUnits, cooledResUnits int
	err = s.db.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM locations WHERE location_id = $1`, resID).Scan(&resUnits, &cooledResUnits)
	if err == nil {
		if *req.CapacityUnits < resUnits || cooledCap < cooledResUnits {
			writeError(w, 409, "capacity_reserved", "Cannot reduce capacity below currently reserved units")
			return
		}
		_, _ = s.db.Exec(ctx, `UPDATE locations SET capacity_units = $1, cooled_capacity_units = $2 WHERE location_id = $3`, *req.CapacityUnits, cooledCap, resID)
	} else {
		if auth.ActiveRole != "administrator" {
			writeError(w, 403, "forbidden", "Only administrator can configure connection capacity")
			return
		}
		err = s.db.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM connections WHERE connection_id = $1`, resID).Scan(&resUnits, &cooledResUnits)
		if err != nil {
			writeError(w, 400, "invalid_capacity", "Resource not found")
			return
		}
		if *req.CapacityUnits < resUnits || cooledCap < cooledResUnits {
			writeError(w, 409, "capacity_reserved", "Cannot reduce capacity below currently reserved units")
			return
		}
		_, _ = s.db.Exec(ctx, `UPDATE connections SET capacity_units = $1, cooled_capacity_units = $2 WHERE connection_id = $3`, *req.CapacityUnits, cooledCap, resID)
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "configure_capacity", "capacity", resID.String(), true, time.Now().UTC(), map[string]any{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooledCap})
	s.publishEvent(ctx, s.db, "capacity_configured", "capacity", resID.String(), map[string]any{"resourceId": resID.String(), "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooledCap})

	writeData(w, 200, map[string]any{
		"resourceId":          resID.String(),
		"capacityUnits":       *req.CapacityUnits,
		"cooledCapacityUnits": cooledCap,
	})
}

func (s *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "set_worker_availability", "administrator", "dispatcher", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		WorkerID      *string `json:"workerId"`
		Available     *bool   `json:"available"`
		CapacityUnits *int    `json:"capacityUnits"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.WorkerID == nil || req.Available == nil || req.CapacityUnits == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	wID, err := uuid.Parse(*req.WorkerID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid workerId")
		return
	}
	if *req.CapacityUnits < 0 {
		writeError(w, 400, "invalid_capacity", "capacityUnits must be >= 0")
		return
	}
	if auth.ActiveRole != "administrator" && auth.ActiveRole != "dispatcher" && auth.UserID != wID {
		writeError(w, 403, "forbidden", "Forbidden")
		return
	}

	var exists int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM users WHERE user_id = $1`, wID).Scan(&exists)
	if exists == 0 {
		writeError(w, 404, "not_found", "Worker not found")
		return
	}

	var activeAccepted int
	_ = s.db.QueryRow(ctx, `
		SELECT COUNT(*) FROM assignments
		WHERE worker_id = $1 AND active = TRUE AND status NOT IN ('completed', 'delivered', 'cancelled')
	`, wID).Scan(&activeAccepted)
	if *req.CapacityUnits < activeAccepted {
		writeError(w, 409, "capacity_reserved", "Worker has active assignments exceeding requested capacity")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE users SET available = $1, capacity_units = $2 WHERE user_id = $3
	`, *req.Available, *req.CapacityUnits, wID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update worker availability")
		return
	}

	if *req.Available && *req.CapacityUnits > 0 {
		s.tryOfferPendingAssignments(ctx, s.db)
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "set_worker_availability", "user", wID.String(), true, time.Now().UTC(), map[string]any{"available": *req.Available, "capacityUnits": *req.CapacityUnits})
	s.publishEvent(ctx, s.db, "worker_availability_changed", "user", wID.String(), map[string]any{"workerId": wID.String(), "available": *req.Available})

	writeData(w, 200, map[string]any{
		"workerId":      wID.String(),
		"available":     *req.Available,
		"capacityUnits": *req.CapacityUnits,
	})
}

func (s *Server) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	_, ok := s.requireRole(ctx, w, r, "read_serviceability_snapshot", "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct{}
	if _, err := decodeStrictJSON(r, &req, true); err != nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}

	var ver, netRev, cpCount int
	var status string
	var compAt time.Time
	var regB []byte
	err := s.db.QueryRow(ctx, `
		SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots
		WHERE status = 'complete'
		ORDER BY version DESC LIMIT 1
	`).Scan(&ver, &status, &compAt, &netRev, &regB, &cpCount)
	if err != nil {
		ver = 1
		status = "complete"
		compAt = time.Now().UTC()
		netRev = 0
		cpCount = 0
		regB = []byte("[]")
	}

	var regions []ServiceabilityRegion
	_ = json.Unmarshal(regB, &regions)
	if regions == nil {
		regions = []ServiceabilityRegion{}
	}

	writeData(w, 200, map[string]any{
		"version":                    ver,
		"status":                     "complete",
		"computedAt":                 formatTimeISO(compAt),
		"networkRevision":            netRev,
		"regions":                    regions,
		"activeCollectionPointCount": cpCount,
	})
}

func (s *Server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	_, ok := s.requireRole(ctx, w, r, "check_serviceability", "requester", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		Origin               *Coordinate `json:"origin"`
		OriginType           *string     `json:"originType"`
		OriginNodeID         *string     `json:"originNodeId"`
		SampleTypeID         *string     `json:"sampleTypeId"`
		RequestedAt          *string     `json:"requestedAt"`
		DeliveryDeadline     *string     `json:"deliveryDeadline"`
		EarliestCollectionAt *string     `json:"earliestCollectionAt"`
		LatestCollectionAt   *string     `json:"latestCollectionAt"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.Origin == nil || req.SampleTypeID == nil || req.RequestedAt == nil || req.DeliveryDeadline == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if !validateCoordinate(*req.Origin) {
		writeError(w, 400, "invalid_origin", "Invalid origin coordinate")
		return
	}
	originType := "home"
	if req.OriginType != nil && *req.OriginType != "" {
		originType = *req.OriginType
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		writeError(w, 400, "invalid_origin_type", "Invalid originType")
		return
	}
	var originNodeID *uuid.UUID
	if req.OriginNodeID != nil && *req.OriginNodeID != "" {
		parsed, err := uuid.Parse(*req.OriginNodeID)
		if err != nil {
			writeError(w, 400, "invalid_origin", "Invalid originNodeId")
			return
		}
		originNodeID = &parsed
	}
	stID, err := uuid.Parse(*req.SampleTypeID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid sampleTypeId")
		return
	}
	reqTime, err1 := parseTimeISO(*req.RequestedAt)
	deadline, err2 := parseTimeISO(*req.DeliveryDeadline)
	if err1 != nil || err2 != nil {
		writeError(w, 400, "invalid_time", "Invalid timestamp")
		return
	}
	earliest := reqTime
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := parseTimeISO(*req.EarliestCollectionAt)
		if err != nil {
			writeError(w, 400, "invalid_time", "Invalid earliestCollectionAt")
			return
		}
		earliest = t
	}
	latest := deadline
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, err := parseTimeISO(*req.LatestCollectionAt)
		if err != nil {
			writeError(w, 400, "invalid_time", "Invalid latestCollectionAt")
			return
		}
		latest = t
	}
	if earliest.After(latest) || earliest.Before(reqTime) {
		writeError(w, 400, "invalid_collection_window", "Invalid collection window")
		return
	}
	if !deadline.After(reqTime) || deadline.Before(earliest) {
		writeError(w, 400, "invalid_deadline", "Invalid delivery deadline")
		return
	}

	st, err := s.loadSampleType(ctx, s.db, stID)
	if err != nil {
		writeError(w, 404, "not_found", "Sample type not found")
		return
	}

	ver := s.getLatestServiceabilityVersion(ctx, s.db)
	serviceable, reason, _, route := s.evaluateServiceability(ctx, s.db, *req.Origin, originType, originNodeID, st, earliest, deadline, 1)

	resp := map[string]any{
		"serviceable":           serviceable,
		"reason":                reason,
		"serviceabilityVersion": ver,
	}
	if serviceable && route != nil {
		resp["targetLaboratoryId"] = route.TargetLaboratoryID.String()
		resp["estimatedArrivalAt"] = formatTimeISO(route.EstimatedDeliveryAt)
	}
	writeData(w, 200, resp)
}

