func (s *Server) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	var req struct {
		Username *string `json:"username"`
		Password *string `json:"password"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.Username == nil || req.Password == nil || *req.Username == "" || *req.Password == "" {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}

	var userID uuid.UUID
	var pwdHash string
	var rolesB []byte
	var active bool
	err := s.db.QueryRow(ctx, `
		SELECT user_id, password_hash, roles, active
		FROM users WHERE username = $1
	`, *req.Username).Scan(&userID, &pwdHash, &rolesB, &active)
	if err != nil || !active || pwdHash != hashPassword(*req.Password) {
		s.recordAudit(ctx, s.db, *req.Username, "none", "authenticate_user", "user", *req.Username, false, time.Now().UTC(), map[string]any{"username": *req.Username})
		writeError(w, 401, "invalid_credentials", "Invalid username or password")
		return
	}

	var roles []string
	_ = json.Unmarshal(rolesB, &roles)
	if roles == nil {
		roles = []string{}
	}

	activeRole := ""
	roleSelected := false
	if len(roles) == 1 {
		activeRole = roles[0]
		roleSelected = true
	}

	tokBytes := make([]byte, 24)
	_, _ = rand.Read(tokBytes)
	sessionToken := hex.EncodeToString(tokBytes)

	_, err = s.db.Exec(ctx, `
		INSERT INTO sessions (token, user_id, active_role, role_selected)
		VALUES ($1, $2, $3, $4)
	`, sessionToken, userID, activeRole, roleSelected)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to create session")
		return
	}

	s.recordAudit(ctx, s.db, userID.String(), activeRole, "authenticate_user", "user", userID.String(), true, time.Now().UTC(), map[string]any{"username": *req.Username})

	writeData(w, 200, map[string]any{
		"sessionToken": sessionToken,
		"userId":       userID.String(),
		"roles":        roles,
		"activeRole":   activeRole,
