func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "create_connection", "administrator")
	if !ok {
		return
	}

	var req struct {
		FromLocationID *string  `json:"fromLocationId"`
		ToLocationID   *string  `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.FromLocationID == nil || req.ToLocationID == nil || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	fromID, err1 := uuid.Parse(*req.FromLocationID)
	toID, err2 := uuid.Parse(*req.ToLocationID)
	if err1 != nil || err2 != nil || fromID == toID || *req.TravelMinutes < 1 || *req.CostUnits < 0 {
		writeError(w, 400, "invalid_connection", "Invalid connection parameters")
		return
	}

	var cnt int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM locations WHERE location_id IN ($1, $2)`, fromID, toID).Scan(&cnt)
	if cnt < 2 {
		writeError(w, 400, "invalid_connection", "Locations not found")
		return
	}

	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}
	cooledCap := 0
	if cooled {
		cooledCap = 50
	}

	connID := uuid.New()
	_, err := s.db.Exec(ctx, `
		INSERT INTO connections (
			connection_id, from_location_id, to_location_id, travel_minutes, cost_units,
			cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		) VALUES ($1, $2, $3, $4, $5, $6, $7, 50, 0, $8, 0)
	`, connID, fromID, toID, *req.TravelMinutes, *req.CostUnits, cooled, *req.Active, cooledCap)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to create connection")
		return
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
