	}

	if auth.AssignedLocationID == nil || *auth.AssignedLocationID != labID {
		s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_laboratory_exception", "sample", sampleID.String(), false, observedAt, map[string]any{"reason": "wrong_laboratory_operator"})
		writeError(w, 403, "wrong_laboratory_operator", "Operator is not assigned to this laboratory")
		return
	}

	var labExists int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM locations WHERE location_id = $1`, labID).Scan(&labExists)
	if labExists == 0 {
		writeError(w, 404, "not_found", "Laboratory not found")
		return
	}

	var activeJourneyID, targetLabID *uuid.UUID
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `SELECT active_journey_id, target_laboratory_id, sealed_at FROM samples WHERE sample_id = $1`, sampleID).Scan(&activeJourneyID, &targetLabID, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	if targetLabID != nil && *targetLabID != labID {
		writeError(w, 409, "wrong_laboratory", "Sample is not targeted to this laboratory")
		return
	}
	if sealedAt != nil && observedAt.Before(*sealedAt) {
		writeError(w, 409, "invalid_exception_time", "Exception time precedes sample sealing")
		return
	}

	excID := uuid.New()
	excMap := map[string]any{
		"exceptionId":  excID.String(),
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"reason":       *req.Reason,
		"observedAt":   formatTimeISO(observedAt),
	}
	excB, _ := json.Marshal(excMap)

	_, err = s.db.Exec(ctx, `UPDATE samples SET status = 'exception', exception_data = $1 WHERE sample_id = $2`, excB, sampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to record laboratory exception")
		return
	}
	_, _ = s.db.Exec(ctx, `
		INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, observed_at, actor_id)
		VALUES ($1, $2, $3, $4, $5, $6)
	`, excID, sampleID, labID, *req.Reason, observedAt, auth.UserID)

	if activeJourneyID != nil {
		_ = s.releaseJourneyCapacity(ctx, s.db, *activeJourneyID, &sampleID)
		_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_laboratory_exception", "sample", sampleID.String(), true, observedAt, excMap)
	s.publishEvent(ctx, s.db, "laboratory_exception_recorded", "sample", sampleID.String(), excMap)

	resp := map[string]any{
		"exceptionId": excID.String(),
		"sampleId":    sampleID.String(),
		"status":      "exception",
		"reason":      *req.Reason,
	}
	s.saveIdempotency(ctx, "record_laboratory_exception", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "record_worker_location", "collection_professional", "delivery_partner")
	if !ok {
		return
	}

	var req struct {
		WorkerID   *string     `json:"workerId"`
		Coordinate *Coordinate `json:"coordinate"`
		RecordedAt *string     `json:"recordedAt"`
		Sequence   *int        `json:"sequence"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.WorkerID == nil || req.Coordinate == nil || req.RecordedAt == nil || req.Sequence == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	workerID, err := uuid.Parse(*req.WorkerID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid workerId")
		return
	}
	if !validateCoordinate(*req.Coordinate) {
		writeError(w, 400, "invalid_coordinate", "Invalid coordinate")
		return
	}
	if *req.Sequence < 1 {
		writeError(w, 400, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recordedAt, err := parseTimeISO(*req.RecordedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid recordedAt")
		return
	}

	if workerID != auth.UserID {
		writeError(w, 403, "forbidden", "Cannot record location for another worker")
		return
	}

	var prevSeq int
	var prevRec *time.Time
	err = s.db.QueryRow(ctx, `SELECT location_sequence, location_recorded_at FROM users WHERE user_id = $1`, workerID).Scan(&prevSeq, &prevRec)
	if err != nil {
		writeError(w, 404, "not_found", "Worker not found")
		return
	}

	if *req.Sequence <= prevSeq || (prevRec != nil && recordedAt.Before(*prevRec)) {
		writeError(w, 409, "stale_location", "Location update is older than or equal to current sequence/timestamp")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE users
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
		WHERE user_id = $5
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, *req.Sequence, workerID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update worker location")
		return
	}

	// Also update samples currently held by this worker
	_, _ = s.db.Exec(ctx, `
		UPDATE samples
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
		WHERE current_holder_id = $4 AND status NOT IN ('received', 'cancelled', 'expired')
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, workerID)

	stale := isLocationStale(&recordedAt, time.Now().UTC())

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_worker_location", "user", workerID.String(), true, recordedAt, map[string]any{
		"coordinate": *req.Coordinate,
		"sequence":   *req.Sequence,
		"stale":      stale,
	})
	s.publishEvent(ctx, s.db, "worker_location_updated", "user", workerID.String(), map[string]any{
		"workerId":   workerID.String(),
		"coordinate": *req.Coordinate,
		"recordedAt": formatTimeISO(recordedAt),
		"sequence":   *req.Sequence,
		"stale":      stale,
	})

	writeData(w, 200, map[string]any{
		"workerId":   workerID.String(),
		"coordinate": *req.Coordinate,
		"recordedAt": formatTimeISO(recordedAt),
		"sequence":   *req.Sequence,
		"stale":      stale,
	})
}

