package main

import (
        "context"
        "encoding/json"
        "fmt"
        "net/http"
        "strings"
        "time"

        "github.com/google/uuid"
)

func (s *Server) handleReadSampleStatus(w http.ResponseWriter, r *http.Request) {
        if r.Method != http.MethodPost {
                writeError(w, 405, "method_not_allowed", "Method not allowed")
                return
        }
        ctx := r.Context()
        auth, ok := s.requireRole(ctx, w, r, "read_sample_status", "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
        if !ok {
                return
        }

        var req struct {
                SampleID *string `json:"sampleId"`
        }
        if _, err := decodeStrictJSON(r, &req, false); err != nil || req.SampleID == nil {
                writeError(w, 400, "invalid_json", "Invalid request body")
                return
        }
        sampleID, err := uuid.Parse(*req.SampleID)
        if err != nil {
                writeError(w, 400, "invalid_json", "Invalid sampleId")
                return
        }

        _ = s.expireTimedOutOffers(ctx, s.db, time.Now().UTC())

        var requesterID, sampleTypeID uuid.UUID
        var activeJourneyID, targetLabID, currentHolderID, originNodeID *uuid.UUID
        var status, container string
        var sealed bool
        var earliest, latest, deadline time.Time
        var lastLat, lastLng, obsTemp *float64
        var lastLocAt, lastUpdatedAt *time.Time
        var obsContainer *string
        var excDataB, activeAssignB, replPlanB []byte

        err = s.db.QueryRow(ctx, `
                SELECT requester_id, sample_type_id, status, sealed, current_holder_id,
                       active_journey_id, target_laboratory_id, origin_node_id,
                       earliest_collection_at, latest_collection_at, delivery_deadline,
                       last_lat, last_lng, last_loc_at, last_updated_at,
                       observed_temp_c, observed_container, container_type,
                       exception_data, active_assignment_ids, active_replacement_plan_ids
                FROM samples WHERE sample_id = $1
        `, sampleID).Scan(
                &requesterID, &sampleTypeID, &status, &sealed, &currentHolderID,
                &activeJourneyID, &targetLabID, &originNodeID,
                &earliest, &latest, &deadline,
                &lastLat, &lastLng, &lastLocAt, &lastUpdatedAt,
                &obsTemp, &obsContainer, &container,
                &excDataB, &activeAssignB, &replPlanB,
        )
        if err != nil {
                writeError(w, 404, "not_found", "Sample not found")
                return
        }

        // Enforce RBAC data access
        if auth.ActiveRole == "requester" && requesterID != auth.UserID {
                writeError(w, 403, "forbidden", "Sample does not belong to requester")
                return
        }
        if auth.ActiveRole == "collection_professional" || auth.ActiveRole == "delivery_partner" || auth.ActiveRole == "node_handler" || auth.ActiveRole == "laboratory_team" {
                allowed := false
                if currentHolderID != nil && *currentHolderID == auth.UserID {
                        allowed = true
                }
                if !allowed {
                        var cnt int
                        _ = s.db.QueryRow(ctx, `
                                SELECT COUNT(*) FROM assignments
                                WHERE sample_id = $1 AND (worker_id = $2 OR offered_to_worker_id = $2
                                      OR ($3 = 'node_handler' AND node_id IS NOT NULL AND node_id = $4)
                                      OR ($3 = 'laboratory_team' AND laboratory_id IS NOT NULL AND laboratory_id = $4))
                        `, sampleID, auth.UserID, auth.ActiveRole, auth.AssignedLocationID).Scan(&cnt)
                        if cnt > 0 {
                                allowed = true
                        }
                }
                if !allowed && auth.AssignedLocationID != nil {
                        if (originNodeID != nil && *originNodeID == *auth.AssignedLocationID) || (targetLabID != nil && *targetLabID == *auth.AssignedLocationID) {
                                allowed = true
                        }
                }
                if !allowed {
                        writeError(w, 403, "forbidden", "Forbidden access to sample")
                        return
                }
        }

        // Calculate route stops progress
        totalStops := 0
        completedStops := 0
        routeNames := []string{}
        if activeJourneyID != nil {
                rows, err := s.db.Query(ctx, `
                        SELECT js.completed_at, l.name
                        FROM journey_stops js
                        LEFT JOIN locations l ON l.location_id = js.location_id
                        WHERE js.journey_id = $1
                        ORDER BY js.sequence ASC
                `, *activeJourneyID)
                if err == nil {
                        for rows.Next() {
                                var compAt *time.Time
                                var lName *string
                                if err := rows.Scan(&compAt, &lName); err == nil {
                                        totalStops++
                                        if compAt != nil {
                                                completedStops++
                                        }
                                        if lName != nil {
                                                routeNames = append(routeNames, *lName)
                                        }
                                }
                        }
                        rows.Close()
                }
        }
        if totalStops == 0 {
                totalStops = 1
        }
        if status == "received" {
                completedStops = totalStops
        }
        progressPercent := float64(completedStops) * 100.0 / float64(totalStops)
        if status == "received" {
                progressPercent = 100.0
        } else if status == "in_transit" && progressPercent < 50.0 {
                progressPercent = 50.0
        } else if status == "collected" && progressPercent < 25.0 {
                progressPercent = 25.0
        }

        routeSummary := strings.Join(routeNames, " -> ")
        if routeSummary == "" {
                routeSummary = "Direct Route"
        }

        // Timeline
        timeline := []SampleTimelineEntry{}
        tRows, err := s.db.Query(ctx, `
                SELECT status, occurred_at, actor_id, location_id, note
                FROM sample_timeline
                WHERE sample_id = $1
