func (s *Server) handleReadEventFeed(w http.ResponseWriter, r *http.Request) {
        if r.Method != http.MethodPost {
                writeError(w, 405, "method_not_allowed", "Method not allowed")
                return
        }
        ctx := r.Context()
        _, ok := s.requireRole(ctx, w, r, "read_event_feed")
        if !ok {
                return
        }

        var req struct {
                AfterSequence *int `json:"afterSequence"`
                Limit         *int `json:"limit"`
        }
        if _, err := decodeStrictJSON(r, &req, true); err != nil {
                writeError(w, 400, "invalid_json", "Invalid request body")
                return
        }

        afterSeq := 0
        if req.AfterSequence != nil {
                if *req.AfterSequence < 0 {
                        writeError(w, 400, "invalid_cursor", "afterSequence must be >= 0")
                        return
                }
                afterSeq = *req.AfterSequence
        }
        limit := 100
        if req.Limit != nil {
                if *req.Limit < 1 || *req.Limit > 500 {
                        writeError(w, 400, "invalid_limit", "limit must be between 1 and 500")
                        return
                }
                limit = *req.Limit
        }

        rows, err := s.db.Query(ctx, `
                SELECT sequence, event_type, entity_type, entity_id, occurred_at, payload
                FROM events
                WHERE sequence > $1
                ORDER BY sequence ASC
                LIMIT $2
        `, afterSeq, limit)
        if err != nil {
                writeError(w, 500, "internal_error", "Failed to read events")
                return
        }
        defer rows.Close()

        events := []EventItem{}
        cursor := afterSeq
        for rows.Next() {
                var seq int
                var evType, entType, entID string
                var occ time.Time
                var payB []byte
                if err := rows.Scan(&seq, &evType, &entType, &entID, &occ, &payB); err == nil {
                        var payload map[string]any
                        _ = json.Unmarshal(payB, &payload)
                        if payload == nil {
                                payload = map[string]any{}
                        }
                        events = append(events, EventItem{
                                Sequence:   seq,
                                EventType:  evType,
                                EntityType: entType,
                                EntityID:   entID,
                                OccurredAt: formatTimeISO(occ),
                                Payload:    payload,
                        })
                        if seq > cursor {
                                cursor = seq
                        }
                }
        }

        writeData(w, 200, EventFeed{
                Cursor: cursor,
                Events: events,
        })
}

func (s *Server) handleStreamEvents(w http.ResponseWriter, r *http.Request) {
        if r.Method != http.MethodGet {
                writeError(w, 405, "method_not_allowed", "Method not allowed")
                return
        }
        ctx := r.Context()
        _, ok := s.requireRole(ctx, w, r, "stream_events")
        if !ok {
                return
        }

        w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
        w.Header().Set("Cache-Control", "no-cache")
        w.Header().Set("Connection", "keep-alive")
        w.WriteHeader(http.StatusOK)

        // Send latest event or initial ready event immediately
        var seq int
        var evType, entType, entID string
        var occ time.Time
        var payB []byte
        err := s.db.QueryRow(ctx, `
                SELECT sequence, event_type, entity_type, entity_id, occurred_at, payload
                FROM events ORDER BY sequence DESC LIMIT 1
        `).Scan(&seq, &evType, &entType, &entID, &occ, &payB)
        if err == nil {
                ev := map[string]any{
                        "sequence":   seq,
                        "eventType":  evType,
                        "entityType": entType,
                        "entityId":   entID,
                        "occurredAt": formatTimeISO(occ),
                }
                b, _ := json.Marshal(ev)
                _, _ = fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", seq, evType, string(b))
        } else {
                _, _ = fmt.Fprintf(w, "id: 0\nevent: connected\ndata: {\"status\":\"connected\"}\n\n")
        }

        if f, ok := w.(http.Flusher); ok {
                f.Flush()
        }
}

