package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
)

func (s *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "read_journey_plan", "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		JourneyID *string `json:"journeyId"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.JourneyID == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	journeyID, err := uuid.Parse(*req.JourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid journeyId")
		return
	}

	jp, err := s.buildJourneyPlan(ctx, s.db, journeyID, 0)
	if err != nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}

	if auth.ActiveRole == "administrator" || auth.ActiveRole == "dispatcher" {
		writeData(w, 200, jp)
		return
	}

	if auth.ActiveRole == "requester" {
		// Verify requester owns at least one sample in the journey
		var ownCount int
		_ = s.db.QueryRow(ctx, `
			SELECT COUNT(*) FROM samples
			WHERE sample_id::text = ANY($1) AND requester_id = $2
		`, jp.SampleIDs, auth.UserID).Scan(&ownCount)
		if ownCount == 0 {
			writeError(w, 403, "forbidden", "Journey does not belong to requester")
			return
		}
		reqLegs := []map[string]any{}
		for _, l := range jp.Legs {
			m := map[string]any{
				"sequence": l.Sequence,
				"status":   l.Status,
			}
			if l.FromLocationID != nil {
				m["fromLocationId"] = *l.FromLocationID
			}
			if l.ToLocationID != nil {
				m["toLocationId"] = *l.ToLocationID
			}
			if l.SampleID != nil {
				m["sampleId"] = *l.SampleID
			}
			reqLegs = append(reqLegs, m)
		}
		rjp := RequesterJourneyPlan{
			JourneyID:           jp.JourneyID,
			ParentJourneyID:     jp.ParentJourneyID,
			PlanVersion:         &jp.PlanVersion,
			RouteMode:           &jp.RouteMode,
			Status:              &jp.Status,
			EstimatedDeliveryAt: &jp.EstimatedDeliveryAt,
			TotalCostUnits:      &jp.TotalCostUnits,
			SampleIDs:           jp.SampleIDs,
			OrderedStops:        jp.OrderedStops,
			Legs:                reqLegs,
		}
		writeData(w, 200, rjp)
		return
	}

	// Worker roles: collection_professional, delivery_partner, node_handler, laboratory_team
	rows, err := s.db.Query(ctx, `
		SELECT assignment_id, sample_id, kind, sequence, status, from_location_id, to_location_id
		FROM assignments
		WHERE journey_id = $1 AND active = TRUE
		  AND (worker_id = $2 OR offered_to_worker_id = $2
		       OR ($3 = 'node_handler' AND node_id IS NOT NULL AND node_id = $4)
		       OR ($3 = 'laboratory_team' AND laboratory_id IS NOT NULL AND laboratory_id = $4))
		ORDER BY sequence ASC
	`, journeyID, auth.UserID, auth.ActiveRole, auth.AssignedLocationID)
	if err != nil {
		writeError(w, 403, "forbidden", "Forbidden")
		return
	}
	defer rows.Close()

	myAssignIDs := []string{}
	myLegs := []JourneyLeg{}
	locFilter := make(map[string]bool)
	myCollIDs := []string{}
	myNodeIDs := []string{}
	myLabIDs := []string{}
	wStr := auth.UserID.String()

	for rows.Next() {
		var aID, sID uuid.UUID
		var kind, aStatus string
		var seq int
		var fromLoc, toLoc *uuid.UUID
		if err := rows.Scan(&aID, &sID, &kind, &seq, &aStatus, &fromLoc, &toLoc); err == nil {
			aStr := aID.String()
			sStr := sID.String()
			myAssignIDs = append(myAssignIDs, aStr)
			switch kind {
			case "collection":
				myCollIDs = append(myCollIDs, aStr)
			case "node":
				myNodeIDs = append(myNodeIDs, aStr)
			case "laboratory":
				myLabIDs = append(myLabIDs, aStr)
			}
			jl := JourneyLeg{
				AssignmentID:  aStr,
				AssignmentSnk: aStr,
				Sequence:      seq,
				Status:        aStatus,
				WorkerID:      &wStr,
				WorkerSnk:     &wStr,
				SampleID:      &sStr,
			}
			if fromLoc != nil {
				fl := fromLoc.String()
				jl.FromLocationID = &fl
				jl.FromLocSnk = &fl
				locFilter[fl] = true
			}
			if toLoc != nil {
				tl := toLoc.String()
				jl.ToLocationID = &tl
				jl.ToLocSnk = &tl
				locFilter[tl] = true
			}
			myLegs = append(myLegs, jl)
		}
	}

	if len(myAssignIDs) == 0 {
		writeError(w, 403, "forbidden", "No assignments on this journey for worker")
		return
	}

	myStops := []JourneyStop{}
	for _, st := range jp.OrderedStops {
		if locFilter[st.LocationID] {
			myStops = append(myStops, st)
		}
	}
	if len(myStops) == 0 {
		myStops = jp.OrderedStops
	}

	wjp := WorkerJourneyPlan{
		JourneyID:               jp.JourneyID,
		ParentJourneyID:         jp.ParentJourneyID,
		PlanVersion:             jp.PlanVersion,
		RouteMode:               jp.RouteMode,
		Status:                  jp.Status,
		EstimatedDeliveryAt:     &jp.EstimatedDeliveryAt,
		Scope:                   "assigned_legs",
		AssignmentIDs:           myAssignIDs,
		SampleIDs:               jp.SampleIDs,
		Legs:                    myLegs,
		OrderedStops:            myStops,
		CollectionAssignmentIDs: myCollIDs,
		NodeAssignmentIDs:       myNodeIDs,
		LaboratoryAssignmentIDs: myLabIDs,
		AssignedWorkerIDs:       []string{wStr},
	}
	writeData(w, 200, wjp)
}

func (s *Server) replanJourneyInternal(ctx context.Context, q DBTx, journeyID uuid.UUID, actorID string, actorRole string, reason string) (string, *uuid.UUID, *JourneyPlan, []string, error) {
	var sampleIDsB []byte
	var jStatus string
	err := q.QueryRow(ctx, `SELECT sample_ids, status FROM journeys WHERE journey_id = $1`, journeyID).Scan(&sampleIDsB, &jStatus)
	if err != nil {
		return "not_required", nil, nil, nil, err
	}
	var sampleIDs []string
	_ = json.Unmarshal(sampleIDsB, &sampleIDs)
	if len(sampleIDs) == 0 {
		return "not_required", nil, nil, nil, nil
	}

	firstSampleID, err := uuid.Parse(sampleIDs[0])
	if err != nil {
		return "not_required", nil, nil, nil, err
	}

	var stID uuid.UUID
	var origLat, origLng float64
	var origType string
	var origNodeID, currentHolderID *uuid.UUID
	var sealed bool
	var earliest, deadline time.Time
	err = q.QueryRow(ctx, `
		SELECT sample_type_id, origin_lat, origin_lng, origin_type, origin_node_id,
		       current_holder_id, sealed, earliest_collection_at, delivery_deadline
		FROM samples WHERE sample_id = $1
	`, firstSampleID).Scan(&stID, &origLat, &origLng, &origType, &origNodeID, &currentHolderID, &sealed, &earliest, &deadline)
	if err != nil {
		return "not_required", nil, nil, nil, err
	}

	st, err := s.loadSampleType(ctx, q, stID)
	if err != nil {
		return "not_required", nil, nil, nil, err
	}

	// Determine current node where sample is located based on completed stops/legs
	var currentLocID *uuid.UUID
	var lastCompTime *time.Time
	_ = q.QueryRow(ctx, `
		SELECT to_location_id, completed_at
		FROM assignments
		WHERE journey_id = $1 AND status IN ('completed', 'delivered') AND to_location_id IS NOT NULL
		ORDER BY sequence DESC LIMIT 1
	`, journeyID).Scan(&currentLocID, &lastCompTime)

	if currentLocID == nil {
		_ = q.QueryRow(ctx, `
			SELECT location_id, completed_at
			FROM journey_stops
			WHERE journey_id = $1 AND completed_at IS NOT NULL
			ORDER BY sequence DESC LIMIT 1
		`, journeyID).Scan(&currentLocID, &lastCompTime)
	}

	// Release old journey's active capacity reservations so they don't block replacement route
	_ = s.releaseJourneyCapacity(ctx, q, journeyID, nil)

	// Cancel unfinished assignments on old journey (completed work is preserved!)
	_, _ = q.Exec(ctx, `
		UPDATE assignments
		SET status = 'cancelled', active = FALSE
		WHERE journey_id = $1 AND status NOT IN ('completed', 'delivered')
	`, journeyID)

	startTime := earliest
	if lastCompTime != nil && lastCompTime.After(startTime) {
		startTime = *lastCompTime
	}

	startOrigin := Coordinate{Latitude: origLat, Longitude: origLng}
	startOriginType := origType
	startNode := origNodeID
	if currentLocID != nil {
		var lLat, lLng float64
		var lActive bool
		if err := q.QueryRow(ctx, `SELECT latitude, longitude, active FROM locations WHERE location_id = $1`, *currentLocID).Scan(&lLat, &lLng, &lActive); err == nil && lActive {
			startOrigin = Coordinate{Latitude: lLat, Longitude: lLng}
			startOriginType = "node"
			startNode = currentLocID
		}
	}

	serviceable, _, _, route := s.evaluateServiceability(ctx, q, startOrigin, startOriginType, startNode, st, startTime, deadline, len(sampleIDs))
	if !serviceable || route == nil {
		// Mark journey and samples as expired
		_, _ = q.Exec(ctx, `UPDATE journeys SET status = 'expired', replan_status = 'expired', plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)
		for _, sidStr := range sampleIDs {
			if sid, err := uuid.Parse(sidStr); err == nil {
				_, _ = q.Exec(ctx, `UPDATE samples SET status = 'expired', active_assignment_ids = '[]'::jsonb WHERE sample_id = $1`, sid)
				s.recordAudit(ctx, q, actorID, actorRole, "sample_expired", "sample", sidStr, true, time.Now().UTC(), map[string]any{"journeyId": journeyID.String(), "reason": reason})
			}
		}
		return "expired", nil, nil, sampleIDs, nil
	}

	newJourneyID, activeAssigns, missingWorker, err := s.createJourneyForSample(ctx, q, firstSampleID, st, route, startTime, sealed, currentHolderID, &journeyID)
	if err != nil {
		_, _ = q.Exec(ctx, `UPDATE journeys SET status = 'expired', replan_status = 'expired', plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)
		for _, sidStr := range sampleIDs {
			if sid, err := uuid.Parse(sidStr); err == nil {
				_, _ = q.Exec(ctx, `UPDATE samples SET status = 'expired', active_assignment_ids = '[]'::jsonb WHERE sample_id = $1`, sid)
			}
		}
		return "expired", nil, nil, sampleIDs, nil
	}

	// Copy completed stops from old journey onto newJourneyID if any existed at different locations
	replanStatus := "replaced"
	if missingWorker {
		replanStatus = "exception"
	}

	// Update sample_ids on newJourneyID if batched
	if len(sampleIDs) > 1 {
		sB, _ := json.Marshal(sampleIDs)
		_, _ = q.Exec(ctx, `UPDATE journeys SET sample_ids = $1, route_mode = 'batched', capacity_used = $2 WHERE journey_id = $3`, sB, len(sampleIDs), newJourneyID)
	}
	_, _ = q.Exec(ctx, `UPDATE journeys SET replan_status = $1 WHERE journey_id = $2`, replanStatus, newJourneyID)

	// Mark old journey replaced
	_, _ = q.Exec(ctx, `
		UPDATE journeys
		SET status = 'replaced', replan_status = $1, replacement_journey_id = $2, plan_version = plan_version + 1
		WHERE journey_id = $3
	`, replanStatus, newJourneyID, journeyID)

	actAssignB, _ := json.Marshal(activeAssigns)
	replPlanB, _ := json.Marshal([]string{newJourneyID.String()})

	for _, sidStr := range sampleIDs {
		if sid, err := uuid.Parse(sidStr); err == nil {
			if missingWorker {
				excID := uuid.New()
				excMap := map[string]any{
					"exceptionId": excID.String(),
					"sampleId":    sidStr,
					"reason":      "no_qualified_worker_available",
					"observedAt":  formatTimeISO(time.Now().UTC()),
				}
				excB, _ := json.Marshal(excMap)
				_, _ = q.Exec(ctx, `
					UPDATE samples
					SET active_journey_id = $1, target_laboratory_id = $2, active_assignment_ids = $3,
					    active_replacement_plan_ids = $4, status = 'exception', exception_data = $5
					WHERE sample_id = $6
				`, newJourneyID, route.TargetLaboratoryID, actAssignB, replPlanB, excB, sid)
			} else {
				_, _ = q.Exec(ctx, `
					UPDATE samples
					SET active_journey_id = $1, target_laboratory_id = $2, active_assignment_ids = $3,
					    active_replacement_plan_ids = $4
					WHERE sample_id = $5
				`, newJourneyID, route.TargetLaboratoryID, actAssignB, replPlanB, sid)
			}
			s.recordAudit(ctx, q, actorID, actorRole, "journey_replanned", "sample", sidStr, true, time.Now().UTC(), map[string]any{
				"oldJourneyId":       journeyID.String(),
				"replacementPlanId":  newJourneyID.String(),
				"replanStatus":       replanStatus,
				"currentHolderSaved": currentHolderID,
			})
		}
	}

	newPlan, _ := s.buildJourneyPlan(ctx, q, newJourneyID, 0)
	return replanStatus, &newJourneyID, newPlan, sampleIDs, nil
}

func (s *Server) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "reroute_journey", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		JourneyID           *string `json:"journeyId"`
		ExpectedPlanVersion *int    `json:"expectedPlanVersion"`
		Reason              *string `json:"reason"`
		IdempotencyKey      *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.Reason == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, 400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "reroute_journey", idemKey, rawBody); done {
		return
	}

	journeyID, err := uuid.Parse(*req.JourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid journeyId")
		return
	}

	var curVer int
	var curStatus string
	err = s.db.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE journey_id = $1`, journeyID).Scan(&curVer, &curStatus)
	if err != nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}
	if curVer != *req.ExpectedPlanVersion {
		writeError(w, 409, "stale_plan", "Plan version mismatch")
		return
	}
	if curStatus == "cancelled" || curStatus == "completed" || curStatus == "replaced" || curStatus == "expired" {
		writeError(w, 409, "inactive_plan", "Journey plan is no longer active")
		return
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to start transaction")
		return
	}
	defer tx.Rollback(ctx)

	replanStatus, newJourneyID, newPlan, _, err := s.replanJourneyInternal(ctx, tx, journeyID, auth.UserID.String(), auth.ActiveRole, *req.Reason)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to reroute journey")
		return
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, tx)
	s.recordAudit(ctx, tx, auth.UserID.String(), auth.ActiveRole, "reroute_journey", "journey", journeyID.String(), true, time.Now().UTC(), map[string]any{
		"journeyId":         journeyID.String(),
		"replanStatus":      replanStatus,
		"replacementPlanId": newJourneyID,
		"reason":            *req.Reason,
	})

	if err := tx.Commit(ctx); err != nil {
		writeError(w, 500, "internal_error", "Failed to commit transaction")
		return
	}

	s.publishEvent(ctx, s.db, "journey_rerouted", "journey", journeyID.String(), map[string]any{
		"journeyId":         journeyID.String(),
		"replanStatus":      replanStatus,
		"replacementPlanId": newJourneyID,
	})

	resp := map[string]any{
		"journeyId":    journeyID.String(),
		"replanStatus": replanStatus,
	}
	if newJourneyID != nil {
		resp["replacementPlanId"] = newJourneyID.String()
	}
	if newPlan != nil {
		resp["replacementJourney"] = newPlan
	}
	s.saveIdempotency(ctx, "reroute_journey", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "report_disruption", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		ResourceType   *string `json:"resourceType"`
		ResourceID     *string `json:"resourceId"`
		Reason         *string `json:"reason"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.ResourceType == nil || req.ResourceID == nil || req.Reason == nil || req.OccurredAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "report_disruption", idemKey, rawBody); done {
		return
	}

	rType := *req.ResourceType
	validTypes := []string{"location", "node", "laboratory", "connection", "route", "worker", "capacity"}
	if !hasString(validTypes, rType) {
		writeError(w, 400, "invalid_resource_type", "Invalid resourceType")
		return
	}
	resID, err := uuid.Parse(*req.ResourceID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid resourceId")
		return
	}
	occurredAt, err := parseTimeISO(*req.OccurredAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid occurredAt")
		return
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to start transaction")
		return
	}
	defer tx.Rollback(ctx)

	affectedJourneySet := make(map[uuid.UUID]bool)
	affectedSamples := []string{}
	replacementPlans := []string{}
	overallStatus := "not_required"

	switch rType {
	case "location", "node", "laboratory":
		tag, err := tx.Exec(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, resID)
		if err != nil || tag.RowsAffected() == 0 {
			writeError(w, 404, "not_found", "Location not found")
			return
		}
		jRows, err := tx.Query(ctx, `
			SELECT DISTINCT j.journey_id
			FROM journeys j
			JOIN journey_stops js ON js.journey_id = j.journey_id
			WHERE js.location_id = $1 AND js.completed_at IS NULL
			  AND j.status IN ('planned', 'in_progress', 'active')
		`, resID)
		if err == nil {
			for jRows.Next() {
				var jid uuid.UUID
				if err := jRows.Scan(&jid); err == nil {
					affectedJourneySet[jid] = true
				}
			}
			jRows.Close()
		}

	case "connection", "route":
		tag, err := tx.Exec(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, resID)
		if err != nil || tag.RowsAffected() == 0 {
			writeError(w, 404, "not_found", "Connection not found")
			return
		}
		jRows, err := tx.Query(ctx, `
			SELECT DISTINCT j.journey_id
			FROM journeys j
			JOIN assignments a ON a.journey_id = j.journey_id
			WHERE a.connection_id = $1 AND a.active = TRUE AND a.status NOT IN ('completed', 'delivered', 'cancelled')
			  AND j.status IN ('planned', 'in_progress', 'active')
		`, resID)
		if err == nil {
			for jRows.Next() {
				var jid uuid.UUID
				if err := jRows.Scan(&jid); err == nil {
					affectedJourneySet[jid] = true
				}
			}
			jRows.Close()
		}

	case "capacity":
		tag1, _ := tx.Exec(ctx, `UPDATE locations SET capacity_units = reserved_units, cooled_capacity_units = cooled_reserved_units WHERE location_id = $1`, resID)
		tag2, _ := tx.Exec(ctx, `UPDATE connections SET capacity_units = reserved_units, cooled_capacity_units = cooled_reserved_units WHERE connection_id = $1`, resID)
		if tag1.RowsAffected() == 0 && tag2.RowsAffected() == 0 {
			writeError(w, 404, "not_found", "Capacity resource not found")
			return
		}
		jRows, err := tx.Query(ctx, `
			SELECT DISTINCT j.journey_id
			FROM journeys j
			JOIN capacity_reservations cr ON cr.journey_id = j.journey_id
			WHERE cr.resource_id = $1 AND cr.active = TRUE
			  AND j.status IN ('planned', 'in_progress', 'active')
		`, resID)
		if err == nil {
			for jRows.Next() {
				var jid uuid.UUID
				if err := jRows.Scan(&jid); err == nil {
					affectedJourneySet[jid] = true
				}
			}
			jRows.Close()
		}

	case "worker":
		tag, err := tx.Exec(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, resID)
		if err != nil || tag.RowsAffected() == 0 {
			writeError(w, 404, "not_found", "Worker not found")
			return
		}
		// Find unfinished assignments for this worker
		aRows, err := tx.Query(ctx, `
			SELECT assignment_id, journey_id, sample_id, kind, node_id, laboratory_id, expected_sample_type_id, declined_by
			FROM assignments
			WHERE (worker_id = $1 OR offered_to_worker_id = $1)
			  AND active = TRUE AND status NOT IN ('completed', 'delivered', 'cancelled')
		`, resID)
		type wAssign struct {
			aID      uuid.UUID
			jID      uuid.UUID
			sID      uuid.UUID
			kind     string
			locID    *uuid.UUID
			stID     *uuid.UUID
			declined []string
		}
		var wAssigns []wAssign
		if err == nil {
			for aRows.Next() {
				var aID, jID, sID uuid.UUID
				var kind string
				var nID, lID, stID *uuid.UUID
				var declB []byte
				if err := aRows.Scan(&aID, &jID, &sID, &kind, &nID, &lID, &stID, &declB); err == nil {
					var decl []string
					_ = json.Unmarshal(declB, &decl)
					if !hasString(decl, resID.String()) {
						decl = append(decl, resID.String())
					}
					loc := nID
					if loc == nil {
						loc = lID
					}
					wAssigns = append(wAssigns, wAssign{aID: aID, jID: jID, sID: sID, kind: kind, locID: loc, stID: stID, declined: decl})
				}
			}
			aRows.Close()
		}
		for _, wa := range wAssigns {
			affectedSamples = append(affectedSamples, wa.sID.String())
			var st *dbSampleType
			if wa.stID != nil {
				st, _ = s.loadSampleType(ctx, tx, *wa.stID)
			}
			nextW, _ := s.findEligibleWorkerForAssignment(ctx, tx, wa.kind, st, wa.locID, wa.declined, occurredAt, nil)
			declB, _ := json.Marshal(wa.declined)
			if nextW != nil {
				_, _ = tx.Exec(ctx, `
					UPDATE assignments SET worker_id = NULL, offered_to_worker_id = $1, status = 'pending', declined_by = $2
					WHERE assignment_id = $3
				`, *nextW, declB, wa.aID)
				_, _ = tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1, replan_status = 'replaced' WHERE journey_id = $1`, wa.jID)
				replacementPlans = append(replacementPlans, wa.jID.String())
				if overallStatus == "not_required" {
					overallStatus = "replaced"
				}
			} else {
				_, _ = tx.Exec(ctx, `
					UPDATE assignments SET worker_id = NULL, offered_to_worker_id = NULL, status = 'pending', declined_by = $1
					WHERE assignment_id = $2
				`, declB, wa.aID)
				excID := uuid.New()
				excMap := map[string]any{
					"exceptionId": excID.String(),
					"sampleId":    wa.sID.String(),
					"reason":      "no_qualified_worker_available",
					"observedAt":  formatTimeISO(occurredAt),
				}
				excB, _ := json.Marshal(excMap)
				_, _ = tx.Exec(ctx, `UPDATE samples SET status = 'exception', exception_data = $1 WHERE sample_id = $2`, excB, wa.sID)
				_, _ = tx.Exec(ctx, `
					INSERT INTO exceptions (exception_id, sample_id, reason, observed_at, actor_id)
					VALUES ($1, $2, 'no_qualified_worker_available', $3, $4)
				`, excID, wa.sID, occurredAt, auth.UserID)
				overallStatus = "exception"
			}
		}
	}

	for jid := range affectedJourneySet {
		repStatus, newJID, _, sIDs, err := s.replanJourneyInternal(ctx, tx, jid, auth.UserID.String(), auth.ActiveRole, *req.Reason)
		if err == nil {
			for _, sid := range sIDs {
				if !hasString(affectedSamples, sid) {
					affectedSamples = append(affectedSamples, sid)
				}
			}
			if newJID != nil {
				replacementPlans = append(replacementPlans, newJID.String())
			}
			if repStatus == "expired" {
				overallStatus = "expired"
			} else if repStatus == "exception" && overallStatus != "expired" {
				overallStatus = "exception"
			} else if repStatus == "replaced" && overallStatus == "not_required" {
				overallStatus = "replaced"
			}
		}
	}

	disruptionID := uuid.New()
	affB, _ := json.Marshal(affectedSamples)
	repB, _ := json.Marshal(replacementPlans)
	_, _ = tx.Exec(ctx, `
		INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
	`, disruptionID, rType, resID, *req.Reason, occurredAt, affB, repB, overallStatus)

	_ = s.recomputeServiceabilitySnapshot(ctx, tx)
	s.recordAudit(ctx, tx, auth.UserID.String(), auth.ActiveRole, "report_disruption", rType, resID.String(), true, occurredAt, map[string]any{
		"disruptionId":       disruptionID.String(),
		"resourceType":       rType,
		"resourceId":         resID.String(),
		"reason":             *req.Reason,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       overallStatus,
	})

	if err := tx.Commit(ctx); err != nil {
		writeError(w, 500, "internal_error", "Failed to commit disruption")
		return
	}

	s.publishEvent(ctx, s.db, "disruption_reported", rType, resID.String(), map[string]any{
		"disruptionId":       disruptionID.String(),
		"replanStatus":       overallStatus,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
	})

	resp := map[string]any{
		"disruptionId":       disruptionID.String(),
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       overallStatus,
	}
	s.saveIdempotency(ctx, "report_disruption", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "cancel_journey", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		JourneyID           *string `json:"journeyId"`
		ExpectedPlanVersion *int    `json:"expectedPlanVersion"`
		Reason              *string `json:"reason"`
		IdempotencyKey      *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.Reason == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, 400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "cancel_journey", idemKey, rawBody); done {
		return
	}

	journeyID, err := uuid.Parse(*req.JourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid journeyId")
		return
	}

	var curVer int
	var curStatus string
	var sampleIDsB []byte
	err = s.db.QueryRow(ctx, `SELECT plan_version, status, sample_ids FROM journeys WHERE journey_id = $1`, journeyID).Scan(&curVer, &curStatus, &sampleIDsB)
	if err != nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}
	if curVer != *req.ExpectedPlanVersion {
		writeError(w, 409, "stale_plan", "Plan version mismatch")
		return
	}
	if curStatus == "cancelled" || curStatus == "completed" || curStatus == "replaced" {
		writeError(w, 409, "inactive_plan", "Journey is already inactive")
		return
	}

	var sampleIDs []string
	_ = json.Unmarshal(sampleIDsB, &sampleIDs)
	if sampleIDs == nil {
		sampleIDs = []string{}
	}

	_, _ = s.db.Exec(ctx, `UPDATE journeys SET status = 'cancelled', plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)
	_, _ = s.db.Exec(ctx, `
		UPDATE assignments SET status = 'cancelled', active = FALSE
		WHERE journey_id = $1 AND status NOT IN ('completed', 'delivered')
	`, journeyID)
	_ = s.releaseJourneyCapacity(ctx, s.db, journeyID, nil)

	for _, sidStr := range sampleIDs {
		if sid, err := uuid.Parse(sidStr); err == nil {
			_, _ = s.db.Exec(ctx, `
				UPDATE samples SET status = 'cancelled', active_assignment_ids = '[]'::jsonb
				WHERE sample_id = $1 AND status NOT IN ('received')
			`, sid)
			s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "cancel_journey", "sample", sidStr, true, time.Now().UTC(), map[string]any{
				"journeyId": journeyID.String(),
				"reason":    *req.Reason,
			})
		}
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "cancel_journey", "journey", journeyID.String(), true, time.Now().UTC(), map[string]any{
		"journeyId": journeyID.String(),
		"reason":    *req.Reason,
		"sampleIds": sampleIDs,
	})
	s.publishEvent(ctx, s.db, "journey_cancelled", "journey", journeyID.String(), map[string]any{
		"journeyId": journeyID.String(),
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	})

	resp := map[string]any{
		"journeyId": journeyID.String(),
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	}
	s.saveIdempotency(ctx, "cancel_journey", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "merge_journeys", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		TargetJourneyID     *string  `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.TargetJourneyID == nil || req.ExpectedPlanVersion == nil || len(req.SourceJourneyIDs) == 0 {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, 400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "merge_journeys", idemKey, rawBody); done {
		return
	}

	targetJID, err := uuid.Parse(*req.TargetJourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid targetJourneyId")
		return
	}

	var curVer int
	var curStatus string
	var targetSamplesB []byte
	var estDel time.Time
	err = s.db.QueryRow(ctx, `SELECT plan_version, status, sample_ids, estimated_delivery_at FROM journeys WHERE journey_id = $1`, targetJID).Scan(&curVer, &curStatus, &targetSamplesB, &estDel)
	if err != nil {
		writeError(w, 404, "not_found", "Target journey not found")
		return
	}
	if curVer != *req.ExpectedPlanVersion {
		writeError(w, 409, "stale_plan", "Plan version mismatch")
		return
	}
	if curStatus == "cancelled" || curStatus == "completed" || curStatus == "replaced" || curStatus == "expired" {
		writeError(w, 409, "inactive_plan", "Target journey is inactive")
		return
	}

	var combinedSampleIDs []string
	_ = json.Unmarshal(targetSamplesB, &combinedSampleIDs)

	sourceUUIDs := []uuid.UUID{}
	for _, srcStr := range req.SourceJourneyIDs {
		srcID, err := uuid.Parse(srcStr)
		if err != nil {
			writeError(w, 400, "invalid_json", "Invalid sourceJourneyId")
			return
		}
		if srcID == targetJID {
			writeError(w, 409, "invalid_merge", "Cannot merge journey with itself")
			return
		}
		var sStatus string
		var sSamplesB []byte
		err = s.db.QueryRow(ctx, `SELECT status, sample_ids FROM journeys WHERE journey_id = $1`, srcID).Scan(&sStatus, &sSamplesB)
		if err != nil {
			writeError(w, 404, "not_found", "Source journey not found")
			return
		}
		if sStatus == "cancelled" || sStatus == "completed" || sStatus == "replaced" || sStatus == "expired" {
			writeError(w, 409, "inactive_plan", "Source journey is inactive")
			return
		}
		var sSamples []string
		_ = json.Unmarshal(sSamplesB, &sSamples)
		for _, sid := range sSamples {
			if !hasString(combinedSampleIDs, sid) {
				combinedSampleIDs = append(combinedSampleIDs, sid)
			}
		}
		sourceUUIDs = append(sourceUUIDs, srcID)
	}

	// Validate compatibility of all combined samples
	type sMeta struct {
		sampleID     uuid.UUID
		stID         uuid.UUID
		stName       string
		batchAllowed bool
		cooled       bool
		incompat     []string
		deadline     time.Time
		tMin         float64
		tMax         float64
	}
	var metas []sMeta
	for _, sidStr := range combinedSampleIDs {
		sid, _ := uuid.Parse(sidStr)
		var stID uuid.UUID
		var incB []byte
		var dl time.Time
		var tMin, tMax float64
		err := s.db.QueryRow(ctx, `
			SELECT sample_type_id, incompatible_sample_types, delivery_deadline, temperature_min_c, temperature_max_c
			FROM samples WHERE sample_id = $1
		`, sid).Scan(&stID, &incB, &dl, &tMin, &tMax)
		if err != nil {
			writeError(w, 404, "not_found", "Sample not found")
			return
		}
		st, err := s.loadSampleType(ctx, s.db, stID)
		if err != nil {
			writeError(w, 404, "not_found", "Sample type not found")
			return
		}
		var inc []string
		_ = json.Unmarshal(incB, &inc)
		for _, x := range st.IncompatibleSampleTypes {
			if !hasString(inc, x) {
				inc = append(inc, x)
			}
		}
		metas = append(metas, sMeta{
			sampleID:     sid,
			stID:         stID,
			stName:       st.Name,
			batchAllowed: st.BatchingAllowed,
			cooled:       st.RequiresCooledRoute,
			incompat:     inc,
			deadline:     dl,
			tMin:         tMin,
			tMax:         tMax,
		})
	}

	for i := 0; i < len(metas); i++ {
		if strings.EqualFold(metas[i].stName, "Pulse") || !metas[i].batchAllowed {
			writeError(w, 409, "pulse_no_batch", "Pulse or non-batchable sample cannot be combined into a consolidation batch")
			return
		}
		if estDel.After(metas[i].deadline) {
			writeError(w, 409, "delivery_deadline_exceeded", "Merged journey exceeds sample delivery deadline")
			return
		}
		for j := i + 1; j < len(metas); j++ {
			if hasString(metas[i].incompat, metas[j].stID.String()) || hasString(metas[j].incompat, metas[i].stID.String()) {
				writeError(w, 409, "incompatible_batch", "Samples have incompatible handling rules")
				return
			}
			if (strings.EqualFold(metas[i].stName, "Amber") && strings.EqualFold(metas[j].stName, "Indigo")) ||
				(strings.EqualFold(metas[i].stName, "Indigo") && strings.EqualFold(metas[j].stName, "Amber")) {
				writeError(w, 409, "incompatible_batch", "Indigo sample cannot share a batch with Amber sample")
				return
			}
			// Check temperature range overlap
			if metas[i].tMax < metas[j].tMin || metas[j].tMax < metas[i].tMin {
				writeError(w, 409, "incompatible_batch", "Samples have incompatible temperature ranges")
				return
			}
		}
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to start transaction")
		return
	}
	defer tx.Rollback(ctx)

	// Release source journey capacities and transfer reservations to target journey
	for _, srcID := range sourceUUIDs {
		_ = s.releaseJourneyCapacity(ctx, tx, srcID, nil)
		_, _ = tx.Exec(ctx, `UPDATE journeys SET status = 'replaced', replacement_journey_id = $1, plan_version = plan_version + 1 WHERE journey_id = $2`, targetJID, srcID)
		_, _ = tx.Exec(ctx, `UPDATE assignments SET active = FALSE, status = 'cancelled' WHERE journey_id = $1 AND status NOT IN ('completed', 'delivered')`, srcID)
	}

	// Reserve capacity on target journey's stops & connections for the newly added samples
	stopRows, err := tx.Query(ctx, `SELECT DISTINCT location_id FROM journey_stops WHERE journey_id = $1 AND completed_at IS NULL`, targetJID)
	var stopLocs []uuid.UUID
	if err == nil {
		for stopRows.Next() {
			var lid uuid.UUID
			if err := stopRows.Scan(&lid); err == nil {
				stopLocs = append(stopLocs, lid)
			}
		}
		stopRows.Close()
	}
	connRows, err := tx.Query(ctx, `SELECT DISTINCT connection_id FROM assignments WHERE journey_id = $1 AND connection_id IS NOT NULL AND active = TRUE AND status NOT IN ('completed', 'delivered')`, targetJID)
	var connIDs []uuid.UUID
	if err == nil {
		for connRows.Next() {
			var cid uuid.UUID
			if err := connRows.Scan(&cid); err == nil {
				connIDs = append(connIDs, cid)
			}
		}
		connRows.Close()
	}

	var targetSampleList []string
	_ = json.Unmarshal(targetSamplesB, &targetSampleList)
	for _, m := range metas {
		if hasString(targetSampleList, m.sampleID.String()) {
			continue
		}
		for _, lid := range stopLocs {
			if err := s.reserveResourceCapacity(ctx, tx, targetJID, m.sampleID, "location", lid, 1, m.cooled); err != nil {
				code := "capacity_exhausted"
				if strings.Contains(err.Error(), "cooled") {
					code = "cooled_capacity_exhausted"
				}
				writeError(w, 409, code, "Insufficient location capacity for merged batch")
				return
			}
		}
		for _, cid := range connIDs {
			if err := s.reserveResourceCapacity(ctx, tx, targetJID, m.sampleID, "connection", cid, 1, m.cooled); err != nil {
				code := "capacity_exhausted"
				if strings.Contains(err.Error(), "cooled") {
					code = "cooled_capacity_exhausted"
				}
				writeError(w, 409, code, "Insufficient connection capacity for merged batch")
				return
			}
		}
		_, _ = tx.Exec(ctx, `UPDATE samples SET active_journey_id = $1 WHERE sample_id = $2`, targetJID, m.sampleID)
	}

	combB, _ := json.Marshal(combinedSampleIDs)
	_, err = tx.Exec(ctx, `
		UPDATE journeys
		SET sample_ids = $1, route_mode = 'batched', capacity_used = $2, plan_version = plan_version + 1
		WHERE journey_id = $3
	`, combB, len(combinedSampleIDs), targetJID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update merged journey")
		return
	}

	jp, err := s.buildJourneyPlan(ctx, tx, targetJID, 0)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to build merged journey plan")
		return
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, tx)
	s.recordAudit(ctx, tx, auth.UserID.String(), auth.ActiveRole, "merge_journeys", "journey", targetJID.String(), true, time.Now().UTC(), map[string]any{
		"targetJourneyId":  targetJID.String(),
		"sourceJourneyIds": req.SourceJourneyIDs,
		"sampleIds":        combinedSampleIDs,
	})

	if err := tx.Commit(ctx); err != nil {
		writeError(w, 500, "internal_error", "Failed to commit merge")
		return
	}

	s.publishEvent(ctx, s.db, "journeys_merged", "journey", targetJID.String(), map[string]any{
		"journeyId": targetJID.String(),
		"sampleIds": combinedSampleIDs,
	})

	s.saveIdempotency(ctx, "merge_journeys", idemKey, rawBody, 201, jp)
	writeData(w, 201, jp)
}

func (s *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "split_journey", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		JourneyID           *string  `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || len(req.SampleIDs) == 0 {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, 400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "split_journey", idemKey, rawBody); done {
		return
	}

	journeyID, err := uuid.Parse(*req.JourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid journeyId")
		return
	}

	var curVer int
	var curStatus string
	var curSamplesB []byte
	err = s.db.QueryRow(ctx, `SELECT plan_version, status, sample_ids FROM journeys WHERE journey_id = $1`, journeyID).Scan(&curVer, &curStatus, &curSamplesB)
	if err != nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}
	if curVer != *req.ExpectedPlanVersion {
		writeError(w, 409, "stale_plan", "Plan version mismatch")
		return
	}
	if curStatus == "cancelled" || curStatus == "completed" || curStatus == "replaced" || curStatus == "expired" {
		writeError(w, 409, "inactive_plan", "Journey is inactive")
		return
	}

	var curSamples []string
	_ = json.Unmarshal(curSamplesB, &curSamples)
	if len(req.SampleIDs) >= len(curSamples) {
		writeError(w, 409, "invalid_split", "Split sampleIds must be a proper subset of journey samples")
		return
	}
	remainingSamples := []string{}
	for _, sID := range curSamples {
		if !hasString(req.SampleIDs, sID) {
			remainingSamples = append(remainingSamples, sID)
		}
	}
	if len(remainingSamples)+len(req.SampleIDs) != len(curSamples) {
		writeError(w, 409, "invalid_split", "One or more sampleIds do not belong to journey")
		return
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to start transaction")
		return
	}
	defer tx.Rollback(ctx)

	firstSplitSID, _ := uuid.Parse(req.SampleIDs[0])
	var stID uuid.UUID
	var origLat, origLng float64
	var origType string
	var origNodeID, currentHolderID *uuid.UUID
	var sealed bool
	var earliest, deadline time.Time
	err = tx.QueryRow(ctx, `
		SELECT sample_type_id, origin_lat, origin_lng, origin_type, origin_node_id,
		       current_holder_id, sealed, earliest_collection_at, delivery_deadline
		FROM samples WHERE sample_id = $1
	`, firstSplitSID).Scan(&stID, &origLat, &origLng, &origType, &origNodeID, &currentHolderID, &sealed, &earliest, &deadline)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}
	st, _ := s.loadSampleType(ctx, tx, stID)

	// Release split samples' reservations from original journey first
	for _, sidStr := range req.SampleIDs {
		if sid, err := uuid.Parse(sidStr); err == nil {
			_ = s.releaseJourneyCapacity(ctx, tx, journeyID, &sid)
		}
	}

	serviceable, _, conflictCode, route := s.evaluateServiceability(ctx, tx, Coordinate{Latitude: origLat, Longitude: origLng}, origType, origNodeID, st, earliest, deadline, len(req.SampleIDs))
	if !serviceable || route == nil {
		if conflictCode == "" {
			conflictCode = "no_valid_route"
		}
		writeError(w, 409, conflictCode, "Split journey cannot be routed")
		return
	}

	splitJID, activeAssigns, _, err := s.createJourneyForSample(ctx, tx, firstSplitSID, st, route, earliest, sealed, currentHolderID, &journeyID)
	if err != nil {
		writeError(w, 409, "capacity_exhausted", err.Error())
		return
	}

	splitSamplesB, _ := json.Marshal(req.SampleIDs)
	splitMode := "direct"
	if len(req.SampleIDs) > 1 {
		splitMode = "batched"
	} else if len(route.Nodes) > 2 {
		splitMode = "multi_stop"
	}
	_, _ = tx.Exec(ctx, `UPDATE journeys SET sample_ids = $1, route_mode = $2, capacity_used = $3 WHERE journey_id = $4`, splitSamplesB, splitMode, len(req.SampleIDs), splitJID)

	actAssignB, _ := json.Marshal(activeAssigns)
	for _, sidStr := range req.SampleIDs {
		if sid, err := uuid.Parse(sidStr); err == nil {
			_, _ = tx.Exec(ctx, `UPDATE samples SET active_journey_id = $1, active_assignment_ids = $2 WHERE sample_id = $3`, splitJID, actAssignB, sid)
		}
	}

	remSamplesB, _ := json.Marshal(remainingSamples)
	remMode := "direct"
	if len(remainingSamples) > 1 {
		remMode = "batched"
	} else {
		var stopCnt int
		_ = tx.QueryRow(ctx, `SELECT COUNT(*) FROM journey_stops WHERE journey_id = $1`, journeyID).Scan(&stopCnt)
		if stopCnt > 2 {
			remMode = "multi_stop"
		}
	}

	_, err = tx.Exec(ctx, `
		UPDATE journeys
		SET sample_ids = $1, route_mode = $2, capacity_used = $3, split_journey_id = $4, plan_version = plan_version + 1
		WHERE journey_id = $5
	`, remSamplesB, remMode, len(remainingSamples), splitJID, journeyID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update original journey")
		return
	}

	origPlan, err1 := s.buildJourneyPlan(ctx, tx, journeyID, 0)
	splitPlan, err2 := s.buildJourneyPlan(ctx, tx, splitJID, 0)
	if err1 != nil || err2 != nil {
		writeError(w, 500, "internal_error", "Failed to build split journey plans")
		return
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, tx)
	s.recordAudit(ctx, tx, auth.UserID.String(), auth.ActiveRole, "split_journey", "journey", journeyID.String(), true, time.Now().UTC(), map[string]any{
		"journeyId":      journeyID.String(),
		"splitJourneyId": splitJID.String(),
		"splitSampleIds": req.SampleIDs,
	})

	if err := tx.Commit(ctx); err != nil {
		writeError(w, 500, "internal_error", "Failed to commit split")
		return
	}

	s.publishEvent(ctx, s.db, "journey_split", "journey", journeyID.String(), map[string]any{
		"journeyId":      journeyID.String(),
		"splitJourneyId": splitJID.String(),
	})

	resp := map[string]any{
		"journey":      origPlan,
		"splitJourney": splitPlan,
	}
	s.saveIdempotency(ctx, "split_journey", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "edit_active_plan", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		JourneyID           *string        `json:"journeyId"`
		ExpectedPlanVersion *int           `json:"expectedPlanVersion"`
		ChangeType          *string        `json:"changeType"`
		Changes             map[string]any `json:"changes"`
		IdempotencyKey      *string        `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.ChangeType == nil || req.Changes == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeError(w, 400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}
	validChangeTypes := []string{
		"add_stop", "remove_stop", "reorder_stops",
		"replace_worker", "reassign_worker",
		"merge_samples", "split_samples", "split_batch",
		"cancel_work", "reroute", "replace_route",
	}
	changeType := *req.ChangeType
	if !hasString(validChangeTypes, changeType) {
		writeError(w, 400, "invalid_change_type", "Invalid changeType")
		return
	}

	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "edit_active_plan", idemKey, rawBody); done {
		return
	}

	journeyID, err := uuid.Parse(*req.JourneyID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid journeyId")
		return
	}

	var curVer int
	var curStatus string
	var sampleIDsB []byte
	err = s.db.QueryRow(ctx, `SELECT plan_version, status, sample_ids FROM journeys WHERE journey_id = $1`, journeyID).Scan(&curVer, &curStatus, &sampleIDsB)
	if err != nil {
		writeError(w, 404, "not_found", "Journey not found")
		return
	}
	if curVer != *req.ExpectedPlanVersion {
		writeError(w, 409, "stale_plan", "Plan version mismatch")
		return
	}
	if curStatus == "cancelled" || curStatus == "completed" || curStatus == "replaced" || curStatus == "expired" {
		writeError(w, 409, "inactive_plan", "Journey is inactive")
		return
	}

	var sampleIDs []string
	_ = json.Unmarshal(sampleIDsB, &sampleIDs)

	tx, err := s.db.Begin(ctx)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to start transaction")
		return
	}
	defer tx.Rollback(ctx)

	switch changeType {
	case "replace_worker", "reassign_worker":
		assignStr := getStringMap(req.Changes, "assignmentId", "assignment_id")
		workerStr := getStringMap(req.Changes, "workerId", "worker_id", "newWorkerId", "new_worker_id")
		if workerStr == "" {
			writeError(w, 400, "invalid_worker", "workerId is required")
			return
		}
		newWorkerID, err := uuid.Parse(workerStr)
		if err != nil {
			writeError(w, 400, "invalid_worker", "Invalid workerId")
			return
		}

		// Find target assignment (either by assignmentId or first unfinished assignment on journey)
		var assignID uuid.UUID
		var aKind, aStatus string
		var aNodeID, aLabID, aStID *uuid.UUID
		if assignStr != "" {
			assignID, err = uuid.Parse(assignStr)
			if err != nil {
				writeError(w, 409, "invalid_assignment", "Invalid assignmentId")
				return
			}
			err = tx.QueryRow(ctx, `
				SELECT kind, status, node_id, laboratory_id, expected_sample_type_id
				FROM assignments WHERE assignment_id = $1 AND journey_id = $2
			`, assignID, journeyID).Scan(&aKind, &aStatus, &aNodeID, &aLabID, &aStID)
			if err != nil {
				writeError(w, 409, "invalid_assignment", "Assignment not found on journey")
				return
			}
		} else {
			err = tx.QueryRow(ctx, `
				SELECT assignment_id, kind, status, node_id, laboratory_id, expected_sample_type_id
				FROM assignments WHERE journey_id = $1 AND active = TRUE AND status NOT IN ('completed', 'delivered')
				ORDER BY sequence ASC LIMIT 1
			`, journeyID).Scan(&assignID, &aKind, &aStatus, &aNodeID, &aLabID, &aStID)
			if err != nil {
				writeError(w, 409, "completed_work_immutable", "No unfinished assignment to reassign")
				return
			}
		}

		if aStatus == "completed" || aStatus == "delivered" {
			writeError(w, 409, "completed_work_immutable", "Cannot reassign completed work")
			return
		}
		if aStatus == "picked_up" || aStatus == "in_transit" {
			writeError(w, 409, "work_in_progress", "Cannot reassign leg while worker is actively transporting custody")
			return
		}

		// Verify new worker eligibility
		var wRolesB, wQualsB, wCertsB []byte
		var wLocID *uuid.UUID
		var wActive, wAvail bool
		var wCap int
		err = tx.QueryRow(ctx, `
			SELECT roles, qualifications, certifications, assigned_location_id, active, available, capacity_units
			FROM users WHERE user_id = $1
		`, newWorkerID).Scan(&wRolesB, &wQualsB, &wCertsB, &wLocID, &wActive, &wAvail, &wCap)
		if err != nil {
			writeError(w, 400, "invalid_worker", "Worker not found")
			return
		}
		if !wActive || !wAvail || wCap <= 0 {
			writeError(w, 409, "worker_unavailable", "Replacement worker is unavailable")
			return
		}
		var wRoles, wQuals []string
		var wCerts []Certification
		_ = json.Unmarshal(wRolesB, &wRoles)
		_ = json.Unmarshal(wQualsB, &wQuals)
		_ = json.Unmarshal(wCertsB, &wCerts)

		reqRole := "delivery_partner"
		switch aKind {
		case "collection":
			reqRole = "collection_professional"
		case "node":
			reqRole = "node_handler"
		case "laboratory":
			reqRole = "laboratory_team"
		}
		if !hasString(wRoles, reqRole) {
			writeError(w, 409, "ineligible_worker", "Worker does not hold required role")
			return
		}
		if aKind == "node" && aNodeID != nil && (wLocID == nil || *wLocID != *aNodeID) {
			writeError(w, 409, "ineligible_worker", "Node handler is not assigned to this node")
			return
		}
		if aKind == "laboratory" && aLabID != nil && (wLocID == nil || *wLocID != *aLabID) {
			writeError(w, 409, "ineligible_worker", "Laboratory operator is not assigned to this laboratory")
			return
		}
		if aKind == "collection" && aStID != nil {
			st, _ := s.loadSampleType(ctx, tx, *aStID)
			if !isWorkerQualifiedForSampleType(wQuals, wCerts, st, time.Now().UTC()) {
				writeError(w, 409, "ineligible_worker", "Collector lacks required qualification")
				return
			}
		}

		_, _ = tx.Exec(ctx, `
			UPDATE assignments SET offered_to_worker_id = $1, worker_id = $1, status = 'accepted'
			WHERE assignment_id = $2
		`, newWorkerID, assignID)
		_, _ = tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)

	case "cancel_work":
		assignStr := getStringMap(req.Changes, "assignmentId", "assignment_id")
		if assignStr != "" {
			aID, err := uuid.Parse(assignStr)
			if err != nil {
				writeError(w, 409, "invalid_assignment", "Invalid assignmentId")
				return
			}
			var aStatus string
			err = tx.QueryRow(ctx, `SELECT status FROM assignments WHERE assignment_id = $1 AND journey_id = $2`, aID, journeyID).Scan(&aStatus)
			if err != nil {
				writeError(w, 409, "invalid_assignment", "Assignment not found")
				return
			}
			if aStatus == "completed" || aStatus == "delivered" {
				writeError(w, 409, "completed_work_immutable", "Cannot cancel completed assignment")
				return
			}
			_, _ = tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled', active = FALSE WHERE assignment_id = $1`, aID)
		} else {
			var compCnt int
			_ = tx.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id = $1 AND status IN ('completed', 'delivered')`, journeyID).Scan(&compCnt)
			_, _ = tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled', active = FALSE WHERE journey_id = $1 AND status NOT IN ('completed', 'delivered')`, journeyID)
			_, _ = tx.Exec(ctx, `UPDATE journeys SET status = 'cancelled' WHERE journey_id = $1`, journeyID)
			_ = s.releaseJourneyCapacity(ctx, tx, journeyID, nil)
		}
		_, _ = tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)

	case "add_stop", "remove_stop", "reorder_stops", "reroute", "replace_route":
		if code, msg := s.applyRouteStopsEdit(ctx, tx, journeyID, sampleIDs, changeType, req.Changes); code != "" {
			if strings.HasPrefix(code, "400:") {
				writeError(w, 400, strings.TrimPrefix(code, "400:"), msg)
			} else {
				writeError(w, 409, code, msg)
			}
			return
		}
		_, _ = tx.Exec(ctx, `UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1`, journeyID)

	case "split_samples", "split_batch":
		rawSplitIDs, ok := req.Changes["sampleIds"]
		var splitIDs []string
		if ok {
			b, _ := json.Marshal(rawSplitIDs)
			_ = json.Unmarshal(b, &splitIDs)
		}
		if len(splitIDs) == 0 || len(splitIDs) >= len(sampleIDs) {
			writeError(w, 409, "invalid_split", "Invalid sampleIds for split")
			return
		}
		rem := []string{}
		for _, sid := range sampleIDs {
			if !hasString(splitIDs, sid) {
				rem = append(rem, sid)
			}
		}
		if len(rem)+len(splitIDs) != len(sampleIDs) {
			writeError(w, 409, "invalid_split", "Sample does not belong to journey")
			return
		}
		firstSplitSID, _ := uuid.Parse(splitIDs[0])
		var stID uuid.UUID
		var origLat, origLng float64
		var origType string
		var origNodeID, currentHolderID *uuid.UUID
		var sealed bool
		var earliest, deadline time.Time
		_ = tx.QueryRow(ctx, `
			SELECT sample_type_id, origin_lat, origin_lng, origin_type, origin_node_id,
			       current_holder_id, sealed, earliest_collection_at, delivery_deadline
			FROM samples WHERE sample_id = $1
		`, firstSplitSID).Scan(&stID, &origLat, &origLng, &origType, &origNodeID, &currentHolderID, &sealed, &earliest, &deadline)
		st, _ := s.loadSampleType(ctx, tx, stID)
		for _, sidStr := range splitIDs {
			if sid, err := uuid.Parse(sidStr); err == nil {
				_ = s.releaseJourneyCapacity(ctx, tx, journeyID, &sid)
			}
		}
		serviceable, _, conflictCode, route := s.evaluateServiceability(ctx, tx, Coordinate{Latitude: origLat, Longitude: origLng}, origType, origNodeID, st, earliest, deadline, len(splitIDs))
		if !serviceable || route == nil {
			if conflictCode == "" {
				conflictCode = "no_valid_route"
			}
			writeError(w, 409, conflictCode, "Cannot route split samples")
			return
		}
		splitJID, actAssigns, _, err := s.createJourneyForSample(ctx, tx, firstSplitSID, st, route, earliest, sealed, currentHolderID, &journeyID)
		if err != nil {
			writeError(w, 409, "capacity_exhausted", err.Error())
			return
		}
		spB, _ := json.Marshal(splitIDs)
		_, _ = tx.Exec(ctx, `UPDATE journeys SET sample_ids = $1, capacity_used = $2 WHERE journey_id = $3`, spB, len(splitIDs), splitJID)
		actB, _ := json.Marshal(actAssigns)
		for _, sidStr := range splitIDs {
			if sid, err := uuid.Parse(sidStr); err == nil {
				_, _ = tx.Exec(ctx, `UPDATE samples SET active_journey_id = $1, active_assignment_ids = $2 WHERE sample_id = $3`, splitJID, actB, sid)
			}
		}
		remB, _ := json.Marshal(rem)
		remMode := "direct"
		if len(rem) > 1 {
			remMode = "batched"
		}
		_, _ = tx.Exec(ctx, `UPDATE journeys SET sample_ids = $1, route_mode = $2, capacity_used = $3, split_journey_id = $4, plan_version = plan_version + 1 WHERE journey_id = $5`, remB, remMode, len(rem), splitJID, journeyID)

	case "merge_samples":
		var addSampleIDs []string
		if rawS, ok := req.Changes["sampleIds"]; ok {
			b, _ := json.Marshal(rawS)
			_ = json.Unmarshal(b, &addSampleIDs)
		}
		if len(addSampleIDs) == 0 {
			writeError(w, 409, "invalid_batch", "sampleIds required for merge_samples")
			return
		}
		allSIDs := append([]string{}, sampleIDs...)
		for _, sid := range addSampleIDs {
			if !hasString(allSIDs, sid) {
				allSIDs = append(allSIDs, sid)
			}
		}
		// Check pulse / incompatibilities
		var stList []*dbSampleType
		for _, sidStr := range allSIDs {
			sid, err := uuid.Parse(sidStr)
			if err != nil {
				writeError(w, 409, "invalid_batch", "Invalid sampleId")
				return
			}
			var stID uuid.UUID
			if err := tx.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id = $1`, sid).Scan(&stID); err != nil {
				writeError(w, 404, "not_found", "Sample not found")
				return
			}
			st, _ := s.loadSampleType(ctx, tx, stID)
			if st != nil {
				if strings.EqualFold(st.Name, "Pulse") || !st.BatchingAllowed {
					writeError(w, 409, "pulse_no_batch", "Pulse sample cannot be batched")
					return
				}
				stList = append(stList, st)
			}
		}
		for i := 0; i < len(stList); i++ {
			for j := i + 1; j < len(stList); j++ {
				if hasString(stList[i].IncompatibleSampleTypes, stList[j].SampleTypeID.String()) ||
					hasString(stList[j].IncompatibleSampleTypes, stList[i].SampleTypeID.String()) ||
					(strings.EqualFold(stList[i].Name, "Amber") && strings.EqualFold(stList[j].Name, "Indigo")) ||
					(strings.EqualFold(stList[i].Name, "Indigo") && strings.EqualFold(stList[j].Name, "Amber")) {
					writeError(w, 409, "incompatible_batch", "Samples are incompatible")
					return
				}
			}
		}
		combB, _ := json.Marshal(allSIDs)
		_, _ = tx.Exec(ctx, `UPDATE journeys SET sample_ids = $1, route_mode = 'batched', capacity_used = $2, plan_version = plan_version + 1 WHERE journey_id = $3`, combB, len(allSIDs), journeyID)
	}

	jp, err := s.buildJourneyPlan(ctx, tx, journeyID, 0)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to build updated plan")
		return
	}

	_ = s.recomputeServiceabilitySnapshot(ctx, tx)
	s.recordAudit(ctx, tx, auth.UserID.String(), auth.ActiveRole, "edit_active_plan", "journey", journeyID.String(), true, time.Now().UTC(), map[string]any{
		"journeyId":   journeyID.String(),
		"changeType":  changeType,
		"planVersion": jp.PlanVersion,
	})

	if err := tx.Commit(ctx); err != nil {
		writeError(w, 500, "internal_error", "Failed to commit plan edit")
		return
	}

	s.publishEvent(ctx, s.db, "journey_plan_edited", "journey", journeyID.String(), map[string]any{
		"journeyId":   journeyID.String(),
		"changeType":  changeType,
		"planVersion": jp.PlanVersion,
	})

	s.saveIdempotency(ctx, "edit_active_plan", idemKey, rawBody, 201, jp)
	writeData(w, 201, jp)
}

func (s *Server) applyRouteStopsEdit(ctx context.Context, tx DBTx, journeyID uuid.UUID, sampleIDs []string, changeType string, changes map[string]any) (string, string) {
	// Load existing stops
	sRows, err := tx.Query(ctx, `
		SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at
		FROM journey_stops WHERE journey_id = $1 ORDER BY sequence ASC
	`, journeyID)
	if err != nil {
		return "invalid_plan", "Failed to load stops"
	}
	type stopRec struct {
		stopID   uuid.UUID
		locID    uuid.UUID
		stopType string
		seq      int
		estAt    time.Time
		dwell    int
		compAt   *time.Time
	}
	var curStops []stopRec
	for sRows.Next() {
		var sr stopRec
		if err := sRows.Scan(&sr.stopID, &sr.locID, &sr.stopType, &sr.seq, &sr.estAt, &sr.dwell, &sr.compAt); err == nil {
			curStops = append(curStops, sr)
		}
	}
	sRows.Close()

	if len(curStops) == 0 {
		return "invalid_plan", "Journey has no stops"
	}

	// Load sample details for validation
	firstSID, _ := uuid.Parse(sampleIDs[0])
	var stID uuid.UUID
	var earliest, deadline time.Time
	_ = tx.QueryRow(ctx, `SELECT sample_type_id, earliest_collection_at, delivery_deadline FROM samples WHERE sample_id = $1`, firstSID).Scan(&stID, &earliest, &deadline)
	st, _ := s.loadSampleType(ctx, tx, stID)
	locs, conns, accepts, _ := s.loadNetwork(ctx, tx)

	newLocSeq := []uuid.UUID{}
	for _, cs := range curStops {
		newLocSeq = append(newLocSeq, cs.locID)
	}

	switch changeType {
	case "remove_stop":
		locStr := getStringMap(changes, "locationId", "location_id", "stopLocationId")
		stopStr := getStringMap(changes, "stopId", "stop_id")
		removed := false
		filtered := []uuid.UUID{}
		for _, cs := range curStops {
			match := (locStr != "" && cs.locID.String() == locStr) || (stopStr != "" && cs.stopID.String() == stopStr)
			if match {
				if cs.compAt != nil {
					return "completed_work_immutable", "Cannot remove a completed stop"
				}
				// Check if any assignment to/from this stop is already completed
				var compCnt int
				_ = tx.QueryRow(ctx, `
					SELECT COUNT(*) FROM assignments
					WHERE journey_id = $1 AND status IN ('completed', 'delivered')
					  AND (from_location_id = $2 OR to_location_id = $2)
				`, journeyID, cs.locID).Scan(&compCnt)
				if compCnt > 0 {
					return "completed_work_immutable", "Cannot remove stop with completed work"
				}
				removed = true
				continue
			}
			filtered = append(filtered, cs.locID)
		}
		if !removed || len(filtered) == 0 {
			return "invalid_stop", "Stop to remove not found or invalid"
		}
		newLocSeq = filtered

	case "add_stop":
		if dwellVal, ok := changes["dwellMinutes"]; ok {
			if df, ok := dwellVal.(float64); ok && (df < 0 || df > 1440) {
				return "400:invalid_dwell", "Invalid dwellMinutes"
			}
		}
		locStr := getStringMap(changes, "locationId", "location_id")
		if locStr == "" {
			if stopMap, ok := changes["stop"].(map[string]any); ok {
				locStr = getStringMap(stopMap, "locationId", "location_id")
				if dwellVal, ok := stopMap["dwellMinutes"]; ok {
					if df, ok := dwellVal.(float64); ok && (df < 0 || df > 1440) {
						return "400:invalid_dwell", "Invalid dwellMinutes"
					}
				}
			}
		}
		locUUID, err := uuid.Parse(locStr)
		if err != nil {
			return "invalid_stop", "Invalid locationId for add_stop"
		}
		if _, ok := locs[locUUID]; !ok {
			return "invalid_stop", "Location not found"
		}
		insertIdx := len(newLocSeq) - 1
		if seqVal, ok := changes["sequence"].(float64); ok {
			idx := int(seqVal) - 1
			if idx < 0 || idx > len(newLocSeq) {
				return "invalid_stop_order", "Invalid stop sequence"
			}
			// Check if trying to insert before a completed stop
			if idx < len(curStops) && curStops[idx].compAt != nil {
				return "completed_work_immutable", "Cannot insert stop before completed stop"
			}
			insertIdx = idx
		}
		updated := append([]uuid.UUID{}, newLocSeq[:insertIdx]...)
		updated = append(updated, locUUID)
		updated = append(updated, newLocSeq[insertIdx:]...)
		newLocSeq = updated

	case "reorder_stops", "reroute", "replace_route":
		var rawLocs []string
		if rl, ok := changes["locationIds"]; ok {
			b, _ := json.Marshal(rl)
			_ = json.Unmarshal(b, &rawLocs)
		} else if rl, ok := changes["orderedLocationIds"]; ok {
			b, _ := json.Marshal(rl)
			_ = json.Unmarshal(b, &rawLocs)
		} else if rawStops, ok := changes["orderedStops"].([]any); ok {
			prevSeq := 0
			seenSeq := make(map[int]bool)
			for _, item := range rawStops {
				if m, ok := item.(map[string]any); ok {
					lStr := getStringMap(m, "locationId", "location_id")
					if lStr != "" {
						rawLocs = append(rawLocs, lStr)
					}
					if sVal, ok := m["sequence"].(float64); ok {
						sq := int(sVal)
						if seenSeq[sq] {
							return "ambiguous_stop_order", "Duplicate stop sequence"
						}
						if sq < prevSeq {
							return "invalid_stop_order", "Stops are out of sequence order"
						}
						seenSeq[sq] = true
						prevSeq = sq
					}
				}
			}
		} else if rawStops, ok := changes["stops"].([]any); ok {
			prevSeq := 0
			seenSeq := make(map[int]bool)
			for _, item := range rawStops {
				if m, ok := item.(map[string]any); ok {
					lStr := getStringMap(m, "locationId", "location_id")
					if lStr != "" {
						rawLocs = append(rawLocs, lStr)
					}
					if sVal, ok := m["sequence"].(float64); ok {
						sq := int(sVal)
						if seenSeq[sq] {
							return "ambiguous_stop_order", "Duplicate stop sequence"
						}
						if sq < prevSeq {
							return "invalid_stop_order", "Stops are out of sequence order"
						}
						seenSeq[sq] = true
						prevSeq = sq
					}
				}
			}
		}

		if len(rawLocs) > 0 {
			parsedSeq := []uuid.UUID{}
			for _, lStr := range rawLocs {
				id, err := uuid.Parse(lStr)
				if err != nil {
					return "invalid_stop", "Invalid stop location UUID"
				}
				parsedSeq = append(parsedSeq, id)
			}
			// Ensure completed stops at the prefix are preserved in order
			for idx, cs := range curStops {
				if cs.compAt != nil {
					if idx >= len(parsedSeq) || parsedSeq[idx] != cs.locID {
						return "completed_work_immutable", "Completed stops cannot be reordered or removed"
					}
				}
			}
			newLocSeq = parsedSeq
		}
	}

	if len(newLocSeq) == 0 {
		return "invalid_stop_order", "Stop sequence cannot be empty"
	}

	// Release existing reservations for journey before validating new route capacities
	_ = s.releaseJourneyCapacity(ctx, tx, journeyID, nil)

	// Validate nodes, connections, capacities, lab acceptance, and deadline for newLocSeq
	pathNodes := []dbLocation{}
	for idx, lid := range newLocSeq {
		loc, ok := locs[lid]
		if !ok || !loc.Active {
			return "invalid_stop", "Stop location is not active"
		}
		if idx == len(newLocSeq)-1 {
			if !loc.FnLaboratory || !accepts[lid][st.SampleTypeID] {
				return "invalid_destination", "Final stop is not an accepting laboratory"
			}
		}
		pathNodes = append(pathNodes, loc)
	}

	connMap := make(map[string]dbConnection)
	for _, c := range conns {
		if c.Active {
			key := fmt.Sprintf("%s->%s", c.FromLocationID.String(), c.ToLocationID.String())
			connMap[key] = c
		}
	}

	pathConns := []dbConnection{}
	for i := 0; i < len(newLocSeq)-1; i++ {
		if newLocSeq[i] == newLocSeq[i+1] {
			continue
		}
		key := fmt.Sprintf("%s->%s", newLocSeq[i].String(), newLocSeq[i+1].String())
		c, ok := connMap[key]
		if !ok {
			return "invalid_route", "No active connection between consecutive stops"
		}
		if st.RequiresCooledRoute && !c.Cooled {
			return "cooled_capacity_exhausted", "Connection does not support cooled transport"
		}
		pathConns = append(pathConns, c)
	}

	eval := evaluateCandidatePath(pathNodes, pathConns, st.RequiresCooledRoute, len(sampleIDs), earliest, deadline)
	if !eval.cooledOK {
		return "cooled_capacity_exhausted", "Cooled route requirement not met"
	}
	if !eval.capOK {
		if st.RequiresCooledRoute {
			return "cooled_capacity_exhausted", "Insufficient cooled capacity"
		}
		return "capacity_exhausted", "Insufficient regular capacity"
	}
	if !eval.deadlineOK {
		return "delivery_deadline_exceeded", "Edited route exceeds sample delivery deadline"
	}

	// Reserve capacity on new path
	for _, sidStr := range sampleIDs {
		sid, _ := uuid.Parse(sidStr)
		for _, n := range pathNodes {
			if err := s.reserveResourceCapacity(ctx, tx, journeyID, sid, "location", n.LocationID, 1, st.RequiresCooledRoute); err != nil {
				return "capacity_exhausted", err.Error()
			}
		}
		for _, c := range pathConns {
			if err := s.reserveResourceCapacity(ctx, tx, journeyID, sid, "connection", c.ConnectionID, 1, st.RequiresCooledRoute); err != nil {
				return "capacity_exhausted", err.Error()
			}
		}
	}

	// Rebuild unfinished stops
	_, _ = tx.Exec(ctx, `DELETE FROM journey_stops WHERE journey_id = $1 AND completed_at IS NULL`, journeyID)
	compStopCount := 0
	for _, cs := range curStops {
		if cs.compAt != nil {
			compStopCount++
		}
	}

	currTime := earliest
	for idx, n := range pathNodes {
		if idx < compStopCount {
			continue
		}
		stopType := "handoff"
		if idx == 0 {
			stopType = "pickup"
		} else if idx == len(pathNodes)-1 {
			stopType = "delivery"
		}
		if idx > 0 && idx-1 < len(pathConns) {
			currTime = currTime.Add(time.Duration(pathConns[idx-1].TravelMinutes) * time.Minute)
		}
		_, _ = tx.Exec(ctx, `
			INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
			VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		`, uuid.New(), journeyID, n.LocationID, stopType, idx+1, currTime, n.HandlingMinutes, n.Latitude, n.Longitude)
		currTime = currTime.Add(time.Duration(n.HandlingMinutes) * time.Minute)
	}

	routeMode := "direct"
	if len(sampleIDs) > 1 {
		routeMode = "batched"
	} else if len(pathNodes) > 2 {
		routeMode = "multi_stop"
	}
	targetLab := pathNodes[len(pathNodes)-1].LocationID
	_, _ = tx.Exec(ctx, `
		UPDATE journeys SET route_mode = $1, estimated_delivery_at = $2, total_cost_units = $3
		WHERE journey_id = $4
	`, routeMode, eval.arrival, eval.cost, journeyID)
	for _, sidStr := range sampleIDs {
		if sid, err := uuid.Parse(sidStr); err == nil {
			_, _ = tx.Exec(ctx, `UPDATE samples SET target_laboratory_id = $1 WHERE sample_id = $2`, targetLab, sid)
		}
	}

	return "", ""
}

func getStringMap(m map[string]any, keys ...string) string {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			if s, ok := v.(string); ok && s != "" {
				return s
			}
		}
	}
	return ""
}

