package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
)

func (s *Server) expireTimedOutOffers(ctx context.Context, q DBTx, refTime time.Time) error {
	if refTime.IsZero() {
		refTime = time.Now().UTC()
	}
	rows, err := q.Query(ctx, `
		SELECT assignment_id, journey_id, sample_id, kind, offered_to_worker_id,
		       node_id, laboratory_id, expected_sample_type_id, declined_by
		FROM assignments
		WHERE status = 'pending' AND active = TRUE AND worker_id IS NULL
		  AND offered_to_worker_id IS NOT NULL AND offer_expires_at IS NOT NULL
		  AND offer_expires_at <= $1
	`, refTime)
	if err != nil {
		return err
	}
	type expiredOffer struct {
		assignID   uuid.UUID
		journeyID  uuid.UUID
		sampleID   uuid.UUID
		kind       string
		offeredTo  uuid.UUID
		nodeID     *uuid.UUID
		labID      *uuid.UUID
		stID       *uuid.UUID
		declinedBy []string
	}
	var offers []expiredOffer
	for rows.Next() {
		var eo expiredOffer
		var declB []byte
		if err := rows.Scan(&eo.assignID, &eo.journeyID, &eo.sampleID, &eo.kind, &eo.offeredTo, &eo.nodeID, &eo.labID, &eo.stID, &declB); err == nil {
			_ = json.Unmarshal(declB, &eo.declinedBy)
			offers = append(offers, eo)
		}
	}
	rows.Close()

	for _, eo := range offers {
		if !hasString(eo.declinedBy, eo.offeredTo.String()) {
			eo.declinedBy = append(eo.declinedBy, eo.offeredTo.String())
		}
		declB, _ := json.Marshal(eo.declinedBy)

		_, _ = q.Exec(ctx, `
			UPDATE users
			SET decline_count = decline_count + 1, last_declined_at = $1
			WHERE user_id = $2
		`, refTime, eo.offeredTo)

		var st *dbSampleType
		if eo.stID != nil {
			st, _ = s.loadSampleType(ctx, q, *eo.stID)
		}
		targetLoc := eo.nodeID
		if targetLoc == nil {
			targetLoc = eo.labID
		}

		nextWorkerID, _ := s.findEligibleWorkerForAssignment(ctx, q, eo.kind, st, targetLoc, eo.declinedBy, refTime, nil)
		if nextWorkerID != nil {
			newExp := refTime.Add(30 * time.Minute)
			_, _ = q.Exec(ctx, `
				UPDATE assignments
				SET offered_to_worker_id = $1, offer_expires_at = $2, declined_by = $3
				WHERE assignment_id = $4
			`, *nextWorkerID, newExp, declB, eo.assignID)
			_, _ = q.Exec(ctx, `
				UPDATE users
				SET assignment_count = assignment_count + 1, last_offered_at = $1
				WHERE user_id = $2
			`, refTime, *nextWorkerID)
			s.recordAudit(ctx, q, eo.offeredTo.String(), "system", "offer_expired_reoffered", "assignment", eo.assignID.String(), true, refTime, map[string]any{
				"assignmentId":    eo.assignID.String(),
				"expiredWorkerId": eo.offeredTo.String(),
				"reofferedTo":     nextWorkerID.String(),
			})
		} else {
			_, _ = q.Exec(ctx, `
				UPDATE assignments
				SET offered_to_worker_id = NULL, offer_expires_at = NULL, declined_by = $1
				WHERE assignment_id = $2
			`, declB, eo.assignID)
			excID := uuid.New()
			excMap := map[string]any{
				"exceptionId":  excID.String(),
				"sampleId":     eo.sampleID.String(),
				"assignmentId": eo.assignID.String(),
				"reason":       "no_qualified_worker_available",
				"observedAt":   formatTimeISO(refTime),
			}
			excB, _ := json.Marshal(excMap)
			_, _ = q.Exec(ctx, `
				UPDATE samples
				SET status = 'exception', exception_data = $1
				WHERE sample_id = $2
			`, excB, eo.sampleID)
			_, _ = q.Exec(ctx, `
				INSERT INTO exceptions (exception_id, sample_id, reason, details, observed_at)
				VALUES ($1, $2, 'no_qualified_worker_available', 'Offer expired and no eligible worker available', $3)
			`, excID, eo.sampleID, refTime)
			s.recordAudit(ctx, q, eo.offeredTo.String(), "system", "offer_expired_exception", "sample", eo.sampleID.String(), true, refTime, excMap)
		}
	}
	return nil
}

func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "list_role_work")
	if !ok {
		return
	}

	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if _, err := decodeStrictJSON(r, &req, true); err != nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}

	if req.Role != nil && *req.Role != "" {
		if !isValidRole(*req.Role) {
			writeError(w, 400, "invalid_role", "Invalid role")
			return
		}
		if *req.Role != auth.ActiveRole {
			s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "list_role_work", "role", *req.Role, false, time.Now().UTC(), map[string]any{"reason": "role_mismatch"})
			writeError(w, 403, "forbidden", "Requested role does not match active role")
			return
		}
	}

	now := time.Now().UTC()
	_ = s.expireTimedOutOffers(ctx, s.db, now)

	roleWork := RoleWork{
		Pending:    []any{},
		InProgress: []any{},
		Completed:  []any{},
	}

	statusFilter := ""
	if req.Status != nil {
		statusFilter = strings.TrimSpace(*req.Status)
	}

	matchesFilter := func(itemStatus string, bucket string) bool {
		if statusFilter == "" {
			return true
		}
		if strings.EqualFold(statusFilter, itemStatus) || strings.EqualFold(statusFilter, bucket) {
			return true
		}
		if statusFilter == "in_progress" && bucket == "inProgress" {
			return true
		}
		return false
	}

	switch auth.ActiveRole {
	case "requester":
		rows, err := s.db.Query(ctx, `
			SELECT sample_id, request_id, status, serviceability, requested_at,
			       delivery_deadline, earliest_collection_at, latest_collection_at,
			       active_journey_id, target_laboratory_id, current_holder_id, requester_id,
			       location_recorded_at
			FROM samples
			WHERE requester_id = $1
			ORDER BY created_at DESC
		`, auth.UserID)
		if err == nil {
			type sRow struct {
				sampleID     uuid.UUID
				requestID    uuid.UUID
				status       string
				serv         string
				reqAt        time.Time
				deadline     time.Time
				earliest     time.Time
				latest       time.Time
				activeJID    *uuid.UUID
				targetLabID  *uuid.UUID
				holderID     *uuid.UUID
				requesterID  *uuid.UUID
				locRecAt     *time.Time
			}
			var list []sRow
			for rows.Next() {
				var sr sRow
				if err := rows.Scan(
					&sr.sampleID, &sr.requestID, &sr.status, &sr.serv, &sr.reqAt,
					&sr.deadline, &sr.earliest, &sr.latest,
					&sr.activeJID, &sr.targetLabID, &sr.holderID, &sr.requesterID,
					&sr.locRecAt,
				); err == nil {
					list = append(list, sr)
				}
			}
			rows.Close()

			for _, sr := range list {
				sidStr := sr.sampleID.String()
				reqStr := sr.requestID.String()
				reqAtStr := formatTimeISO(sr.reqAt)
				dlStr := formatTimeISO(sr.deadline)
				earStr := formatTimeISO(sr.earliest)
				latStr := formatTimeISO(sr.latest)
				serv := sr.serv

				item := SampleWorkItem{
					Kind:                 "sample",
					SampleID:             sidStr,
					SampleIDSnk:          &sidStr,
					RequestID:            reqStr,
					Status:               sr.status,
					Serviceability:       &serv,
					RequestedAt:          &reqAtStr,
					DeliveryDeadline:     &dlStr,
					EarliestCollectionAt: &earStr,
					LatestCollectionAt:   &latStr,
					History:              s.loadTimelineForEntities(ctx, s.db, []string{sidStr, reqStr}),
					LocationStale:        isLocationStale(sr.locRecAt, now),
				}
				if sr.activeJID != nil {
					jStr := sr.activeJID.String()
					item.JourneyID = &jStr
					item.ActiveJourneyID = &jStr
				}
				if sr.targetLabID != nil {
					lStr := sr.targetLabID.String()
					item.LaboratoryID = &lStr
				}
				if sr.holderID != nil {
					hStr := sr.holderID.String()
					item.CurrentHolderID = &hStr
				}
				if sr.requesterID != nil {
					rStr := sr.requesterID.String()
					item.RequesterID = &rStr
				}
				if sr.locRecAt != nil {
					tStr := formatTimeISO(*sr.locRecAt)
					item.LocationRecordedAt = &tStr
				}

				switch sr.status {
				case "requested", "pending":
					if matchesFilter(sr.status, "pending") {
						roleWork.Pending = append(roleWork.Pending, item)
					}
				case "received", "completed", "cancelled", "expired":
					if matchesFilter(sr.status, "completed") {
						roleWork.Completed = append(roleWork.Completed, item)
					}
				default:
					if matchesFilter(sr.status, "inProgress") {
						roleWork.InProgress = append(roleWork.InProgress, item)
					}
				}
			}
		}

	case "dispatcher", "administrator":
		sRows, err := s.db.Query(ctx, `
			SELECT sample_id, request_id, status, serviceability, requested_at,
			       delivery_deadline, earliest_collection_at, latest_collection_at,
			       active_journey_id, target_laboratory_id, current_holder_id, requester_id,
			       location_recorded_at
			FROM samples
			ORDER BY created_at DESC
		`)
		if err == nil {
			type sRow struct {
				sampleID    uuid.UUID
				requestID   uuid.UUID
				status      string
				serv        string
				reqAt       time.Time
				deadline    time.Time
				earliest    time.Time
				latest      time.Time
				activeJID   *uuid.UUID
				targetLabID *uuid.UUID
				holderID    *uuid.UUID
				requesterID *uuid.UUID
				locRecAt    *time.Time
			}
			var list []sRow
			for sRows.Next() {
				var sr sRow
				if err := sRows.Scan(
					&sr.sampleID, &sr.requestID, &sr.status, &sr.serv, &sr.reqAt,
					&sr.deadline, &sr.earliest, &sr.latest,
					&sr.activeJID, &sr.targetLabID, &sr.holderID, &sr.requesterID,
					&sr.locRecAt,
				); err == nil {
					list = append(list, sr)
				}
			}
			sRows.Close()

			for _, sr := range list {
				sidStr := sr.sampleID.String()
				reqStr := sr.requestID.String()
				reqAtStr := formatTimeISO(sr.reqAt)
				dlStr := formatTimeISO(sr.deadline)
				earStr := formatTimeISO(sr.earliest)
				latStr := formatTimeISO(sr.latest)
				serv := sr.serv

				item := SampleWorkItem{
					Kind:                 "sample",
					SampleID:             sidStr,
					SampleIDSnk:          &sidStr,
					RequestID:            reqStr,
					Status:               sr.status,
					Serviceability:       &serv,
					RequestedAt:          &reqAtStr,
					DeliveryDeadline:     &dlStr,
					EarliestCollectionAt: &earStr,
					LatestCollectionAt:   &latStr,
					History:              s.loadTimelineForEntities(ctx, s.db, []string{sidStr, reqStr}),
					LocationStale:        isLocationStale(sr.locRecAt, now),
				}
				if sr.activeJID != nil {
					jStr := sr.activeJID.String()
					item.JourneyID = &jStr
					item.ActiveJourneyID = &jStr
				}
				if sr.targetLabID != nil {
					lStr := sr.targetLabID.String()
					item.LaboratoryID = &lStr
				}
				if sr.holderID != nil {
					hStr := sr.holderID.String()
					item.CurrentHolderID = &hStr
				}
				if sr.requesterID != nil {
					rStr := sr.requesterID.String()
					item.RequesterID = &rStr
				}
				if sr.locRecAt != nil {
					tStr := formatTimeISO(*sr.locRecAt)
					item.LocationRecordedAt = &tStr
				}

				switch sr.status {
				case "requested", "pending":
					if matchesFilter(sr.status, "pending") {
						roleWork.Pending = append(roleWork.Pending, item)
					}
				case "received", "completed", "cancelled", "expired":
					if matchesFilter(sr.status, "completed") {
						roleWork.Completed = append(roleWork.Completed, item)
					}
				default:
					if matchesFilter(sr.status, "inProgress") {
						roleWork.InProgress = append(roleWork.InProgress, item)
					}
				}
			}
		}

		jRows, err := s.db.Query(ctx, `
			SELECT journey_id, status, route_mode, plan_version, sample_ids, estimated_delivery_at
			FROM journeys
			ORDER BY created_at DESC
		`)
		if err == nil {
			type jRow struct {
				jID      uuid.UUID
				status   string
				mode     string
				planVer  int
				samplesB []byte
				estDel   time.Time
			}
			var jList []jRow
			for jRows.Next() {
				var jr jRow
				if err := jRows.Scan(&jr.jID, &jr.status, &jr.mode, &jr.planVer, &jr.samplesB, &jr.estDel); err == nil {
					jList = append(jList, jr)
				}
			}
			jRows.Close()

			for _, jr := range jList {
				jidStr := jr.jID.String()
				var sids []string
				_ = json.Unmarshal(jr.samplesB, &sids)
				if sids == nil {
					sids = []string{}
				}
				var assignCnt int
				_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id = $1 AND active = TRUE`, jr.jID).Scan(&assignCnt)

				item := JourneyWorkItem{
					Kind:                "journey",
					JourneyID:           jidStr,
					JourneyIDSnk:        &jidStr,
					Status:              jr.status,
					RouteMode:           jr.mode,
					PlanVersion:         jr.planVer,
					SampleIDs:           sids,
					EstimatedDeliveryAt: formatTimeISO(jr.estDel),
					AssignmentCount:     assignCnt,
					History:             s.loadTimelineForEntities(ctx, s.db, append([]string{jidStr}, sids...)),
				}
				switch jr.status {
				case "planned":
					if matchesFilter(jr.status, "pending") {
						roleWork.Pending = append(roleWork.Pending, item)
					}
				case "completed", "cancelled", "replaced", "expired":
					if matchesFilter(jr.status, "completed") {
						roleWork.Completed = append(roleWork.Completed, item)
					}
				default:
					if matchesFilter(jr.status, "inProgress") {
						roleWork.InProgress = append(roleWork.InProgress, item)
					}
				}
			}
		}

	default:
		// Worker roles: collection_professional, delivery_partner, node_handler, laboratory_team
		targetKind := "transport"
		switch auth.ActiveRole {
		case "collection_professional":
			targetKind = "collection"
		case "delivery_partner":
			targetKind = "transport"
		case "node_handler":
			targetKind = "node"
		case "laboratory_team":
			targetKind = "laboratory"
		}

		aRows, err := s.db.Query(ctx, `
			SELECT assignment_id, journey_id, sample_id, kind, status, sequence,
			       worker_id, offered_to_worker_id, offer_expires_at,
			       from_location_id, to_location_id, node_id, incoming_from_location_id,
			       outgoing_to_location_id, laboratory_id, expected_sample_type_id
			FROM assignments
			WHERE kind = $1
			  AND (
			       worker_id = $2
			       OR offered_to_worker_id = $2
			       OR ($3::uuid IS NOT NULL AND (node_id = $3 OR laboratory_id = $3) AND worker_id IS NULL AND offered_to_worker_id IS NULL)
			  )
			ORDER BY sequence ASC
		`, targetKind, auth.UserID, auth.AssignedLocationID)
		if err == nil {
			type aRow struct {
				assignID  uuid.UUID
				journeyID uuid.UUID
				sampleID  uuid.UUID
				kind      string
				status    string
				seq       int
				workerID  *uuid.UUID
				offeredTo *uuid.UUID
				offerExp  *time.Time
				fromLoc   *uuid.UUID
				toLoc     *uuid.UUID
				nodeID    *uuid.UUID
				inFrom    *uuid.UUID
				outTo     *uuid.UUID
				labID     *uuid.UUID
				stID      *uuid.UUID
			}
			var aList []aRow
			for aRows.Next() {
				var ar aRow
				if err := aRows.Scan(
					&ar.assignID, &ar.journeyID, &ar.sampleID, &ar.kind, &ar.status, &ar.seq,
					&ar.workerID, &ar.offeredTo, &ar.offerExp,
					&ar.fromLoc, &ar.toLoc, &ar.nodeID, &ar.inFrom,
					&ar.outTo, &ar.labID, &ar.stID,
				); err == nil {
					aList = append(aList, ar)
				}
			}
			aRows.Close()

			for _, ar := range aList {
				aidStr := ar.assignID.String()
				sidStr := ar.sampleID.String()
				jidStr := ar.journeyID.String()
				seq := ar.seq
				item := AssignmentWorkItem{
					Kind:            ar.kind,
					AssignmentID:    aidStr,
					AssignmentIDSnk: &aidStr,
					SampleID:        sidStr,
					SampleIDSnk:     &sidStr,
					Status:          ar.status,
					JourneyID:       &jidStr,
					Sequence:        &seq,
					History:         s.loadTimelineForEntities(ctx, s.db, []string{aidStr, sidStr}),
				}
				if ar.fromLoc != nil {
					fStr := ar.fromLoc.String()
					item.FromLocationID = &fStr
				}
				if ar.toLoc != nil {
					tStr := ar.toLoc.String()
					item.ToLocationID = &tStr
				}
				if ar.offerExp != nil {
					eStr := formatTimeISO(*ar.offerExp)
					item.OfferExpiresAt = &eStr
				}
				if ar.nodeID != nil {
					nStr := ar.nodeID.String()
					item.NodeID = &nStr
				}
				if ar.inFrom != nil {
					iStr := ar.inFrom.String()
					item.IncomingFromLocationID = &iStr
				}
				if ar.outTo != nil {
					oStr := ar.outTo.String()
					item.OutgoingToLocationID = &oStr
				}
				if ar.labID != nil {
					lStr := ar.labID.String()
					item.LaboratoryID = &lStr
				}
				if ar.stID != nil {
					stStr := ar.stID.String()
					item.ExpectedSampleTypeID = &stStr
				}

				capLocID := ar.labID
				if capLocID == nil {
					capLocID = ar.nodeID
				}
				if capLocID == nil {
					capLocID = ar.toLoc
				}
				if capLocID == nil {
					capLocID = auth.AssignedLocationID
				}
				if capLocID != nil {
					if capObj, err := s.getLocationCapacity(ctx, s.db, *capLocID); err == nil {
						item.DestinationCapacity = &capObj
					}
				}

				switch ar.status {
				case "pending":
					if matchesFilter(ar.status, "pending") {
						roleWork.Pending = append(roleWork.Pending, item)
					}
				case "completed", "delivered", "cancelled":
					if matchesFilter(ar.status, "completed") {
						roleWork.Completed = append(roleWork.Completed, item)
					}
				default:
					if matchesFilter(ar.status, "inProgress") {
						roleWork.InProgress = append(roleWork.InProgress, item)
					}
				}
			}
		}
	}

	writeData(w, 200, roleWork)
}

func (s *Server) buildOperationsState(ctx context.Context, auth *AuthContext, sampleTypeFilter string) (*OperationsState, error) {
	now := time.Now().UTC()
	_ = s.expireTimedOutOffers(ctx, s.db, now)

	state := &OperationsState{
		Samples:                   []OperationsSample{},
		Workers:                   []OperationsWorker{},
		Locations:                 []OperationsLocation{},
		Connections:               []OperationsConnection{},
		Routes:                    []map[string]any{},
		Handoffs:                  []map[string]any{},
		Delays:                    []map[string]any{},
		Exceptions:                []map[string]any{},
		AssignmentCountSpread:     0,
		IneligibleAssignmentCount: 0,
	}

	var filterStID *uuid.UUID
	if sampleTypeFilter != "" {
		if id, err := uuid.Parse(sampleTypeFilter); err == nil {
			filterStID = &id
		}
	}

	// 1. Samples
	sRows, err := s.db.Query(ctx, `
		SELECT sample_id, request_id, sample_type_id, status, origin_lat, origin_lng,
		       delivery_deadline, current_holder_id, active_journey_id, target_laboratory_id,
		       latest_location_lat, latest_location_lng, location_recorded_at, requester_id
		FROM samples
		ORDER BY created_at DESC
	`)
	if err == nil {
		for sRows.Next() {
			var sID, reqID, stID uuid.UUID
			var status string
			var origLat, origLng float64
			var deadline time.Time
			var holderID, activeJID, targetLabID, requesterID *uuid.UUID
			var lat, lng *float64
			var locRecAt *time.Time
			if err := sRows.Scan(
				&sID, &reqID, &stID, &status, &origLat, &origLng,
				&deadline, &holderID, &activeJID, &targetLabID,
				&lat, &lng, &locRecAt, &requesterID,
			); err == nil {
				if filterStID != nil && stID != *filterStID {
					continue
				}
				if auth.ActiveRole == "requester" && (requesterID == nil || *requesterID != auth.UserID) {
					continue
				}
				sidStr := sID.String()
				reqStr := reqID.String()
				dlStr := formatTimeISO(deadline)
				orig := Coordinate{Latitude: origLat, Longitude: origLng}
				os := OperationsSample{
					SampleID:         sidStr,
					SampleIDSnk:      &sidStr,
					Status:           status,
					RequestID:        &reqStr,
					Origin:           &orig,
					DeliveryDeadline: &dlStr,
					LocationStale:    isLocationStale(locRecAt, now),
				}
				if holderID != nil {
					hStr := holderID.String()
					os.CurrentHolderID = &hStr
				}
				if activeJID != nil {
					jStr := activeJID.String()
					os.ActiveJourneyID = &jStr
				}
				if lat != nil && lng != nil {
					c := Coordinate{Latitude: *lat, Longitude: *lng}
					os.LatestLocation = &c
				}
				if locRecAt != nil {
					tStr := formatTimeISO(*locRecAt)
					os.LocationRecordedAt = &tStr
				}
				state.Samples = append(state.Samples, os)

				if status != "received" && status != "cancelled" && now.After(deadline) {
					state.Delays = append(state.Delays, map[string]any{
						"sampleId":         sidStr,
						"status":           status,
						"deliveryDeadline": dlStr,
						"reason":           "delivery_deadline_exceeded",
					})
				}
			}
		}
		sRows.Close()
	}

	// 2. Workers
	wRows, err := s.db.Query(ctx, `
		SELECT user_id, full_name, roles, available, capacity_units, assignment_count,
		       latest_location_lat, latest_location_lng, location_recorded_at
		FROM users
		WHERE active = TRUE
		ORDER BY created_at ASC
	`)
	minAssign := -1
	maxAssign := -1
	if err == nil {
		for wRows.Next() {
			var uID uuid.UUID
			var fullName string
			var rolesB []byte
			var avail bool
			var capUnits, assignCnt int
			var lat, lng *float64
			var locRecAt *time.Time
			if err := wRows.Scan(&uID, &fullName, &rolesB, &avail, &capUnits, &assignCnt, &lat, &lng, &locRecAt); err == nil {
				var roles []string
				_ = json.Unmarshal(rolesB, &roles)
				isWorker := false
				for _, r := range roles {
					if r == "collection_professional" || r == "delivery_partner" || r == "node_handler" || r == "laboratory_team" {
						isWorker = true
						break
					}
				}
				if !isWorker {
					continue
				}
				widStr := uID.String()
				stStr := "unavailable"
				if avail && capUnits > 0 {
					stStr = "available"
				}
				ow := OperationsWorker{
					WorkerID:        widStr,
					WorkerIDSnk:     &widStr,
					FullName:        &fullName,
					Roles:           roles,
					Available:       avail,
					Status:          stStr,
					CapacityUnits:   capUnits,
					AssignmentCount: assignCnt,
					LocationStale:   isLocationStale(locRecAt, now),
				}
				if lat != nil && lng != nil {
					c := Coordinate{Latitude: *lat, Longitude: *lng}
					ow.LatestLocation = &c
					ow.LatestLocationSnk = &c
				}
				if locRecAt != nil {
					tStr := formatTimeISO(*locRecAt)
					ow.LocationRecordedAt = &tStr
				}
				state.Workers = append(state.Workers, ow)

				if avail && capUnits > 0 && (hasString(roles, "collection_professional") || hasString(roles, "delivery_partner")) {
					if minAssign == -1 || assignCnt < minAssign {
						minAssign = assignCnt
					}
					if maxAssign == -1 || assignCnt > maxAssign {
						maxAssign = assignCnt
					}
				}
			}
		}
		wRows.Close()
	}
	if minAssign >= 0 && maxAssign >= minAssign {
		state.AssignmentCountSpread = maxAssign - minAssign
	}

	// 3. Locations
	locMap, err := s.loadLocationsMap(ctx, s.db)
	if err == nil {
		for _, loc := range locMap {
			if (auth.ActiveRole == "node_handler" || auth.ActiveRole == "laboratory_team") && auth.AssignedLocationID != nil {
				if loc.LocationID != *auth.AssignedLocationID {
					continue
				}
			}
			capObj, _ := s.getLocationCapacity(ctx, s.db, loc.LocationID)
			lidStr := loc.LocationID.String()
			ol := OperationsLocation{
				LocationID:            lidStr,
				LocationIDSnk:         &lidStr,
				Name:                  loc.Name,
				Coordinates:           loc.Coordinates,
				Functions:             loc.Functions,
				ActiveFunctions:       loc.ActiveFunctions,
				Active:                loc.Active,
				HandlingMinutes:       loc.HandlingMinutes,
				Capacity:              capObj,
				AcceptedSampleTypeIDs: loc.AcceptedSampleTypeIDs,
			}
			state.Locations = append(state.Locations, ol)
		}
	}

	// 4. Connections
	conns, err := s.loadConnectionsList(ctx, s.db)
	if err == nil {
		for _, c := range conns {
			capObj, _ := s.getConnectionCapacity(ctx, s.db, c.ConnectionID)
			cidStr := c.ConnectionID.String()
			fromStr := c.FromLocationID.String()
			toStr := c.ToLocationID.String()
			oc := OperationsConnection{
				ConnectionID:      cidStr,
				ConnectionIDSnk:   &cidStr,
				FromLocationID:    fromStr,
				ToLocationID:      toStr,
				Active:            c.Active,
				TravelMinutes:     c.TravelMinutes,
				SupportsCooled:    c.SupportsCooled,
				CostUnits:         c.CostUnits,
				ConsolidationHold: c.ConsolidationHold,
				Capacity:          capObj,
			}
			state.Connections = append(state.Connections, oc)
		}
	}

	// 5. Routes (active journeys)
	jRows, err := s.db.Query(ctx, `
		SELECT journey_id, status, route_mode, plan_version, sample_ids, estimated_delivery_at, total_cost_units
		FROM journeys
		ORDER BY created_at DESC
	`)
	if err == nil {
		for jRows.Next() {
			var jID uuid.UUID
			var status, mode string
			var planVer int
			var samplesB []byte
			var estDel time.Time
			var cost float64
			if err := jRows.Scan(&jID, &status, &mode, &planVer, &samplesB, &estDel, &cost); err == nil {
				var sids []string
				_ = json.Unmarshal(samplesB, &sids)
				if filterStID != nil {
					matched := false
					for _, sidStr := range sids {
						if sid, err := uuid.Parse(sidStr); err == nil {
							var stID uuid.UUID
							if err := s.db.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id = $1`, sid).Scan(&stID); err == nil && stID == *filterStID {
								matched = true
								break
							}
						}
					}
					if !matched {
						continue
					}
				}
				state.Routes = append(state.Routes, map[string]any{
					"journeyId":           jID.String(),
					"status":              status,
					"routeMode":           mode,
					"planVersion":         planVer,
					"sampleIds":           sids,
					"estimatedDeliveryAt": formatTimeISO(estDel),
					"totalCostUnits":      cost,
				})
			}
		}
		jRows.Close()
	}

	// 6. Handoffs
	hRows, err := s.db.Query(ctx, `
		SELECT handoff_id, sample_id, sender_id, receiver_id, status, current_holder_id,
		       sender_confirmed, receiver_confirmed, initiated_at, confirmed_at
		FROM handoffs
		ORDER BY initiated_at DESC
	`)
	if err == nil {
		for hRows.Next() {
			var hID, sID, senderID, receiverID, holderID uuid.UUID
			var status string
			var sConf, rConf bool
			var initAt time.Time
			var confAt *time.Time
			if err := hRows.Scan(&hID, &sID, &senderID, &receiverID, &status, &holderID, &sConf, &rConf, &initAt, &confAt); err == nil {
				if filterStID != nil {
					var stID uuid.UUID
					if err := s.db.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id = $1`, sID).Scan(&stID); err != nil || stID != *filterStID {
						continue
					}
				}
				hm := map[string]any{
					"handoffId":         hID.String(),
					"sampleId":          sID.String(),
					"senderId":          senderID.String(),
					"receiverId":        receiverID.String(),
					"status":            status,
					"currentHolderId":   holderID.String(),
					"senderConfirmed":   sConf,
					"receiverConfirmed": rConf,
					"initiatedAt":       formatTimeISO(initAt),
				}
				if confAt != nil {
					hm["confirmedAt"] = formatTimeISO(*confAt)
				}
				state.Handoffs = append(state.Handoffs, hm)
			}
		}
		hRows.Close()
	}

	// 7. Exceptions
	eRows, err := s.db.Query(ctx, `
		SELECT exception_id, sample_id, laboratory_id, reason, details, observed_at
		FROM exceptions
		ORDER BY observed_at DESC
	`)
	if err == nil {
		for eRows.Next() {
			var eID, sID uuid.UUID
			var labID *uuid.UUID
			var reason string
			var details *string
			var obsAt time.Time
			if err := eRows.Scan(&eID, &sID, &labID, &reason, &details, &obsAt); err == nil {
				if filterStID != nil {
					var stID uuid.UUID
					if err := s.db.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id = $1`, sID).Scan(&stID); err != nil || stID != *filterStID {
						continue
					}
				}
				em := map[string]any{
					"exceptionId": eID.String(),
					"sampleId":    sID.String(),
					"reason":      reason,
					"observedAt":  formatTimeISO(obsAt),
				}
				if labID != nil {
					em["laboratoryId"] = labID.String()
				}
				if details != nil {
					em["details"] = *details
				}
				state.Exceptions = append(state.Exceptions, em)
			}
		}
		eRows.Close()
	}

	return state, nil
}

func (s *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "read_operations_state", "dispatcher", "administrator", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		Filters *struct {
			SampleTypeID    *string `json:"sampleTypeId"`
			SampleTypeIDSnk *string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if _, err := decodeStrictJSON(r, &req, true); err != nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}

	stFilter := ""
	if req.Filters != nil {
		if req.Filters.SampleTypeID != nil && *req.Filters.SampleTypeID != "" {
			stFilter = *req.Filters.SampleTypeID
		} else if req.Filters.SampleTypeIDSnk != nil && *req.Filters.SampleTypeIDSnk != "" {
			stFilter = *req.Filters.SampleTypeIDSnk
		}
		if stFilter != "" {
			if _, err := uuid.Parse(stFilter); err != nil {
				writeError(w, 400, "invalid_json", "Invalid sampleTypeId filter")
				return
			}
		}
	}

	state, err := s.buildOperationsState(ctx, auth, stFilter)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to read operations state")
		return
	}

	writeData(w, 200, state)
}

func (s *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	_, ok := s.requireRole(ctx, w, r, "search_audit_trail", "dispatcher", "administrator")
	if !ok {
		return
	}

	var req struct {
		Query      *string `json:"query"`
		ActorID    *string `json:"actorId"`
		EntityType *string `json:"entityType"`
		EntityID   *string `json:"entityId"`
		Action     *string `json:"action"`
		Role       *string `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      *string `json:"order"`
	}
	if _, err := decodeStrictJSON(r, &req, true); err != nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}

	limit := 500
	if req.Limit != nil {
		if *req.Limit < 1 || *req.Limit > 5000 {
			writeError(w, 400, "invalid_limit", "limit must be between 1 and 5000")
			return
		}
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil {
		if *req.Offset < 0 {
			writeError(w, 400, "invalid_offset", "offset must be >= 0")
			return
		}
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != nil && *req.Order != "" {
		if *req.Order != "newest_first" && *req.Order != "oldest_first" {
			writeError(w, 400, "invalid_order", "order must be newest_first or oldest_first")
			return
		}
		order = *req.Order
	}

	var fromTime, toTime *time.Time
	if req.FromTime != nil && *req.FromTime != "" {
		ft, err := parseTimeISO(*req.FromTime)
		if err != nil {
			writeError(w, 400, "invalid_time", "Invalid fromTime")
			return
		}
		fromTime = &ft
	}
	if req.ToTime != nil && *req.ToTime != "" {
		tt, err := parseTimeISO(*req.ToTime)
		if err != nil {
			writeError(w, 400, "invalid_time", "Invalid toTime")
			return
		}
		toTime = &tt
	}

	conditions := []string{"1=1"}
	args := []any{}
	argIdx := 1

	if req.ActorID != nil && strings.TrimSpace(*req.ActorID) != "" {
		conditions = append(conditions, fmt.Sprintf("actor_id = $%d", argIdx))
		args = append(args, strings.TrimSpace(*req.ActorID))
		argIdx++
	}
	if req.EntityType != nil && strings.TrimSpace(*req.EntityType) != "" {
		conditions = append(conditions, fmt.Sprintf("entity_type = $%d", argIdx))
		args = append(args, strings.TrimSpace(*req.EntityType))
		argIdx++
	}
	if req.EntityID != nil && strings.TrimSpace(*req.EntityID) != "" {
		entID := strings.TrimSpace(*req.EntityID)
		relatedIDs := []string{entID}
		if uid, err := uuid.Parse(entID); err == nil {
			var sID, rID uuid.UUID
			if err := s.db.QueryRow(ctx, `SELECT sample_id, request_id FROM samples WHERE sample_id = $1 OR request_id = $1 LIMIT 1`, uid).Scan(&sID, &rID); err == nil {
				if !hasString(relatedIDs, sID.String()) {
					relatedIDs = append(relatedIDs, sID.String())
				}
				if !hasString(relatedIDs, rID.String()) {
					relatedIDs = append(relatedIDs, rID.String())
				}
			}
		}
		conditions = append(conditions, fmt.Sprintf("(entity_id = ANY($%d) OR details->>'sampleId' = ANY($%d) OR details->>'requestId' = ANY($%d))", argIdx, argIdx, argIdx))
		args = append(args, relatedIDs)
		argIdx++
	}
	if req.Action != nil && strings.TrimSpace(*req.Action) != "" {
		conditions = append(conditions, fmt.Sprintf("action = $%d", argIdx))
		args = append(args, strings.TrimSpace(*req.Action))
		argIdx++
	}
	if req.Role != nil && strings.TrimSpace(*req.Role) != "" {
		conditions = append(conditions, fmt.Sprintf("role = $%d", argIdx))
		args = append(args, strings.TrimSpace(*req.Role))
		argIdx++
	}
	if req.Success != nil {
		conditions = append(conditions, fmt.Sprintf("success = $%d", argIdx))
		args = append(args, *req.Success)
		argIdx++
	}
	if fromTime != nil {
		conditions = append(conditions, fmt.Sprintf("occurred_at >= $%d", argIdx))
		args = append(args, *fromTime)
		argIdx++
	}
	if toTime != nil {
		conditions = append(conditions, fmt.Sprintf("occurred_at <= $%d", argIdx))
		args = append(args, *toTime)
		argIdx++
	}
	if req.Query != nil && strings.TrimSpace(*req.Query) != "" {
		qStr := "%" + strings.TrimSpace(*req.Query) + "%"
		conditions = append(conditions, fmt.Sprintf("(action ILIKE $%d OR entity_type ILIKE $%d OR entity_id ILIKE $%d OR actor_id ILIKE $%d OR role ILIKE $%d OR details::text ILIKE $%d)", argIdx, argIdx, argIdx, argIdx, argIdx, argIdx))
		args = append(args, qStr)
		argIdx++
	}

	whereClause := strings.Join(conditions, " AND ")

	var total int
	countSQL := fmt.Sprintf("SELECT COUNT(*) FROM audit_logs WHERE %s", whereClause)
	_ = s.db.QueryRow(ctx, countSQL, args...).Scan(&total)

	orderSQL := "DESC"
	if order == "oldest_first" {
		orderSQL = "ASC"
	}

	querySQL := fmt.Sprintf(`
		SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_logs
		WHERE %s
		ORDER BY occurred_at %s, seq %s
		LIMIT $%d OFFSET $%d
	`, whereClause, orderSQL, orderSQL, argIdx, argIdx+1)
	queryArgs := append(append([]any{}, args...), limit, offset)

	rows, err := s.db.Query(ctx, querySQL, queryArgs...)
	entries := []AuditEntry{}
	if err == nil {
		for rows.Next() {
			var aID uuid.UUID
			var actorID, roleStr, actionStr, entType, entID string
			var success bool
			var occAt time.Time
			var detB []byte
			if err := rows.Scan(&aID, &actorID, &roleStr, &actionStr, &entType, &entID, &success, &occAt, &detB); err == nil {
				var det map[string]any
				_ = json.Unmarshal(detB, &det)
				if det == nil {
					det = map[string]any{}
				}
				entries = append(entries, AuditEntry{
					AuditID:    aID.String(),
					ActorID:    actorID,
					Role:       roleStr,
					Action:     actionStr,
					EntityType: entType,
					EntityID:   entID,
					Success:    success,
					OccurredAt: formatTimeISO(occAt),
					Details:    det,
				})
			}
		}
		rows.Close()
	}

	hasMore := offset+len(entries) < total
	var nextOffset *int
	if hasMore {
		no := offset + len(entries)
		nextOffset = &no
	}

	res := AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}
	writeData(w, 200, res)
}

func (s *Server) handleStreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, err := s.authenticateRequest(ctx, r)
	if err != nil {
		writeError(w, 401, "unauthorized", "Authentication required")
		return
	}

	var since int64 = 0
	if sinceStr := strings.TrimSpace(r.URL.Query().Get("since")); sinceStr != "" {
		if v, err := strconv.ParseInt(sinceStr, 10, 64); err == nil && v >= 0 {
			since = v
		}
	}

	rows, err := s.db.Query(ctx, `
		SELECT id, type, entity_type, entity_id, payload, created_at
		FROM realtime_events
		WHERE id > $1
		ORDER BY id ASC
		LIMIT 500
	`, since)
	events := []RealtimeEvent{}
	var cursor int64 = since
	if err == nil {
		var rawEvents []RealtimeEvent
		for rows.Next() {
			var id int64
			var evType, entType, entID string
			var payB []byte
			var createdAt time.Time
			if err := rows.Scan(&id, &evType, &entType, &entID, &payB, &createdAt); err == nil {
				var pay map[string]any
				_ = json.Unmarshal(payB, &pay)
				if pay == nil {
					pay = map[string]any{}
				}
				rawEvents = append(rawEvents, RealtimeEvent{
					ID:         id,
					Type:       evType,
					EntityType: entType,
					EntityID:   entID,
					Payload:    pay,
					CreatedAt:  formatTimeISO(createdAt),
				})
				if id > cursor {
					cursor = id
				}
			}
		}
		rows.Close()

		for _, ev := range rawEvents {
			if s.canSessionReceiveEvent(ctx, auth.SessionToken, ev) {
				events = append(events, ev)
			}
		}
	}

	if websocket.IsWebSocketUpgrade(r) || strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		respHeader := http.Header{}
		if proto := r.Header.Get("Sec-WebSocket-Protocol"); proto != "" {
			parts := strings.Split(proto, ",")
			selectedProto := ""
			for _, p := range parts {
				pt := strings.TrimSpace(p)
				if pt == "lab-logistics-v1" {
					selectedProto = pt
					break
				}
			}
			if selectedProto == "" {
				for _, p := range parts {
					pt := strings.TrimSpace(p)
					if pt != "" && !strings.HasPrefix(pt, "bearer.") && !strings.HasPrefix(strings.ToLower(pt), "bearer ") {
						selectedProto = pt
						break
					}
				}
			}
			if selectedProto == "" && len(parts) > 0 {
				selectedProto = strings.TrimSpace(parts[0])
			}
			if selectedProto != "" {
				respHeader.Set("Sec-WebSocket-Protocol", selectedProto)
			}
		}
		conn, err := s.upgrader.Upgrade(w, r, respHeader)
		if err != nil {
			return
		}
		s.wsMu.Lock()
		s.wsConns[conn] = auth.SessionToken
		s.wsMu.Unlock()

		for _, ev := range events {
			if msg, err := json.Marshal(ev); err == nil {
				_ = conn.SetWriteDeadline(time.Now().Add(2 * time.Second))
				_ = conn.WriteMessage(websocket.TextMessage, msg)
			}
		}

		go func() {
			defer func() {
				s.wsMu.Lock()
				delete(s.wsConns, conn)
				s.wsMu.Unlock()
				_ = conn.Close()
			}()
			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					return
				}
			}
		}()
		return
	}

	writeData(w, 200, map[string]any{
		"events": events,
		"cursor": cursor,
	})
}

func (s *Server) handleReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, err := s.authenticateRequest(ctx, r)
	if err != nil {
		writeError(w, 401, "unauthorized", "Authentication required")
		return
	}

	now := time.Now().UTC()
	_ = s.expireTimedOutOffers(ctx, s.db, now)

	roleSelectionRequired := !auth.RoleSelected || auth.ActiveRole == ""
	userObj := map[string]any{
		"userId":                auth.UserID.String(),
		"username":              auth.Username,
		"fullName":              auth.FullName,
		"roles":                 auth.Roles,
		"activeRole":            auth.ActiveRole,
		"roleSelectionRequired": roleSelectionRequired,
	}

	reqSamples := []map[string]any{}
	if hasString(auth.Roles, "requester") {
		rows, err := s.db.Query(ctx, `
			SELECT sample_id, request_id, status, serviceability, requested_at,
			       delivery_deadline, active_journey_id, target_laboratory_id, current_holder_id,
			       location_recorded_at
			FROM samples
			WHERE requester_id = $1
			ORDER BY created_at DESC
		`, auth.UserID)
		if err == nil {
			for rows.Next() {
				var sID, reqID uuid.UUID
				var status, serv string
				var reqAt, dl time.Time
				var activeJID, labID, holderID *uuid.UUID
				var locRecAt *time.Time
				if err := rows.Scan(&sID, &reqID, &status, &serv, &reqAt, &dl, &activeJID, &labID, &holderID, &locRecAt); err == nil {
					m := map[string]any{
						"sampleId":         sID.String(),
						"requestId":        reqID.String(),
						"status":           status,
						"serviceability":   serv,
						"requestedAt":      formatTimeISO(reqAt),
						"deliveryDeadline": formatTimeISO(dl),
						"locationStale":    isLocationStale(locRecAt, now),
					}
					if activeJID != nil {
						m["activeJourneyId"] = activeJID.String()
					}
					if labID != nil {
						m["laboratoryId"] = labID.String()
					}
					if holderID != nil {
						m["currentHolderId"] = holderID.String()
					}
					if locRecAt != nil {
						m["locationRecordedAt"] = formatTimeISO(*locRecAt)
					}
					reqSamples = append(reqSamples, m)
				}
			}
			rows.Close()
		}
	}

	ops, _ := s.buildOperationsState(ctx, auth, "")
	writeData(w, 200, map[string]any{
		"user":             userObj,
		"serverTime":       formatTimeISO(now),
		"requesterSamples": reqSamples,
		"operations":       ops,
	})
}

