func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
        if r.Method != http.MethodPost {
                writeError(w, 405, "method_not_allowed", "Method not allowed")
                return
        }
        ctx := r.Context()
        auth, ok := s.requireRole(ctx, w, r, "confirm_handoff", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
        if !ok {
                return
        }

        var req struct {
                HandoffID        *string `json:"handoffId"`
                ConfirmationSide *string `json:"confirmationSide"`
                ConfirmedAt      *string `json:"confirmedAt"`
                IdempotencyKey   *string `json:"idempotencyKey"`
        }
        rawBody, err := decodeStrictJSON(r, &req, false)
        if err != nil || req.HandoffID == nil || req.ConfirmationSide == nil || req.ConfirmedAt == nil {
                writeError(w, 400, "invalid_json", "Invalid request body")
                return
        }
        if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
                writeError(w, 400, "idempotency_required", "idempotencyKey is required")
                return
        }
        idemKey := strings.TrimSpace(*req.IdempotencyKey)
        if done := s.checkIdempotency(ctx, w, "confirm_handoff", idemKey, rawBody); done {
                return
        }

        side := *req.ConfirmationSide
        if side != "sender" && side != "receiver" {
                writeError(w, 400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
                return
        }
        handoffID, err := uuid.Parse(*req.HandoffID)
        if err != nil {
                writeError(w, 400, "invalid_json", "Invalid handoffId")
                return
        }
        confirmedAt, err := parseTimeISO(*req.ConfirmedAt)
        if err != nil {
                writeError(w, 400, "invalid_time", "Invalid confirmedAt")
                return
        }

        var sampleID, journeyID, fromAssignID, toAssignID, senderID, receiverID uuid.UUID
        var hStatus string
        var sConf, rConf, active bool
        var initAt time.Time

        err = s.db.QueryRow(ctx, `
                SELECT sample_id, journey_id, from_assignment_id, to_assignment_id,
                       sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, initiated_at, active
                FROM handoffs WHERE handoff_id = $1
        `, handoffID).Scan(&sampleID, &journeyID, &fromAssignID, &toAssignID, &senderID, &receiverID, &hStatus, &sConf, &rConf, &initAt, &active)
        if err != nil {
                writeError(w, 404, "not_found", "Handoff not found")
                return
        }
        if !active || hStatus == "cancelled" {
                writeError(w, 409, "handoff_inactive", "Handoff is inactive")
                return
        }
        if confirmedAt.Before(initAt) {
                writeError(w, 409, "invalid_confirmation_time", "Confirmation time precedes handoff initiation")
                return
        }

        if side == "sender" && auth.UserID != senderID {
                writeError(w, 403, "forbidden", "Actor is not the handoff sender")
                return
        }
        if side == "receiver" && auth.UserID != receiverID {
                writeError(w, 403, "forbidden", "Actor is not the handoff receiver")
                return
        }

        var currentHolderID *uuid.UUID
        _ = s.db.QueryRow(ctx, `SELECT current_holder_id FROM samples WHERE sample_id = $1`, sampleID).Scan(&currentHolderID)

        // If already confirmed, return idempotent confirmed state without duplicate custody transfer
        if hStatus == "confirmed" {
                holderStr := receiverID.String()
                if currentHolderID != nil {
                        holderStr = currentHolderID.String()
                }
                resp := map[string]any{
                        "handoffId":         handoffID.String(),
                        "status":            "confirmed",
                        "senderConfirmed":   true,
                        "receiverConfirmed": true,
                        "currentHolderId":   holderStr,
                }
                s.saveIdempotency(ctx, "confirm_handoff", idemKey, rawBody, 201, resp)
                writeData(w, 201, resp)
                return
        }

        if currentHolderID == nil || *currentHolderID != senderID {
                writeError(w, 409, "custody_conflict", "Sender no longer holds custody of the sample")
                return
        }

        if side == "sender" {
                sConf = true
                _, _ = s.db.Exec(ctx, `UPDATE handoffs SET sender_confirmed = TRUE, sender_confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)
        } else {
                rConf = true
                _, _ = s.db.Exec(ctx, `UPDATE handoffs SET receiver_confirmed = TRUE, receiver_confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)
        }

        newHolder := senderID
        if sConf && rConf {
                hStatus = "confirmed"
                newHolder = receiverID
                _, _ = s.db.Exec(ctx, `UPDATE handoffs SET status = 'confirmed', confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)

                // Transfer custody on sample
                var fromToLoc *uuid.UUID
                var fromSeq, toSeq int
                _ = s.db.QueryRow(ctx, `SELECT to_location_id, sequence FROM assignments WHERE assignment_id = $1`, fromAssignID).Scan(&fromToLoc, &fromSeq)
                _ = s.db.QueryRow(ctx, `SELECT sequence FROM assignments WHERE assignment_id = $1`, toAssignID).Scan(&toSeq)

                if fromToLoc != nil {
                        var lat, lng float64
                        if err := s.db.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE location_id = $1`, *fromToLoc).Scan(&lat, &lng); err == nil {
                                _, _ = s.db.Exec(ctx, `
                                        UPDATE samples SET current_holder_id = $1, latest_lat = $2, latest_lng = $3, location_recorded_at = $4
                                        WHERE sample_id = $5
                                `, receiverID, lat, lng, confirmedAt, sampleID)
                        } else {
                                _, _ = s.db.Exec(ctx, `UPDATE samples SET current_holder_id = $1, location_recorded_at = $2 WHERE sample_id = $3`, receiverID, confirmedAt, sampleID)
                        }
                        // Mark stop at fromToLoc completed
                        _, _ = s.db.Exec(ctx, `
                                UPDATE journey_stops SET completed_at = COALESCE(completed_at, $1)
                                WHERE journey_id = $2 AND location_id = $3 AND stop_type IN ('pickup', 'handoff')
                        `, confirmedAt, journeyID, *fromToLoc)
                } else {
                        _, _ = s.db.Exec(ctx, `UPDATE samples SET current_holder_id = $1, location_recorded_at = $2 WHERE sample_id = $3`, receiverID, confirmedAt, sampleID)
                }

                // Mark fromAssignment completed
                _, _ = s.db.Exec(ctx, `
                        UPDATE assignments SET status = 'completed', completed_at = COALESCE(completed_at, $1)
                        WHERE assignment_id = $2
                `, confirmedAt, fromAssignID)

