		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "collect_and_seal_sample", idemKey, rawBody); done {
		return
	}

	sampleID, err1 := uuid.Parse(*req.SampleID)
	assignID, err2 := uuid.Parse(*req.AssignmentID)
	if err1 != nil || err2 != nil {
		writeError(w, 400, "invalid_json", "Invalid UUID")
		return
	}
	collectedAt, err := parseTimeISO(*req.CollectedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid collectedAt")
		return
	}

	var aSampleID, aJourneyID uuid.UUID
	var aKind, aStatus string
	var aWorkerID, aOfferedTo *uuid.UUID
	var aActive bool
	err = s.db.QueryRow(ctx, `
		SELECT sample_id, journey_id, kind, status, worker_id, offered_to_worker_id, active
		FROM assignments WHERE assignment_id = $1
	`, assignID).Scan(&aSampleID, &aJourneyID, &aKind, &aStatus, &aWorkerID, &aOfferedTo, &aActive)
	if err != nil {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}

	var stID uuid.UUID
	var sCont string
	var tMin, tMax, origLat, origLng float64
	var reqAt, deadline, earliest, latest time.Time
	var sStatus string
	var sealed bool
	err = s.db.QueryRow(ctx, `
		SELECT sample_type_id, container_type, temperature_min_c, temperature_max_c,
		       origin_lat, origin_lng, requested_at, delivery_deadline,
		       earliest_collection_at, latest_collection_at, status, sealed
		FROM samples WHERE sample_id = $1
	`, sampleID).Scan(&stID, &sCont, &tMin, &tMax, &origLat, &origLng, &reqAt, &deadline, &earliest, &latest, &sStatus, &sealed)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	if aSampleID != sampleID || aKind != "collection" {
		writeError(w, 403, "forbidden", "Assignment does not match sample collection")
		return
	}
	if !aActive || aStatus == "cancelled" {
		writeError(w, 409, "assignment_inactive", "Assignment is inactive")
		return
	}
	if aWorkerID == nil {
		if aOfferedTo != nil && *aOfferedTo == auth.UserID {
			writeError(w, 409, "collection_not_ready", "Assignment must be accepted before collecting")
			return
		}
		writeError(w, 403, "forbidden", "Assignment does not belong to worker")
		return
	}
	if *aWorkerID != auth.UserID {
		writeError(w, 403, "forbidden", "Assignment belongs to another worker")
		return
	}
	if sealed || sStatus == "cancelled" || sStatus == "received" || sStatus == "expired" {
		writeError(w, 409, "invalid_sample_state", "Sample is already sealed or in terminal state")
		return
	}

	// Check certification active at collectedAt
	st, _ := s.loadSampleType(ctx, s.db, stID)
	if !isWorkerQualifiedForSampleType(auth.Qualifications, auth.Certifications, st, collectedAt) {
		writeError(w, 409, "certification_inactive", "Worker certification is inactive or expired")
		return
	}

	// Check collection window
	if collectedAt.Before(earliest) || collectedAt.After(latest) {
		writeError(w, 409, "outside_collection_window", "Collection timestamp is outside the allowed collection window")
		return
	}
	if collectedAt.After(deadline) || collectedAt.Before(reqAt) {
		writeError(w, 409, "invalid_collection_time", "Invalid collection time")
		return
	}

	// Check handling compliance
	if *req.ContainerType != sCont || *req.ObservedTemperatureC < tMin || *req.ObservedTemperatureC > tMax {
		writeError(w, 400, "handling_noncompliant", "Observed container or temperature is non-compliant")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE samples
		SET status = 'sealed', sealed = TRUE, sealed_at = $1, current_holder_id = $2,
		    latest_lat = $3, latest_lng = $4, location_recorded_at = $1
		WHERE sample_id = $5
	`, collectedAt, auth.UserID, origLat, origLng, sampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update sample")
		return
	}

	_, _ = s.db.Exec(ctx, `
		UPDATE assignments
		SET status = 'completed', completed_at = $1, last_progress_at = $1
		WHERE assignment_id = $2
	`, collectedAt, assignID)

	_, _ = s.db.Exec(ctx, `
		UPDATE journey_stops
		SET completed_at = $1
		WHERE journey_id = $2 AND sequence = 1
	`, collectedAt, aJourneyID)

	_, _ = s.db.Exec(ctx, `
		UPDATE journeys SET status = 'in_progress' WHERE journey_id = $1 AND status = 'planned'
	`, aJourneyID)

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "collect_and_seal_sample", "sample", sampleID.String(), true, collectedAt, map[string]any{
		"assignmentId":         assignID.String(),
		"containerType":        *req.ContainerType,
		"observedTemperatureC": *req.ObservedTemperatureC,
		"currentHolderId":      auth.UserID.String(),
	})
	s.publishEvent(ctx, s.db, "sample_sealed", "sample", sampleID.String(), map[string]any{
		"sampleId":        sampleID.String(),
		"status":          "sealed",
		"currentHolderId": auth.UserID.String(),
	})

	resp := map[string]any{
		"sampleId":          sampleID.String(),
		"status":            "sealed",
		"currentHolderId":   auth.UserID.String(),
		"sealedAt":          formatTimeISO(collectedAt),
		"handlingCompliant": true,
	}
	s.saveIdempotency(ctx, "collect_and_seal_sample", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "update_assignment_progress", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		Status         *string `json:"status"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.AssignmentID == nil || req.Status == nil || req.OccurredAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "update_assignment_progress", idemKey, rawBody); done {
		return
	}

	newStatus := *req.Status
	validStatuses := []string{"at_pickup", "picked_up", "in_transit", "arrived", "delivered", "in_progress", "completed"}
	if !hasString(validStatuses, newStatus) {
		writeError(w, 400, "invalid_json", "Invalid status")
		return
	}

	assignID, err := uuid.Parse(*req.AssignmentID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid assignmentId")
		return
	}
	occurredAt, err := parseTimeISO(*req.OccurredAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid occurredAt")
		return
	}

	var sampleID, journeyID uuid.UUID
	var kind, curStatus string
	var seq int
	var workerID, offeredTo, fromLocID, toLocID *uuid.UUID
	var lastProg *time.Time
	var active bool

	err = s.db.QueryRow(ctx, `
		SELECT sample_id, journey_id, kind, sequence, status, worker_id, offered_to_worker_id,
		       from_location_id, to_location_id, last_progress_at, active
		FROM assignments WHERE assignment_id = $1
	`, assignID).Scan(&sampleID, &journeyID, &kind, &seq, &curStatus, &workerID, &offeredTo, &fromLocID, &toLocID, &lastProg, &active)
	if err != nil {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if !active || curStatus == "cancelled" {
		writeError(w, 409, "assignment_inactive", "Assignment is inactive")
		return
	}
	if workerID == nil {
		if offeredTo != nil && *offeredTo == auth.UserID {
			writeError(w, 409, "assignment_not_ready", "Assignment must be accepted first")
			return
		}
		writeError(w, 403, "forbidden", "Forbidden")
		return
	}
	if *workerID != auth.UserID {
		writeError(w, 403, "forbidden", "Assignment belongs to another worker")
		return
	}

	var sealed bool
	var sStatus string
	var currentHolderID *uuid.UUID
	var deadline time.Time
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `
		SELECT sealed, status, current_holder_id, delivery_deadline, sealed_at
		FROM samples WHERE sample_id = $1
	`, sampleID).Scan(&sealed, &sStatus, &currentHolderID, &deadline, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	if lastProg != nil && occurredAt.Before(*lastProg) {
		writeError(w, 409, "invalid_progress_time", "Progress timestamp precedes prior progress")
		return
	}
	if sealedAt != nil && occurredAt.Before(*sealedAt) && kind != "collection" {
		writeError(w, 409, "invalid_progress_time", "Progress timestamp precedes sample sealing")
		return
	}
	if occurredAt.After(deadline) {
		writeError(w, 409, "delivery_deadline_exceeded", "OccurredAt exceeds sample delivery deadline")
		return
	}

	if kind != "collection" {
		if !sealed {
			writeError(w, 409, "collection_required", "Sample must be collected and sealed before transport")
			return
		}
		// Check prior transport legs
		var incompletePrior int
		_ = s.db.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE journey_id = $1 AND kind = 'transport' AND sequence < $2 AND active = TRUE
			  AND status NOT IN ('completed', 'delivered')
		`, journeyID, seq).Scan(&incompletePrior)
		if incompletePrior > 0 {
			writeError(w, 409, "prior_leg_incomplete", "Prior transport leg is not yet completed")
			return
		}
		if newStatus != "at_pickup" {
			if currentHolderID == nil || *currentHolderID != auth.UserID {
				writeError(w, 409, "custody_required", "Confirmed custody handoff is required before continuing leg")
				return
			}
		}
	}

	// Validate state transition
	if !isValidAssignmentTransition(kind, curStatus, newStatus) {
		writeError(w, 409, "invalid_transition", "Invalid assignment status transition from "+curStatus+" to "+newStatus)
		return
	}

	var compAt *time.Time
	if newStatus == "delivered" || newStatus == "completed" {
		compAt = &occurredAt
	}

	_, err = s.db.Exec(ctx, `
		UPDATE assignments
		SET status = $1, last_progress_at = $2, completed_at = COALESCE(completed_at, $3), started_at = COALESCE(started_at, $2)
		WHERE assignment_id = $4
	`, newStatus, occurredAt, compAt, assignID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update assignment progress")
		return
	}

	// Update sample status and location
	targetLoc := fromLocID
	if newStatus == "arrived" || newStatus == "delivered" || newStatus == "completed" {
		if toLocID != nil {
			targetLoc = toLocID
		}
	}
	if targetLoc != nil {
		var lat, lng float64
		if err := s.db.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE location_id = $1`, *targetLoc).Scan(&lat, &lng); err == nil {
			sampleStatus := sStatus
			if newStatus == "picked_up" || newStatus == "in_transit" {
				sampleStatus = "in_transit"
			}
			_, _ = s.db.Exec(ctx, `
				UPDATE samples SET status = $1, latest_lat = $2, latest_lng = $3, location_recorded_at = $4
				WHERE sample_id = $5
			`, sampleStatus, lat, lng, occurredAt, sampleID)
		}
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "update_assignment_progress", "assignment", assignID.String(), true, occurredAt, map[string]any{
		"assignmentId": assignID.String(),
		"sampleId":     sampleID.String(),
		"status":       newStatus,
	})
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "update_assignment_progress", "sample", sampleID.String(), true, occurredAt, map[string]any{
		"assignmentId": assignID.String(),
		"status":       newStatus,
	})
	s.publishEvent(ctx, s.db, "assignment_progress", "assignment", assignID.String(), map[string]any{
		"assignmentId": assignID.String(),
		"sampleId":     sampleID.String(),
		"status":       newStatus,
	})

	resp := map[string]any{
		"assignmentId": assignID.String(),
		"sampleId":     sampleID.String(),
		"status":       newStatus,
	}
	s.saveIdempotency(ctx, "update_assignment_progress", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func isValidAssignmentTransition(kind, cur, next string) bool {
	if cur == "completed" || cur == "delivered" || cur == "cancelled" {
		return false
	}
	if kind == "transport" {
		order := map[string]int{
			"accepted":    1,
			"at_pickup":   2,
			"picked_up":   3,
			"in_progress": 3,
			"in_transit":  4,
			"arrived":     5,
			"delivered":   6,
			"completed":   6,
		}
		cOrd, ok1 := order[cur]
		nOrd, ok2 := order[next]
		if !ok1 || !ok2 {
			return false
		}
		if nOrd < cOrd {
			return false
		}
		// Must go through picked_up or in_progress before in_transit / arrived / delivered / completed
		if cOrd < 3 && nOrd > 3 {
			return false
		}
		return true
	}
	return true
}

func (s *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "initiate_handoff", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		SampleID         *string `json:"sampleId"`
		FromAssignmentID *string `json:"fromAssignmentId"`
		ToAssignmentID   *string `json:"toAssignmentId"`
		ReceiverID       *string `json:"receiverId"`
		InitiatedAt      *string `json:"initiatedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.SampleID == nil || req.FromAssignmentID == nil || req.ToAssignmentID == nil || req.ReceiverID == nil || req.InitiatedAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "initiate_handoff", idemKey, rawBody); done {
		return
	}

	sampleID, err1 := uuid.Parse(*req.SampleID)
	fromAssignID, err2 := uuid.Parse(*req.FromAssignmentID)
	toAssignID, err3 := uuid.Parse(*req.ToAssignmentID)
	receiverID, err4 := uuid.Parse(*req.ReceiverID)
	if err1 != nil || err2 != nil || err3 != nil || err4 != nil {
		writeError(w, 400, "invalid_json", "Invalid UUID")
		return
	}
	initiatedAt, err := parseTimeISO(*req.InitiatedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid initiatedAt")
		return
	}

	var sealed bool
	var currentHolderID *uuid.UUID
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `SELECT sealed, current_holder_id, sealed_at FROM samples WHERE sample_id = $1`, sampleID).Scan(&sealed, &currentHolderID, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	type aInfo struct {
		sampleID  uuid.UUID
		journeyID uuid.UUID
		kind      string
		seq       int
		status    string
		workerID  *uuid.UUID
		offeredTo *uuid.UUID
		fromLoc   *uuid.UUID
		toLoc     *uuid.UUID
		nodeID    *uuid.UUID
		labID     *uuid.UUID
		lastProg  *time.Time
		compAt    *time.Time
		active    bool
	}
	var fromA, toA aInfo
	err = s.db.QueryRow(ctx, `
		SELECT sample_id, journey_id, kind, sequence, status, worker_id, offered_to_worker_id,
		       from_location_id, to_location_id, node_id, laboratory_id, last_progress_at, completed_at, active
		FROM assignments WHERE assignment_id = $1
	`, fromAssignID).Scan(&fromA.sampleID, &fromA.journeyID, &fromA.kind, &fromA.seq, &fromA.status, &fromA.workerID, &fromA.offeredTo, &fromA.fromLoc, &fromA.toLoc, &fromA.nodeID, &fromA.labID, &fromA.lastProg, &fromA.compAt, &fromA.active)
	if err != nil {
		writeError(w, 404, "not_found", "fromAssignment not found")
		return
	}
	err = s.db.QueryRow(ctx, `
		SELECT sample_id, journey_id, kind, sequence, status, worker_id, offered_to_worker_id,
		       from_location_id, to_location_id, node_id, laboratory_id, last_progress_at, completed_at, active
		FROM assignments WHERE assignment_id = $1
	`, toAssignID).Scan(&toA.sampleID, &toA.journeyID, &toA.kind, &toA.seq, &toA.status, &toA.workerID, &toA.offeredTo, &toA.fromLoc, &toA.toLoc, &toA.nodeID, &toA.labID, &toA.lastProg, &toA.compAt, &toA.active)
	if err != nil {
		writeError(w, 404, "not_found", "toAssignment not found")
		return
	}

	// Check receiver user
	var recActive, recAvail bool
	var recLocID *uuid.UUID
	err = s.db.QueryRow(ctx, `SELECT active, available, assigned_location_id FROM users WHERE user_id = $1`, receiverID).Scan(&recActive, &recAvail, &recLocID)
	if err != nil {
		writeError(w, 400, "invalid_receiver", "Receiver user not found")
		return
	}

	if fromA.sampleID != sampleID || toA.sampleID != sampleID {
		writeError(w, 400, "invalid_handoff_route", "Assignments do not belong to sample")
		return
	}
	if fromA.workerID == nil || *fromA.workerID != auth.UserID {
		writeError(w, 403, "sender_assignment_mismatch", "Sender does not own fromAssignment")
		return
	}
	if !sealed || currentHolderID == nil || *currentHolderID != auth.UserID {
		writeError(w, 409, "not_current_holder", "Sender is not the current custodian of the sample")
		return
	}

	var pendCount int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM handoffs WHERE sample_id = $1 AND status = 'pending' AND active = TRUE`, sampleID).Scan(&pendCount)
	if pendCount > 0 {
		writeError(w, 409, "pending_handoff_exists", "Sample already has an active pending handoff")
		return
	}

	if !fromA.active || !toA.active {
		writeError(w, 409, "invalid_assignment_state", "Assignment is inactive")
		return
	}
	if !recActive || !recAvail {
		writeError(w, 409, "receiver_unavailable", "Receiver is unavailable")
		return
	}
	if toA.kind == "node" && toA.nodeID != nil {
		if recLocID == nil || *recLocID != *toA.nodeID {
			writeError(w, 409, "node_assignment_mismatch", "Receiver is not assigned to the node")
			return
		}
	}
	if toA.kind == "laboratory" && toA.labID != nil {
		if recLocID == nil || *recLocID != *toA.labID {
			writeError(w, 409, "node_assignment_mismatch", "Receiver is not assigned to the laboratory")
			return
		}
	}
	if toA.workerID == nil {
		if toA.offeredTo != nil && *toA.offeredTo != receiverID {
			writeError(w, 409, "receiver_assignment_mismatch", "toAssignment is offered to a different worker")
			return
		}
		writeError(w, 409, "offer_not_available", "toAssignment has not been accepted by receiver yet")
		return
	}
	if *toA.workerID != receiverID {
		writeError(w, 409, "receiver_assignment_mismatch", "Receiver does not match worker assigned to toAssignment")
		return
	}

	// Check adjacency
	if fromAssignID == toAssignID || fromA.seq >= toA.seq {
		writeError(w, 409, "nonadjacent_handoff", "Assignments are not in valid adjacent order")
		return
	}
	if fromA.toLoc != nil && toA.fromLoc != nil && *fromA.toLoc != *toA.fromLoc {
		writeError(w, 409, "nonadjacent_handoff", "Handoff locations are not adjacent")
		return
	}
	// Also ensure no intermediate transport leg was skipped
	var skippedTransport int
	_ = s.db.QueryRow(ctx, `
		SELECT COUNT(*) FROM assignments
		WHERE journey_id = $1 AND kind = 'transport' AND sequence > $2 AND sequence < $3 AND active = TRUE
	`, fromA.journeyID, fromA.seq, toA.seq).Scan(&skippedTransport)
	if skippedTransport > 0 {
		writeError(w, 409, "nonadjacent_handoff", "Cannot skip intermediate transport leg")
		return
	}

	// Check fromAssignment completion/progress state
	if fromA.kind == "transport" {
		if fromA.status == "accepted" || fromA.status == "at_pickup" || fromA.status == "pending" {
			writeError(w, 409, "transport_leg_incomplete", "Transport leg has not been picked up/transported")
			return
		}
	}
	if sealedAt != nil && initiatedAt.Before(*sealedAt) {
		writeError(w, 409, "invalid_handoff_time", "Handoff time precedes sample sealing")
		return
	}
	if fromA.lastProg != nil && initiatedAt.Before(*fromA.lastProg) {
		writeError(w, 409, "invalid_handoff_time", "Handoff time precedes leg progress")
		return
	}

	handoffID := uuid.New()
	_, err = s.db.Exec(ctx, `
		INSERT INTO handoffs (
			handoff_id, sample_id, journey_id, from_assignment_id, to_assignment_id,
			sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, initiated_at, active
		) VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', FALSE, FALSE, $8, TRUE)
	`, handoffID, sampleID, toA.journeyID, fromAssignID, toAssignID, auth.UserID, receiverID, initiatedAt)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to create handoff")
		return
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "initiate_handoff", "handoff", handoffID.String(), true, initiatedAt, map[string]any{
		"sampleId":         sampleID.String(),
		"fromAssignmentId": fromAssignID.String(),
		"toAssignmentId":   toAssignID.String(),
		"senderId":         auth.UserID.String(),
		"receiverId":       receiverID.String(),
	})
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "initiate_handoff", "sample", sampleID.String(), true, initiatedAt, map[string]any{
		"handoffId":  handoffID.String(),
		"senderId":   auth.UserID.String(),
		"receiverId": receiverID.String(),
	})
	s.publishEvent(ctx, s.db, "handoff_initiated", "handoff", handoffID.String(), map[string]any{
		"handoffId":  handoffID.String(),
		"sampleId":   sampleID.String(),
		"senderId":   auth.UserID.String(),
		"receiverId": receiverID.String(),
		"status":     "pending",
	})

	resp := map[string]any{
		"handoffId":       handoffID.String(),
		"senderId":        auth.UserID.String(),
		"receiverId":      receiverID.String(),
		"currentHolderId": currentHolderID.String(),
		"status":          "pending",
	}
	s.saveIdempotency(ctx, "initiate_handoff", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "confirm_handoff", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		HandoffID        *string `json:"handoffId"`
		ConfirmationSide *string `json:"confirmationSide"`
		ConfirmedAt      *string `json:"confirmedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.HandoffID == nil || req.ConfirmationSide == nil || req.ConfirmedAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "confirm_handoff", idemKey, rawBody); done {
		return
	}

	side := *req.ConfirmationSide
	if side != "sender" && side != "receiver" {
		writeError(w, 400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		return
	}
	handoffID, err := uuid.Parse(*req.HandoffID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid handoffId")
		return
	}
	confirmedAt, err := parseTimeISO(*req.ConfirmedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid confirmedAt")
		return
	}

	var sampleID, journeyID, fromAssignID, toAssignID, senderID, receiverID uuid.UUID
	var hStatus string
	var sConf, rConf, active bool
	var initAt time.Time

	err = s.db.QueryRow(ctx, `
		SELECT sample_id, journey_id, from_assignment_id, to_assignment_id,
		       sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, initiated_at, active
		FROM handoffs WHERE handoff_id = $1
	`, handoffID).Scan(&sampleID, &journeyID, &fromAssignID, &toAssignID, &senderID, &receiverID, &hStatus, &sConf, &rConf, &initAt, &active)
	if err != nil {
		writeError(w, 404, "not_found", "Handoff not found")
		return
	}
	if !active || hStatus == "cancelled" {
		writeError(w, 409, "handoff_inactive", "Handoff is inactive")
		return
	}
	if confirmedAt.Before(initAt) {
		writeError(w, 409, "invalid_confirmation_time", "Confirmation time precedes handoff initiation")
		return
	}

	if side == "sender" && auth.UserID != senderID {
		writeError(w, 403, "forbidden", "Actor is not the handoff sender")
		return
	}
	if side == "receiver" && auth.UserID != receiverID {
		writeError(w, 403, "forbidden", "Actor is not the handoff receiver")
		return
	}

	var currentHolderID *uuid.UUID
	_ = s.db.QueryRow(ctx, `SELECT current_holder_id FROM samples WHERE sample_id = $1`, sampleID).Scan(&currentHolderID)

	// If already confirmed, return idempotent confirmed state without duplicate custody transfer
	if hStatus == "confirmed" {
		holderStr := receiverID.String()
		if currentHolderID != nil {
			holderStr = currentHolderID.String()
		}
		resp := map[string]any{
			"handoffId":         handoffID.String(),
			"status":            "confirmed",
			"senderConfirmed":   true,
			"receiverConfirmed": true,
			"currentHolderId":   holderStr,
		}
		s.saveIdempotency(ctx, "confirm_handoff", idemKey, rawBody, 201, resp)
		writeData(w, 201, resp)
		return
	}

	if currentHolderID == nil || *currentHolderID != senderID {
		writeError(w, 409, "custody_conflict", "Sender no longer holds custody of the sample")
		return
	}

	if side == "sender" {
		sConf = true
		_, _ = s.db.Exec(ctx, `UPDATE handoffs SET sender_confirmed = TRUE, sender_confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)
	} else {
		rConf = true
		_, _ = s.db.Exec(ctx, `UPDATE handoffs SET receiver_confirmed = TRUE, receiver_confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)
	}

	newHolder := senderID
	if sConf && rConf {
		hStatus = "confirmed"
		newHolder = receiverID
		_, _ = s.db.Exec(ctx, `UPDATE handoffs SET status = 'confirmed', confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, handoffID)

		// Transfer custody on sample
		var fromToLoc *uuid.UUID
		var fromSeq, toSeq int
		_ = s.db.QueryRow(ctx, `SELECT to_location_id, sequence FROM assignments WHERE assignment_id = $1`, fromAssignID).Scan(&fromToLoc, &fromSeq)
		_ = s.db.QueryRow(ctx, `SELECT sequence FROM assignments WHERE assignment_id = $1`, toAssignID).Scan(&toSeq)

		if fromToLoc != nil {
			var lat, lng float64
			if err := s.db.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE location_id = $1`, *fromToLoc).Scan(&lat, &lng); err == nil {
				_, _ = s.db.Exec(ctx, `
					UPDATE samples SET current_holder_id = $1, latest_lat = $2, latest_lng = $3, location_recorded_at = $4
					WHERE sample_id = $5
				`, receiverID, lat, lng, confirmedAt, sampleID)
			} else {
				_, _ = s.db.Exec(ctx, `UPDATE samples SET current_holder_id = $1, location_recorded_at = $2 WHERE sample_id = $3`, receiverID, confirmedAt, sampleID)
			}
			// Mark stop at fromToLoc completed
			_, _ = s.db.Exec(ctx, `
				UPDATE journey_stops SET completed_at = COALESCE(completed_at, $1)
				WHERE journey_id = $2 AND location_id = $3 AND stop_type IN ('pickup', 'handoff')
			`, confirmedAt, journeyID, *fromToLoc)
		} else {
			_, _ = s.db.Exec(ctx, `UPDATE samples SET current_holder_id = $1, location_recorded_at = $2 WHERE sample_id = $3`, receiverID, confirmedAt, sampleID)
		}

		// Mark fromAssignment completed
		_, _ = s.db.Exec(ctx, `
			UPDATE assignments SET status = 'completed', completed_at = COALESCE(completed_at, $1)
			WHERE assignment_id = $2
		`, confirmedAt, fromAssignID)

		// If any intermediate node assignment between fromSeq and toSeq was bypassed, mark it completed/inactive
		if toSeq > fromSeq+1 {
			_, _ = s.db.Exec(ctx, `
				UPDATE assignments SET status = 'completed', completed_at = $1, active = FALSE
				WHERE journey_id = $2 AND sequence > $3 AND sequence < $4 AND kind = 'node'
			`, confirmedAt, journeyID, fromSeq, toSeq)
		}

		s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "custody_transferred", "sample", sampleID.String(), true, confirmedAt, map[string]any{
			"handoffId":       handoffID.String(),
			"fromHolderId":    senderID.String(),
			"currentHolderId": receiverID.String(),
		})
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "confirm_handoff", "handoff", handoffID.String(), true, confirmedAt, map[string]any{
		"handoffId":         handoffID.String(),
		"sampleId":          sampleID.String(),
		"confirmationSide":  side,
		"senderConfirmed":   sConf,
		"receiverConfirmed": rConf,
		"status":            hStatus,
		"currentHolderId":   newHolder.String(),
	})
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "confirm_handoff", "sample", sampleID.String(), true, confirmedAt, map[string]any{
		"handoffId":         handoffID.String(),
		"confirmationSide":  side,
		"status":            hStatus,
		"currentHolderId":   newHolder.String(),
	})
	s.publishEvent(ctx, s.db, "handoff_confirmed", "handoff", handoffID.String(), map[string]any{
		"handoffId":         handoffID.String(),
		"sampleId":          sampleID.String(),
		"status":            hStatus,
		"senderConfirmed":   sConf,
		"receiverConfirmed": rConf,
		"currentHolderId":   newHolder.String(),
	})

	resp := map[string]any{
		"handoffId":         handoffID.String(),
		"status":            hStatus,
		"senderConfirmed":   sConf,
		"receiverConfirmed": rConf,
		"currentHolderId":   newHolder.String(),
	}
	s.saveIdempotency(ctx, "confirm_handoff", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "record_handling_checkpoint", "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		LocationID           *string  `json:"locationId"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           *string  `json:"recordedAt"`
		IdempotencyKey       *string  `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.SampleID == nil || req.AssignmentID == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil || req.RecordedAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "record_handling_checkpoint", idemKey, rawBody); done {
		return
	}

	sampleID, err1 := uuid.Parse(*req.SampleID)
	assignID, err2 := uuid.Parse(*req.AssignmentID)
	if err1 != nil || err2 != nil {
		writeError(w, 400, "invalid_json", "Invalid UUID")
		return
	}
	var locID *uuid.UUID
	if req.LocationID != nil && *req.LocationID != "" {
		parsed, err := uuid.Parse(*req.LocationID)
		if err != nil {
			writeError(w, 400, "invalid_json", "Invalid locationId")
			return
		}
		locID = &parsed
	}
	recordedAt, err := parseTimeISO(*req.RecordedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid recordedAt")
		return
	}

	var sCont, sStatus string
	var tMin, tMax float64
	var currentHolderID *uuid.UUID
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `
		SELECT container_type, temperature_min_c, temperature_max_c, status, current_holder_id, sealed_at
		FROM samples WHERE sample_id = $1
	`, sampleID).Scan(&sCont, &tMin, &tMax, &sStatus, &currentHolderID, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	var aSampleID uuid.UUID
	var aWorkerID *uuid.UUID
	var aActive bool
	err = s.db.QueryRow(ctx, `
		SELECT sample_id, worker_id, active FROM assignments WHERE assignment_id = $1
	`, assignID).Scan(&aSampleID, &aWorkerID, &aActive)
	if err != nil {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}
	if sStatus == "received" || sStatus == "cancelled" || sStatus == "expired" {
		writeError(w, 409, "terminal_sample", "Sample is in a terminal state")
		return
	}
	if !aActive {
		writeError(w, 409, "assignment_inactive", "Assignment is inactive")
		return
	}
	if aSampleID != sampleID || aWorkerID == nil || *aWorkerID != auth.UserID || currentHolderID == nil || *currentHolderID != auth.UserID {
		writeError(w, 403, "forbidden", "Worker must hold custody of the sample to record a handling checkpoint")
		return
	}
	if sealedAt != nil && recordedAt.Before(*sealedAt) {
		writeError(w, 409, "invalid_checkpoint_time", "Checkpoint time precedes sample sealing")
		return
	}

	compliant := (*req.ContainerType == sCont && *req.ObservedTemperatureC >= tMin && *req.ObservedTemperatureC <= tMax)
	cpID := uuid.New()
	_, err = s.db.Exec(ctx, `
		INSERT INTO checkpoints (
			checkpoint_id, sample_id, assignment_id, location_id,
			container_type, observed_temperature_c, compliant, recorded_at, actor_id
		) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
	`, cpID, sampleID, assignID, locID, *req.ContainerType, *req.ObservedTemperatureC, compliant, recordedAt, auth.UserID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to save checkpoint")
		return
	}

	if !compliant {
		sStatus = "exception"
		excID := uuid.New()
		excMap := map[string]any{
			"exceptionId":          excID.String(),
			"sampleId":             sampleID.String(),
			"reason":               "handling_checkpoint_noncompliant",
			"containerType":        *req.ContainerType,
			"observedTemperatureC": *req.ObservedTemperatureC,
			"observedAt":           formatTimeISO(recordedAt),
		}
		excB, _ := json.Marshal(excMap)
		_, _ = s.db.Exec(ctx, `UPDATE samples SET status = 'exception', exception_data = $1 WHERE sample_id = $2`, excB, sampleID)
		_, _ = s.db.Exec(ctx, `
			INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, observed_at, actor_id)
			VALUES ($1, $2, $3, 'handling_checkpoint_noncompliant', $4, $5)
		`, excID, sampleID, locID, recordedAt, auth.UserID)
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_handling_checkpoint", "sample", sampleID.String(), true, recordedAt, map[string]any{
		"checkpointId":         cpID.String(),
		"containerType":        *req.ContainerType,
		"observedTemperatureC": *req.ObservedTemperatureC,
		"compliant":            compliant,
		"sampleStatus":         sStatus,
	})
	s.publishEvent(ctx, s.db, "checkpoint_recorded", "sample", sampleID.String(), map[string]any{
		"checkpointId": cpID.String(),
		"sampleId":     sampleID.String(),
		"compliant":    compliant,
		"sampleStatus": sStatus,
	})

	resp := map[string]any{
		"checkpointId": cpID.String(),
		"sampleId":     sampleID.String(),
		"compliant":    compliant,
		"sampleStatus": sStatus,
	}
	s.saveIdempotency(ctx, "record_handling_checkpoint", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "confirm_laboratory_receipt", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		SampleID       *string `json:"sampleId"`
		LaboratoryID   *string `json:"laboratoryId"`
		ReceivedAt     *string `json:"receivedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.SampleID == nil || req.LaboratoryID == nil || req.ReceivedAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "confirm_laboratory_receipt", idemKey, rawBody); done {
		return
	}

	sampleID, err1 := uuid.Parse(*req.SampleID)
	labID, err2 := uuid.Parse(*req.LaboratoryID)
	if err1 != nil || err2 != nil {
		writeError(w, 400, "invalid_json", "Invalid UUID")
		return
	}
	receivedAt, err := parseTimeISO(*req.ReceivedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid receivedAt")
		return
	}

	if auth.AssignedLocationID == nil || *auth.AssignedLocationID != labID {
		s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "confirm_laboratory_receipt", "sample", sampleID.String(), false, receivedAt, map[string]any{"reason": "wrong_laboratory_operator"})
		writeError(w, 403, "wrong_laboratory_operator", "Operator is not assigned to this laboratory")
		return
	}

	var labActive, fnLab bool
	var labLat, labLng float64
	err = s.db.QueryRow(ctx, `SELECT active, fn_laboratory, latitude, longitude FROM locations WHERE location_id = $1`, labID).Scan(&labActive, &fnLab, &labLat, &labLng)
	if err != nil {
		writeError(w, 404, "not_found", "Laboratory not found")
		return
	}

	var stID uuid.UUID
	var sealed bool
	var sStatus string
	var activeJourneyID, currentHolderID *uuid.UUID
	var deadline time.Time
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `
		SELECT sample_type_id, sealed, status, active_journey_id, current_holder_id, delivery_deadline, sealed_at
		FROM samples WHERE sample_id = $1
	`, sampleID).Scan(&stID, &sealed, &sStatus, &activeJourneyID, &currentHolderID, &deadline, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	if !labActive || !fnLab {
		writeError(w, 409, "laboratory_unavailable", "Laboratory is inactive")
		return
	}
	var accepts bool
	_ = s.db.QueryRow(ctx, `SELECT accepts FROM lab_acceptances WHERE laboratory_id = $1 AND sample_type_id = $2`, labID, stID).Scan(&accepts)
	if !accepts {
		writeError(w, 409, "laboratory_unavailable", "Laboratory does not accept this sample type")
		return
	}

	var pendHandoffs int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM handoffs WHERE sample_id = $1 AND status = 'pending' AND active = TRUE`, sampleID).Scan(&pendHandoffs)
	if pendHandoffs > 0 {
		writeError(w, 409, "pending_handoff_exists", "Sample has an unconfirmed pending handoff")
		return
	}

	if !sealed {
		writeError(w, 409, "receipt_not_ready", "Sample is not sealed")
		return
	}

	// Check transport legs are completed/delivered
	if activeJourneyID != nil {
		var unfinishedTransport int
		_ = s.db.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE journey_id = $1 AND kind = 'transport' AND active = TRUE AND status NOT IN ('completed', 'delivered', 'arrived')
		`, *activeJourneyID).Scan(&unfinishedTransport)
		if unfinishedTransport > 0 {
			writeError(w, 409, "receipt_not_ready", "Transport legs are not yet complete")
			return
		}
	}

	if currentHolderID == nil || *currentHolderID != auth.UserID {
		writeError(w, 409, "custody_conflict", "Laboratory operator does not hold custody of the sample")
		return
	}

	if sealedAt != nil && receivedAt.Before(*sealedAt) {
		writeError(w, 409, "invalid_receipt_time", "Receipt time precedes sample sealing")
		return
	}
	var lastConfAt *time.Time
	_ = s.db.QueryRow(ctx, `SELECT MAX(confirmed_at) FROM handoffs WHERE sample_id = $1 AND status = 'confirmed'`, sampleID).Scan(&lastConfAt)
	if lastConfAt != nil && receivedAt.Before(*lastConfAt) {
		writeError(w, 409, "invalid_receipt_time", "Receipt time precedes handoff confirmation")
		return
	}
	if receivedAt.After(deadline) {
		writeError(w, 409, "delivery_deadline_exceeded", "Receipt time exceeds sample delivery deadline")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE samples
		SET status = 'received', received_laboratory_id = $1, received_at = $2,
		    latest_lat = $3, latest_lng = $4, location_recorded_at = $2
		WHERE sample_id = $5
	`, labID, receivedAt, labLat, labLng, sampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to confirm receipt")
		return
	}

	if activeJourneyID != nil {
		_, _ = s.db.Exec(ctx, `
			UPDATE assignments SET status = 'completed', completed_at = COALESCE(completed_at, $1)
			WHERE journey_id = $2 AND sample_id = $3 AND active = TRUE
		`, receivedAt, *activeJourneyID, sampleID)
		_, _ = s.db.Exec(ctx, `
			UPDATE journey_stops SET completed_at = COALESCE(completed_at, $1)
			WHERE journey_id = $2 AND stop_type = 'delivery'
		`, receivedAt, *activeJourneyID)
		_ = s.releaseJourneyCapacity(ctx, s.db, *activeJourneyID, &sampleID)

		// If all samples in journey are received/completed, mark journey completed
		var rem int
		_ = s.db.QueryRow(ctx, `
			SELECT COUNT(*) FROM samples WHERE active_journey_id = $1 AND status NOT IN ('received', 'cancelled', 'expired', 'exception')
		`, *activeJourneyID).Scan(&rem)
		if rem == 0 {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET status = 'completed' WHERE journey_id = $1`, *activeJourneyID)
		}
		_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "confirm_laboratory_receipt", "sample", sampleID.String(), true, receivedAt, map[string]any{
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"receivedAt":   formatTimeISO(receivedAt),
	})
	s.publishEvent(ctx, s.db, "sample_received", "sample", sampleID.String(), map[string]any{
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"status":       "received",
	})

	resp := map[string]any{
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"status":       "received",
		"receivedAt":   formatTimeISO(receivedAt),
	}
	s.saveIdempotency(ctx, "confirm_laboratory_receipt", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "record_laboratory_exception", "laboratory_team")
	if !ok {
		return
	}

	var req struct {
		SampleID       *string `json:"sampleId"`
		LaboratoryID   *string `json:"laboratoryId"`
		Reason         *string `json:"reason"`
		ObservedAt     *string `json:"observedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	rawBody, err := decodeStrictJSON(r, &req, false)
	if err != nil || req.SampleID == nil || req.LaboratoryID == nil || req.Reason == nil || req.ObservedAt == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	if req.IdempotencyKey == nil || strings.TrimSpace(*req.IdempotencyKey) == "" {
		writeError(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	idemKey := strings.TrimSpace(*req.IdempotencyKey)
	if done := s.checkIdempotency(ctx, w, "record_laboratory_exception", idemKey, rawBody); done {
		return
	}

	sampleID, err1 := uuid.Parse(*req.SampleID)
	labID, err2 := uuid.Parse(*req.LaboratoryID)
	if err1 != nil || err2 != nil || strings.TrimSpace(*req.Reason) == "" {
		writeError(w, 400, "invalid_json", "Invalid parameters")
		return
	}
	observedAt, err := parseTimeISO(*req.ObservedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid observedAt")
		return
	}

	if auth.AssignedLocationID == nil || *auth.AssignedLocationID != labID {
		s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_laboratory_exception", "sample", sampleID.String(), false, observedAt, map[string]any{"reason": "wrong_laboratory_operator"})
		writeError(w, 403, "wrong_laboratory_operator", "Operator is not assigned to this laboratory")
		return
	}

	var labExists int
	_ = s.db.QueryRow(ctx, `SELECT COUNT(*) FROM locations WHERE location_id = $1`, labID).Scan(&labExists)
	if labExists == 0 {
		writeError(w, 404, "not_found", "Laboratory not found")
		return
	}

	var activeJourneyID, targetLabID *uuid.UUID
	var sealedAt *time.Time
	err = s.db.QueryRow(ctx, `SELECT active_journey_id, target_laboratory_id, sealed_at FROM samples WHERE sample_id = $1`, sampleID).Scan(&activeJourneyID, &targetLabID, &sealedAt)
	if err != nil {
		writeError(w, 404, "not_found", "Sample not found")
		return
	}

	if targetLabID != nil && *targetLabID != labID {
		writeError(w, 409, "wrong_laboratory", "Sample is not targeted to this laboratory")
		return
	}
	if sealedAt != nil && observedAt.Before(*sealedAt) {
		writeError(w, 409, "invalid_exception_time", "Exception time precedes sample sealing")
		return
	}

	excID := uuid.New()
	excMap := map[string]any{
		"exceptionId":  excID.String(),
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"reason":       *req.Reason,
		"observedAt":   formatTimeISO(observedAt),
	}
	excB, _ := json.Marshal(excMap)

	_, err = s.db.Exec(ctx, `UPDATE samples SET status = 'exception', exception_data = $1 WHERE sample_id = $2`, excB, sampleID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to record laboratory exception")
		return
	}
	_, _ = s.db.Exec(ctx, `
		INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, observed_at, actor_id)
		VALUES ($1, $2, $3, $4, $5, $6)
	`, excID, sampleID, labID, *req.Reason, observedAt, auth.UserID)

	if activeJourneyID != nil {
		_ = s.releaseJourneyCapacity(ctx, s.db, *activeJourneyID, &sampleID)
		_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	}

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_laboratory_exception", "sample", sampleID.String(), true, observedAt, excMap)
	s.publishEvent(ctx, s.db, "laboratory_exception_recorded", "sample", sampleID.String(), excMap)

	resp := map[string]any{
		"exceptionId": excID.String(),
		"sampleId":    sampleID.String(),
		"status":      "exception",
		"reason":      *req.Reason,
	}
	s.saveIdempotency(ctx, "record_laboratory_exception", idemKey, rawBody, 201, resp)
	writeData(w, 201, resp)
}

func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "record_worker_location", "collection_professional", "delivery_partner")
	if !ok {
		return
	}

	var req struct {
		WorkerID   *string     `json:"workerId"`
		Coordinate *Coordinate `json:"coordinate"`
		RecordedAt *string     `json:"recordedAt"`
		Sequence   *int        `json:"sequence"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.WorkerID == nil || req.Coordinate == nil || req.RecordedAt == nil || req.Sequence == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	workerID, err := uuid.Parse(*req.WorkerID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid workerId")
		return
	}
	if !validateCoordinate(*req.Coordinate) {
		writeError(w, 400, "invalid_coordinate", "Invalid coordinate")
		return
	}
	if *req.Sequence < 1 {
		writeError(w, 400, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recordedAt, err := parseTimeISO(*req.RecordedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid recordedAt")
		return
	}

	if workerID != auth.UserID {
		writeError(w, 403, "forbidden", "Cannot record location for another worker")
		return
	}

	var prevSeq int
	var prevRec *time.Time
	err = s.db.QueryRow(ctx, `SELECT location_sequence, location_recorded_at FROM users WHERE user_id = $1`, workerID).Scan(&prevSeq, &prevRec)
	if err != nil {
		writeError(w, 404, "not_found", "Worker not found")
		return
	}

	if *req.Sequence <= prevSeq || (prevRec != nil && recordedAt.Before(*prevRec)) {
		writeError(w, 409, "stale_location", "Location update is older than or equal to current sequence/timestamp")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE users
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
		WHERE user_id = $5
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, *req.Sequence, workerID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update worker location")
		return
	}

	// Also update samples currently held by this worker
	_, _ = s.db.Exec(ctx, `
		UPDATE samples
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
		WHERE current_holder_id = $4 AND status NOT IN ('received', 'cancelled', 'expired')
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, workerID)

	stale := isLocationStale(&recordedAt, time.Now().UTC())

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_worker_location", "user", workerID.String(), true, recordedAt, map[string]any{
		"coordinate": *req.Coordinate,
		"sequence":   *req.Sequence,
		"stale":      stale,
	})
	s.publishEvent(ctx, s.db, "worker_location_updated", "user", workerID.String(), map[string]any{
		"workerId":   workerID.String(),
		"coordinate": *req.Coordinate,
		"recordedAt": formatTimeISO(recordedAt),
		"sequence":   *req.Sequence,
		"stale":      stale,
	})

	writeData(w, 200, map[string]any{
		"workerId":   workerID.String(),
		"coordinate": *req.Coordinate,
		"recordedAt": formatTimeISO(recordedAt),
		"sequence":   *req.Sequence,
		"stale":      stale,
	})
}

