package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func main() {
	ctx := context.Background()

	if len(os.Args) > 1 && os.Args[1] == "reset" {
		pool, err := connectDB(ctx)
		if err != nil {
			log.Fatalf("connect db for reset: %v", err)
		}
		defer pool.Close()
		if err := resetDatabase(ctx, pool); err != nil {
			log.Fatalf("reset db: %v", err)
		}
		fmt.Println("Database reset complete")
		return
	}

	pool, err := connectDB(ctx)
	if err != nil {
		log.Fatalf("connect db: %v", err)
	}
	defer pool.Close()

	if err := initDatabase(ctx, pool); err != nil {
		log.Fatalf("init db: %v", err)
	}

	srv := NewServer(pool)
	mux := http.NewServeMux()

	readyHandler := func(w http.ResponseWriter, r *http.Request) {
		pingCtx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
		defer cancel()
		if err := srv.db.Ping(pingCtx); err != nil {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unhealthy"})
			return
		}
		writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
	}
	mux.HandleFunc("/ready", readyHandler)
	mux.HandleFunc("/api/ready", readyHandler)

	// Auth & Users
	mux.HandleFunc("/api/login", srv.handleLogin)
	mux.HandleFunc("/api/logout", srv.handleLogout)
	mux.HandleFunc("/api/select-active-role", srv.handleSelectActiveRole)
	mux.HandleFunc("/api/create-user-account", srv.handleCreateUserAccount)
	mux.HandleFunc("/api/update-user-roles-and-certifications", srv.handleUpdateUserRolesAndCertifications)

	// Network & Admin
	mux.HandleFunc("/api/create-network-location", srv.handleCreateNetworkLocation)
	mux.HandleFunc("/api/update-network-location", srv.handleUpdateNetworkLocation)
	mux.HandleFunc("/api/set-location-status", srv.handleSetLocationStatus)
	mux.HandleFunc("/api/set-location-function-status", srv.handleSetLocationFunctionStatus)
	mux.HandleFunc("/api/create-transport-connection", srv.handleCreateTransportConnection)
	mux.HandleFunc("/api/set-connection-status", srv.handleSetConnectionStatus)
	mux.HandleFunc("/api/upsert-sample-type", srv.handleUpsertSampleType)
	mux.HandleFunc("/api/set-laboratory-sample-acceptance", srv.handleSetLaboratorySampleAcceptance)
	mux.HandleFunc("/api/configure-capacity", srv.handleConfigureCapacity)
	mux.HandleFunc("/api/set-worker-availability", srv.handleSetWorkerAvailability)
	mux.HandleFunc("/api/read-serviceability-status", srv.handleReadServiceabilityStatus)

	// Requests, Samples, Custody, Assignments
	mux.HandleFunc("/api/check-request-serviceability", srv.handleCheckRequestServiceability)
	mux.HandleFunc("/api/create-collection-request", srv.handleCreateCollectionRequest)
	mux.HandleFunc("/api/ingest-presealed-sample", srv.handleIngestPresealedSample)
	mux.HandleFunc("/api/read-sample-state", srv.handleReadSampleState)
	mux.HandleFunc("/api/read-sample-lifecycle", srv.handleReadSampleLifecycle)
	mux.HandleFunc("/api/accept-assignment", srv.handleAcceptAssignment)
