func (s *Server) getLocationCapacity(ctx context.Context, q DBTx, locID uuid.UUID) (Capacity, error) {
        var capUnits, resUnits, cooledCap, cooledRes int
        err := q.QueryRow(ctx, `
                SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
                FROM locations WHERE location_id = $1
        `, locID).Scan(&capUnits, &resUnits, &cooledCap, &cooledRes)
        if err != nil {
                return Capacity{}, err
        }
        avail := capUnits - resUnits
        if avail < 0 {
                avail = 0
        }
        cooledAvail := cooledCap - cooledRes
        if cooledAvail < 0 {
                cooledAvail = 0
        }
        return Capacity{
                CapacityUnits:        capUnits,
                ReservedUnits:        resUnits,
                AvailableUnits:       avail,
                CooledCapacityUnits:  cooledCap,
                CooledReservedUnits:  cooledRes,
                CooledAvailableUnits: cooledAvail,
        }, nil
}

