func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, 405, "method_not_allowed", "Method not allowed")
		return
	}
	ctx := r.Context()
	auth, ok := s.requireRole(ctx, w, r, "record_worker_location", "collection_professional", "delivery_partner")
	if !ok {
		return
	}

	var req struct {
		AssignmentID *string     `json:"assignmentId"`
		Coordinate   *Coordinate `json:"coordinate"`
		RecordedAt   *string     `json:"recordedAt"`
		Sequence     *int        `json:"sequence"`
	}
	if _, err := decodeStrictJSON(r, &req, false); err != nil || req.AssignmentID == nil || req.Coordinate == nil || req.RecordedAt == nil || req.Sequence == nil {
		writeError(w, 400, "invalid_json", "Invalid request body")
		return
	}
	assignmentID, err := uuid.Parse(*req.AssignmentID)
	if err != nil {
		writeError(w, 400, "invalid_json", "Invalid assignmentId")
		return
	}
	if !validateCoordinate(*req.Coordinate) {
		writeError(w, 400, "invalid_coordinate", "Invalid coordinate")
		return
	}
	if *req.Sequence < 1 {
		writeError(w, 400, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recordedAt, err := parseTimeISO(*req.RecordedAt)
	if err != nil {
		writeError(w, 400, "invalid_time", "Invalid recordedAt")
		return
	}

	var sampleID uuid.UUID
	var workerID, offeredToID *uuid.UUID
	var prevSeq int
	var prevRec *time.Time
	err = s.db.QueryRow(ctx, `
		SELECT sample_id, worker_id, offered_to_worker_id, location_sequence, location_recorded_at
		FROM assignments WHERE assignment_id = $1
	`, assignmentID).Scan(&sampleID, &workerID, &offeredToID, &prevSeq, &prevRec)
	if err != nil {
		writeError(w, 404, "not_found", "Assignment not found")
		return
	}

	isOwner := (workerID != nil && *workerID == auth.UserID) || (offeredToID != nil && *offeredToID == auth.UserID)
	if !isOwner {
		writeError(w, 403, "forbidden", "Cannot record location for another worker's assignment")
		return
	}

	if *req.Sequence <= prevSeq || (prevRec != nil && recordedAt.Before(*prevRec)) {
		writeError(w, 409, "stale_location", "Location update is older than or equal to current sequence/timestamp")
		return
	}

	_, err = s.db.Exec(ctx, `
		UPDATE assignments
		SET location_sequence = $1, location_recorded_at = $2, last_progress_at = $2
		WHERE assignment_id = $3
	`, *req.Sequence, recordedAt, assignmentID)
	if err != nil {
		writeError(w, 500, "internal_error", "Failed to update assignment location")
		return
	}

	_, _ = s.db.Exec(ctx, `
		UPDATE users
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
		WHERE user_id = $5
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, *req.Sequence, auth.UserID)

	// Also update samples currently held by this worker or linked to this assignment
	_, _ = s.db.Exec(ctx, `
		UPDATE samples
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
		WHERE (sample_id = $4 OR current_holder_id = $5) AND status NOT IN ('received_at_lab', 'cancelled', 'expired')
	`, req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, sampleID, auth.UserID)

	stale := isLocationStale(&recordedAt, time.Now().UTC())

	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "record_worker_location", "assignment", assignmentID.String(), true, recordedAt, map[string]any{
		"assignmentId": assignmentID.String(),
		"coordinate":   *req.Coordinate,
		"sequence":     *req.Sequence,
		"stale":        stale,
	})
	s.publishEvent(ctx, s.db, "worker_location_updated", "assignment", assignmentID.String(), map[string]any{
		"assignmentId": assignmentID.String(),
		"workerId":     auth.UserID.String(),
		"coordinate":   *req.Coordinate,
		"recordedAt":   formatTimeISO(recordedAt),
		"sequence":     *req.Sequence,
		"stale":        stale,
	})

	writeData(w, 201, map[string]any{
		"assignmentId": assignmentID.String(),
		"coordinate":   *req.Coordinate,
		"sequence":     *req.Sequence,
		"recordedAt":   formatTimeISO(recordedAt),
	})
}

