func (s *Server) buildJourneyPlan(ctx context.Context, q DBTx, journeyID uuid.UUID, depth int) (*JourneyPlan, error) {
        var parentID, replID, splitID *uuid.UUID
        var planVer, capUsed, capAvail int
        var routeMode, status string
        var estDel time.Time
        var totalCost float64
        var sampleIDsB []byte
        var valid bool
        var replanStatus *string

        err := q.QueryRow(ctx, `
                SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at,
                       total_cost_units, capacity_used, capacity_available, sample_ids, valid,
                       replan_status, replacement_journey_id, split_journey_id
                FROM journeys WHERE journey_id = $1
        `, journeyID).Scan(
                &parentID, &planVer, &routeMode, &status, &estDel,
                &totalCost, &capUsed, &capAvail, &sampleIDsB, &valid,
                &replanStatus, &replID, &splitID,
        )
        if err != nil {
                return nil, err
        }

        var sampleIDs []string
        _ = json.Unmarshal(sampleIDsB, &sampleIDs)
        if sampleIDs == nil {
                sampleIDs = []string{}
        }

        // Load stops
        sRows, err := q.Query(ctx, `
                SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
                FROM journey_stops
                WHERE journey_id = $1
                ORDER BY sequence ASC
        `, journeyID)
        if err != nil {
                return nil, err
        }
        stops := []JourneyStop{}
        for sRows.Next() {
                var stID, locID uuid.UUID
                var stType string
                var seq, dwell int
                var est time.Time
                var lat, lng float64
                var comp *time.Time
                if err := sRows.Scan(&stID, &locID, &stType, &seq, &est, &dwell, &lat, &lng, &comp); err == nil {
                        estStr := formatTimeISO(est)
                        js := JourneyStop{
                                StopID:       stID.String(),
                                LocationID:   locID.String(),
                                LocationSnk:  locID.String(),
                                StopType:     stType,
                                StopTypeSnk:  stType,
                                Sequence:     seq,
                                EstimatedAt:  estStr,
                                EstimatedSnk: estStr,
                                DwellMinutes: dwell,
                                Coordinate:   &Coordinate{Latitude: lat, Longitude: lng},
                        }
                        if comp != nil {
                                cStr := formatTimeISO(*comp)
                                js.CompletedAt = &cStr
                        }
                        stops = append(stops, js)
                }
        }
        sRows.Close()

        // Load assignments
        aRows, err := q.Query(ctx, `
                SELECT assignment_id, sample_id, kind, sequence, status,
                       COALESCE(worker_id, offered_to_worker_id), from_location_id, to_location_id
                FROM assignments
                WHERE journey_id = $1 AND active = TRUE
                ORDER BY sequence ASC, created_at ASC
        `, journeyID)
        if err != nil {
                return nil, err
        }

        legs := []JourneyLeg{}
        collIDs := []string{}
        nodeIDs := []string{}
        labIDs := []string{}
        transportIDs := []string{}
        workerSet := make(map[string]bool)
        assignedWorkerIDs := []string{}

        legSeq := 1
        for aRows.Next() {
                var aID, sID uuid.UUID
                var kind, aStatus string
                var seq int
                var wID, fromLoc, toLoc *uuid.UUID
                if err := aRows.Scan(&aID, &sID, &kind, &seq, &aStatus, &wID, &fromLoc, &toLoc); err == nil {
                        aStr := aID.String()
                        sStr := sID.String()
                        if wID != nil {
                                wStr := wID.String()
                                if !workerSet[wStr] {
                                        workerSet[wStr] = true
                                        assignedWorkerIDs = append(assignedWorkerIDs, wStr)
                                }
                        }
                        switch kind {
                        case "collection":
                                collIDs = append(collIDs, aStr)
                        case "node":
                                nodeIDs = append(nodeIDs, aStr)
                        case "laboratory":
                                labIDs = append(labIDs, aStr)
                        case "transport":
                                transportIDs = append(transportIDs, aStr)
                                jl := JourneyLeg{
                                        AssignmentID:  aStr,
                                        AssignmentSnk: aStr,
                                        Sequence:      legSeq,
                                        Status:        aStatus,
                                        SampleID:      &sStr,
                                }
                                if fromLoc != nil {
                                        fl := fromLoc.String()
                                        jl.FromLocationID = &fl
                                        jl.FromLocSnk = &fl
                                }
                                if toLoc != nil {
                                        tl := toLoc.String()
                                        jl.ToLocationID = &tl
                                        jl.ToLocSnk = &tl
                                }
                                if wID != nil {
                                        wl := wID.String()
                                        jl.WorkerID = &wl
                                        jl.WorkerSnk = &wl
                                }
                                legs = append(legs, jl)
                                legSeq++
                        }

