        if len(route.Connections) == 0 {
                // Single node that is both collection point and laboratory
                twID, _ := s.findEligibleWorkerForAssignment(ctx, q, "transport", st, nil, nil, startTime, usedInCycle)
                if twID != nil {
                        usedInCycle[*twID]++
                }
                tID := uuid.New()
