                        wPtr = holderID
                        twID = holderID
                        tStatus = "accepted"
                }
                _, _ = q.Exec(ctx, `
                        INSERT INTO assignments (
                                assignment_id, journey_id, sample_id, kind, sequence, status,
                                worker_id, offered_to_worker_id, offer_expires_at, from_location_id, to_location_id, expected_sample_type_id
                        ) VALUES ($1, $2, $3, 'transport', $4, $5, $6, $7, $8, $9, $9, $10)
                `, tID, journeyID, sampleID, seq, tStatus, wPtr, twID, offerExp, startLoc, st.SampleTypeID)
                if twID != nil && wPtr == nil {
                        _, _ = q.Exec(ctx, `UPDATE users SET assignment_count = assignment_count + 1, last_offered_at = NOW() WHERE user_id = $1`, *twID)
                }
                activeAssignmentIDs = append(activeAssignmentIDs, tID.String())
                seq++
        } else {
                for idx, conn := range route.Connections {
                        twID, _ := s.findEligibleWorkerForAssignment(ctx, q, "transport", st, nil, nil, startTime, usedInCycle)
                        if twID != nil {
                                usedInCycle[*twID]++
                        }
                        tID := uuid.New()
                        tStatus := "pending"
                        var wPtr *uuid.UUID
                        if presealed && idx == 0 && holderID != nil && len(activeAssignmentIDs) == 0 {
                                wPtr = holderID
                                twID = holderID
                                tStatus = "accepted"
                        }
                        _, _ = q.Exec(ctx, `
                                INSERT INTO assignments (
                                        assignment_id, journey_id, sample_id, kind, sequence, status,
                                        worker_id, offered_to_worker_id, offer_expires_at,
                                        from_location_id, to_location_id, connection_id, expected_sample_type_id
                                ) VALUES ($1, $2, $3, 'transport', $4, $5, $6, $7, $8, $9, $10, $11, $12)
                        `, tID, journeyID, sampleID, seq, tStatus, wPtr, twID, offerExp, conn.FromLocationID, conn.ToLocationID, conn.ConnectionID, st.SampleTypeID)
                        if twID != nil && wPtr == nil {
                                _, _ = q.Exec(ctx, `UPDATE users SET assignment_count = assignment_count + 1, last_offered_at = NOW() WHERE user_id = $1`, *twID)
                        }
                        activeAssignmentIDs = append(activeAssignmentIDs, tID.String())
                        seq++

                        // If this connection ends at an intermediate node (idx < len(route.Connections)-1), create a node assignment for that hub/transfer node
                        if idx < len(route.Connections)-1 {
                                midLoc := route.Nodes[idx+1].LocationID
                                nextLoc := route.Nodes[idx+2].LocationID
                                nhWorkerID, _ := s.findEligibleWorkerForAssignment(ctx, q, "node", st, &midLoc, nil, startTime, usedInCycle)
                                if nhWorkerID != nil {
                                        usedInCycle[*nhWorkerID]++
                                }
                                nodeAssignID := uuid.New()
                                _, _ = q.Exec(ctx, `
                                        INSERT INTO assignments (
                                                assignment_id, journey_id, sample_id, kind, sequence, status,
                                                offered_to_worker_id, offer_expires_at, from_location_id, to_location_id,
                                                node_id, incoming_from_location_id, outgoing_to_location_id, expected_sample_type_id
                                        ) VALUES ($1, $2, $3, 'node', $4, 'pending', $5, $6, $7, $7, $7, $8, $9, $10)
                                `, nodeAssignID, journeyID, sampleID, seq, nhWorkerID, offerExp, midLoc, conn.FromLocationID, nextLoc, st.SampleTypeID)
                                if nhWorkerID != nil {
                                        _, _ = q.Exec(ctx, `UPDATE users SET assignment_count = assignment_count + 1, last_offered_at = NOW() WHERE user_id = $1`, *nhWorkerID)
                                }
                                activeAssignmentIDs = append(activeAssignmentIDs, nodeAssignID.String())
                                seq++
                        }
                }
        }

        // Laboratory intake assignment at target laboratory
        labWorkerID, _ := s.findEligibleWorkerForAssignment(ctx, q, "laboratory", st, &endLoc, nil, startTime, usedInCycle)
        if labWorkerID != nil {
                usedInCycle[*labWorkerID]++
        }
        labAssignID := uuid.New()
        inLoc := startLoc
        if len(route.Nodes) > 1 {
                inLoc = route.Nodes[len(route.Nodes)-2].LocationID
        }
        _, _ = q.Exec(ctx, `
                INSERT INTO assignments (
                        assignment_id, journey_id, sample_id, kind, sequence, status,
                        offered_to_worker_id, offer_expires_at, from_location_id, to_location_id,
                        laboratory_id, incoming_from_location_id, expected_sample_type_id
                ) VALUES ($1, $2, $3, 'laboratory', $4, 'pending', $5, $6, $7, $7, $7, $8, $9)
        `, labAssignID, journeyID, sampleID, seq, labWorkerID, offerExp, endLoc, inLoc, st.SampleTypeID)
        if labWorkerID != nil {
                _, _ = q.Exec(ctx, `UPDATE users SET assignment_count = assignment_count + 1, last_offered_at = NOW() WHERE user_id = $1`, *labWorkerID)
        }
        activeAssignmentIDs = append(activeAssignmentIDs, labAssignID.String())

        return journeyID, activeAssignmentIDs, missingQualifiedCollector, nil
}

func (s *Server) reserveResourceCapacity(ctx context.Context, q DBTx, journeyID, sampleID uuid.UUID, resourceType string, resourceID uuid.UUID, units int, cooled bool) error {
        if resourceType == "location" {
                if cooled {
                        tag, err := q.Exec(ctx, `
                                UPDATE locations
                                SET cooled_reserved_units = cooled_reserved_units + $1
                                WHERE location_id = $2 AND (cooled_capacity_units - cooled_reserved_units) >= $1
                        `, units, resourceID)
                        if err != nil || tag.RowsAffected() == 0 {
                                return fmt.Errorf("cooled_capacity_exhausted")
                        }
                } else {
                        tag, err := q.Exec(ctx, `
                                UPDATE locations
                                SET reserved_units = reserved_units + $1
                                WHERE location_id = $2 AND (capacity_units - reserved_units) >= $1
                        `, units, resourceID)
                        if err != nil || tag.RowsAffected() == 0 {
                                return fmt.Errorf("capacity_exhausted")
                        }
                }
        } else if resourceType == "connection" {
                if cooled {
                        tag, err := q.Exec(ctx, `
                                UPDATE connections
                                SET cooled_reserved_units = cooled_reserved_units + $1
                                WHERE connection_id = $2 AND cooled = TRUE AND (cooled_capacity_units - cooled_reserved_units) >= $1
                        `, units, resourceID)

