                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Role-Specific Action Panels */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, padding: '0 20px 20px' }}>
        {session.activeRole === 'requester' && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Serviceability Check &amp; Collection Request</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <label>
                Origin Type:
                <select value={reqOriginType} onChange={(e) => setReqOriginType(e.target.value as any)} style={{ width: '100%' }}>
                  <option value="home">Home</option>
                  <option value="clinic">Clinic</option>
                  <option value="node">Node</option>
                </select>
              </label>
              <label>
                Sample Type:
                <input value={reqSampleType} onChange={(e) => setReqSampleType(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label>
