        {(session.activeRole === 'collection_professional' ||
          session.activeRole === 'delivery_partner' ||
          session.activeRole === 'node_handler' ||
          session.activeRole === 'laboratory_team') && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Custody, Checkpoints &amp; Field Operations</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, fontSize: 12 }}>
              <input placeholder="Sample ID" value={selectedSampleId} onChange={(e) => setSelectedSampleId(e.target.value)} />
              <input placeholder="Assignment ID" value={handoffFromAssign} onChange={(e) => setHandoffFromAssign(e.target.value)} />
              <input placeholder="Container (standard-vial / cryo-box)" value={containerType} onChange={(e) => setContainerType(e.target.value)} />
              <input placeholder="Observed Temp C" value={observedTemp} onChange={(e) => setObservedTemp(e.target.value)} />
              <input placeholder="Lat" value={workerLat} onChange={(e) => setWorkerLat(e.target.value)} />
              <input placeholder="Lng" value={workerLng} onChange={(e) => setWorkerLng(e.target.value)} />
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 10 }}>
              {(session.activeRole === 'collection_professional' || session.activeRole === 'delivery_partner') && (
                <button
                  onClick={async () => {
                    await apiCall('/api/record-worker-location', 'POST', {
                      assignmentId: handoffFromAssign,
                      coordinate: { latitude: parseFloat(workerLat), longitude: parseFloat(workerLng) },
                      recordedAt: new Date().toISOString(),
                      sequence: Math.floor(Date.now() / 1000)
                    })
                    setNotice('Location recorded')
                  }}
                >
                  Record Location
                </button>
              )}
              {session.activeRole === 'collection_professional' && (
                <button
                  onClick={async () => {
                    await apiCall('/api/collect-and-seal-sample', 'POST', {
                      sampleId: selectedSampleId,
                      assignmentId: handoffFromAssign,
                      collectedAt: new Date().toISOString(),
                      containerType,
                      observedTemperatureC: parseFloat(observedTemp),
                      idempotencyKey: crypto.randomUUID()
                    })
                    setNotice('Sample collected and sealed')
                    refreshData()
                  }}
                >
                  Collect &amp; Seal
                </button>
              )}
              <button
                onClick={async () => {
                  await apiCall('/api/record-handling-checkpoint', 'POST', {
                    sampleId: selectedSampleId,
                    assignmentId: handoffFromAssign || undefined,
                    containerType,
                    observedTemperatureC: parseFloat(observedTemp),
                    recordedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Handling checkpoint recorded')
                }}
              >
                Record Checkpoint
              </button>
              {session.activeRole === 'laboratory_team' && (
                <button
                  onClick={async () => {
                    await apiCall('/api/confirm-laboratory-receipt', 'POST', {
                      sampleId: selectedSampleId,
                      assignmentId: handoffFromAssign,
                      receivedAt: new Date().toISOString(),
                      containerType,
                      observedTemperatureC: parseFloat(observedTemp),
                      idempotencyKey: crypto.randomUUID()
                    })
                    setNotice('Laboratory receipt confirmed')
                    refreshData()
                  }}
                >
                  Confirm Lab Receipt
                </button>
              )}
            </div>
            <hr style={{ borderColor: '#334155', margin: '12px 0' }} />
            <h4>Dual-Confirmation Handoff</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6 }}>
              <input placeholder="To Assignment ID" value={handoffToAssign} onChange={(e) => setHandoffToAssign(e.target.value)} />
              <input placeholder="Receiver User ID" value={handoffReceiverId} onChange={(e) => setHandoffReceiverId(e.target.value)} />
              <input placeholder="Handoff ID" value={handoffIdInput} onChange={(e) => setHandoffIdInput(e.target.value)} />
            </div>
            <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
              <button
                onClick={async () => {
                  const h = await apiCall('/api/initiate-handoff', 'POST', {
                    sampleId: selectedSampleId,
                    fromAssignmentId: handoffFromAssign,
                    toAssignmentId: handoffToAssign,
                    receiverId: handoffReceiverId,
                    initiatedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setHandoffIdInput(h.handoffId)
                  setNotice(`Handoff initiated: ${h.handoffId}`)
                }}
              >
                Initiate Handoff
              </button>
              <button
                onClick={async () => {
                  await apiCall('/api/confirm-handoff', 'POST', {
                    handoffId: handoffIdInput,
                    confirmationSide: 'sender',
                    confirmedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Sender confirmed handoff')
                }}
              >
                Confirm (Sender)
              </button>
              <button
                onClick={async () => {
                  await apiCall('/api/confirm-handoff', 'POST', {
                    handoffId: handoffIdInput,
                    confirmationSide: 'receiver',
                    confirmedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Receiver confirmed handoff — custody transferred')
                  refreshData()
                }}
              >
                Confirm (Receiver)
              </button>
            </div>
          </div>
        )}

        {(session.activeRole === 'dispatcher' || session.activeRole === 'administrator') && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Dispatcher Monitor, Replanning &amp; Audit Search</h3>
            {opsState && (
              <div style={{ fontSize: 12, marginBottom: 10 }}>
                <div>
                  Serviceability Version: <strong>{opsState.serviceabilityVersion}</strong> | Locations:{' '}
                  {(opsState.locations || []).length} | Active Samples: {(opsState.samples || []).length} | Workers:{' '}
                  {(opsState.workers || []).length}
                </div>
                <div style={{ maxHeight: 130, overflowY: 'auto', marginTop: 6, background: '#0f172a', padding: 6, borderRadius: 6 }}>
                  {(opsState.samples || []).map((s: any) => (
                    <div key={s.sampleId} style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0' }}>
                      <span>
                        {s.sampleTypeCode} | {s.status} | Holder: {s.currentHolderUsername || 'unsealed'} |{' '}
                        {s.locationStale ? 'STALE' : 'Fresh'}
                      </span>
                      <button onClick={() => inspectSample(s.sampleId)}>Inspect</button>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
              <input
                placeholder="Journey ID"
                value={selectedJourneyId}
                onChange={(e) => setSelectedJourneyId(e.target.value)}
                style={{ flex: 1 }}
              />
              <button
                onClick={async () => {
                  const jp = await apiCall('/api/read-journey-plan', 'POST', { journeyId: selectedJourneyId })
                  setJourneyPlan(jp)
                }}
              >
                Load Plan
              </button>
              <button
                onClick={async () => {
                  if (!journeyPlan) return
                  const res = await apiCall('/api/reroute-journey', 'POST', {
                    journeyId: selectedJourneyId,
                    expectedPlanVersion: journeyPlan.planVersion,
                    reason: 'Dispatcher manual reroute',
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Rerouted: ${res.replanStatus}`)
                  refreshData()
                }}
              >
                Reroute Journey
              </button>
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              <input
                placeholder="Target Type (sample/journey/user)"
                value={auditFilterType}
                onChange={(e) => setAuditFilterType(e.target.value)}
              />
              <input placeholder="Target ID" value={auditFilterId} onChange={(e) => setAuditFilterId(e.target.value)} />
              <button
                onClick={async () => {
                  const res = await apiCall('/api/search-audit-trail', 'POST', {
                    targetType: auditFilterType || undefined,
                    targetId: auditFilterId || undefined
                  })
                  setAuditEntries(res.entries || [])
                }}
              >
                Search Audit
              </button>
            </div>
            {auditEntries.length > 0 && (
              <div style={{ maxHeight: 140, overflowY: 'auto', marginTop: 8, background: '#0f172a', padding: 6, borderRadius: 6, fontSize: 11 }}>
                {auditEntries.map((a) => (
                  <div key={a.auditId}>
                    [{a.occurredAt}] {a.actorRole} &rarr; <strong>{a.action}</strong> ({a.targetType}:{a.targetId})
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {session.activeRole === 'administrator' && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Administrator Configuration</h3>
            <h4>Upsert User</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
              <input placeholder="Username" value={newUsername} onChange={(e) => setNewUsername(e.target.value)} />
              <input placeholder="Password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} />
              <select value={newRole} onChange={(e) => setNewRole(e.target.value as Role)}>
                <option value="requester">requester</option>
                <option value="collection_professional">collection_professional</option>
                <option value="delivery_partner">delivery_partner</option>
                <option value="node_handler">node_handler</option>
                <option value="laboratory_team">laboratory_team</option>
                <option value="dispatcher">dispatcher</option>
                <option value="administrator">administrator</option>
              </select>
              <input placeholder="Qualifications (csv)" value={newQuals} onChange={(e) => setNewQuals(e.target.value)} />
              <input
                placeholder="Assigned Location ID (optional)"
                value={newAssignedLocId}
                onChange={(e) => setNewAssignedLocId(e.target.value)}
              />
              <button
                onClick={async () => {
                  await apiCall('/api/upsert-user', 'POST', {
                    username: newUsername,
                    password: newPassword,
                    roles: [newRole],
                    qualifications: newQuals.split(',').map((s) => s.trim()).filter(Boolean),
                    assignedLocationId: newAssignedLocId || undefined,
                    active: true,
                    available: true,
                    capacityUnits: 5,
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Upserted user ${newUsername}`)
                  refreshData()
                }}
              >
                Save User
              </button>
            </div>
            <h4 style={{ marginBottom: 4 }}>Upsert Network Location</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6 }}>
              <input placeholder="Code" value={locCode} onChange={(e) => setLocCode(e.target.value)} />
              <input placeholder="Name" value={locName} onChange={(e) => setLocName(e.target.value)} />
              <input placeholder="Functions (csv)" value={locFunctions} onChange={(e) => setLocFunctions(e.target.value)} />
              <input placeholder="Lat" value={locLat} onChange={(e) => setLocLat(e.target.value)} />
              <input placeholder="Lng" value={locLng} onChange={(e) => setLocLng(e.target.value)} />
              <button
                onClick={async () => {
                  await apiCall('/api/upsert-location', 'POST', {
                    code: locCode,
                    name: locName,
                    coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
                    functions: locFunctions.split(',').map((s) => s.trim()).filter(Boolean),
                    active: true,
                    handlingMinutes: 5,
                    capacityUnits: parseInt(locCap, 10),
                    cooledCapacityUnits: parseInt(locCooledCap, 10),
                    acceptedSampleTypeCodes: ['Amber', 'Indigo', 'Frost', 'Pulse'],
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Upserted location ${locCode}`)
                  refreshData()
                }}
              >
                Save Location
              </button>
            </div>
          </div>
        )}

        {/* Sample & Journey Inspector */}
        {(sampleDetail || sampleTimeline || journeyPlan) && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Sample, Custody Timeline &amp; Journey Inspector</h3>
            {sampleDetail && (
              <div style={{ fontSize: 12, marginBottom: 8 }}>
                <strong>Sample:</strong> {sampleDetail.sampleId} | <strong>Status:</strong> {sampleDetail.status} |{' '}
                <strong>Holder:</strong> {sampleDetail.currentHolderId || 'None'}
              </div>
            )}
            {sampleTimeline && (
              <div style={{ maxHeight: 160, overflowY: 'auto', background: '#0f172a', padding: 8, borderRadius: 6, fontSize: 11, marginBottom: 8 }}>
                <strong>Status Timeline &amp; Custody History:</strong>
                {(sampleTimeline.events || []).map((ev: any, i: number) => (
                  <div key={i}>
                    [{ev.occurredAt}] <strong>{ev.status}</strong> ({ev.eventType})
                  </div>
                ))}
              </div>
            )}
            {journeyPlan && (
              <pre style={{ maxHeight: 160, overflow: 'auto', background: '#0f172a', padding: 8, borderRadius: 6, fontSize: 11 }}>
                {JSON.stringify(journeyPlan, null, 2)}
              </pre>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

