import React, { useEffect, useRef, useState } from 'react'
import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'

const pmtilesProtocol = new Protocol()
maplibregl.addProtocol('pmtiles', pmtilesProtocol.tile)

type Role =
  | 'requester'
  | 'collection_professional'
  | 'delivery_partner'
  | 'node_handler'
  | 'laboratory_team'
  | 'dispatcher'
  | 'administrator'

interface UserSession {
  userId: string
  username: string
  roles: Role[]
  activeRole: Role
  assignedLocationId?: string
  token: string
}

export default function App() {
  const [session, setSession] = useState<UserSession | null>(() => {
    const saved = localStorage.getItem('lspds_session')
    return saved ? JSON.parse(saved) : null
  })
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)

  const [roleWork, setRoleWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: []
  })
  const [opsState, setOpsState] = useState<any>(null)
  const [selectedSampleId, setSelectedSampleId] = useState<string>('')
  const [sampleDetail, setSampleDetail] = useState<any>(null)
  const [sampleTimeline, setSampleTimeline] = useState<any>(null)
  const [selectedJourneyId, setSelectedJourneyId] = useState<string>('')
  const [journeyPlan, setJourneyPlan] = useState<any>(null)
  const [auditEntries, setAuditEntries] = useState<any[]>([])
  const [auditFilterType, setAuditFilterType] = useState('')
  const [auditFilterId, setAuditFilterId] = useState('')
  const [serviceabilityResult, setServiceabilityResult] = useState<any>(null)

  // Requester form
  const [reqOriginType, setReqOriginType] = useState<'home' | 'clinic' | 'node'>('home')
  const [reqLat, setReqLat] = useState('12.9720')
  const [reqLng, setReqLng] = useState('77.5950')
  const [reqSampleType, setReqSampleType] = useState('Amber')
  const [reqEarliest, setReqEarliest] = useState(() => new Date().toISOString())
  const [reqLatest, setReqLatest] = useState(() => new Date(Date.now() + 2 * 3600_000).toISOString())
  const [reqDeadline, setReqDeadline] = useState(() => new Date(Date.now() + 4 * 3600_000).toISOString())

  // Worker forms
  const [workerLat, setWorkerLat] = useState('12.9720')
  const [workerLng, setWorkerLng] = useState('77.5950')
  const [containerType, setContainerType] = useState('standard-vial')
  const [observedTemp, setObservedTemp] = useState('20')
  const [handoffFromAssign, setHandoffFromAssign] = useState('')
  const [handoffToAssign, setHandoffToAssign] = useState('')
  const [handoffReceiverId, setHandoffReceiverId] = useState('')
  const [handoffIdInput, setHandoffIdInput] = useState('')

  // Admin forms
  const [newUsername, setNewUsername] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [newRole, setNewRole] = useState<Role>('collection_professional')
  const [newQuals, setNewQuals] = useState('Amber,Indigo,Frost,Pulse')
  const [newAssignedLocId, setNewAssignedLocId] = useState('')

  const [locCode, setLocCode] = useState('')
  const [locName, setLocName] = useState('')
  const [locLat, setLocLat] = useState('12.9716')
  const [locLng, setLocLng] = useState('77.5946')
  const [locFunctions, setLocFunctions] = useState('collection_point,hub,laboratory')
  const [locCap, setLocCap] = useState('20')
  const [locCooledCap, setLocCooledCap] = useState('10')

  const mapContainerRef = useRef<HTMLDivElement | null>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const markersRef = useRef<maplibregl.Marker[]>([])

  const apiCall = async (path: string, method = 'POST', body?: any, tokenOverride?: string) => {
    setError(null)
    const tok = tokenOverride || session?.token
    const headers: Record<string, string> = {}
    if (tok) headers['Authorization'] = `Bearer ${tok}`
    if (body !== undefined) headers['Content-Type'] = 'application/json'

    const res = await fetch(path, {
      method,
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined
    })
    const json = await res.json().catch(() => ({}))
    if (!res.ok) {
      throw new Error(json.error || json.code || `HTTP ${res.status}`)
    }
    return json.data
  }

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const data = await apiCall('/api/authenticate-user', 'POST', { username, password })
      const sess: UserSession = {
        userId: data.userId,
        username: data.username,
        roles: data.roles,
        activeRole: data.activeRole,
        assignedLocationId: data.assignedLocationId,
        token: data.accessToken
      }
      setSession(sess)
      localStorage.setItem('lspds_session', JSON.stringify(sess))
      setNotice(`Signed in as ${sess.username} (${sess.activeRole})`)
    } catch (err: any) {
      setError(err.message)
    }
  }

  const handleLogout = async () => {
    setSession(null)
    localStorage.removeItem('lspds_session')
  }

  const handleSwitchRole = async (role: Role) => {
    if (!session) return
    try {
      const data = await apiCall('/api/select-active-role', 'POST', { role })
      const updated: UserSession = {
        ...session,
        activeRole: data.activeRole,
        roles: data.roles,
        token: data.accessToken || session.token
      }
      setSession(updated)
      localStorage.setItem('lspds_session', JSON.stringify(updated))
      setNotice(`Switched active role to ${data.activeRole}`)
    } catch (err: any) {
      setError(err.message)
    }
  }

  const refreshData = async () => {
    if (!session) return
    try {
      const work = await apiCall('/api/list-role-work', 'POST', {})
      setRoleWork(work)
      if (session.activeRole === 'dispatcher' || session.activeRole === 'administrator') {
        const ops = await apiCall('/api/read-operations-state', 'POST', {})
        setOpsState(ops)
      }
    } catch (err: any) {
      setError(err.message)
    }
  }

  useEffect(() => {
    if (!session) return
    refreshData()
  }, [session?.token, session?.activeRole])

  // Initialize MapLibre GL JS with offline PMTiles style
  useEffect(() => {
    if (!session || !mapContainerRef.current) return
    if (mapRef.current) return

    let cancelled = false
    fetch('/api/ui/bootstrap', {
      headers: { Authorization: `Bearer ${session.token}` }
    })
      .then((r) => r.json())
      .then((res) => {
        if (cancelled || !mapContainerRef.current) return
        const cfg = res.data || {}
        const map = new maplibregl.Map({
          container: mapContainerRef.current,
          style: cfg.mapStyleUrl || '/map-assets/style.json',
          center: cfg.initialCenter || [77.5946, 12.9716],
          zoom: cfg.initialZoom || 11
        })
        map.addControl(new maplibregl.NavigationControl(), 'top-right')
        mapRef.current = map
      })
      .catch(() => {})

    return () => {
      cancelled = true
      if (mapRef.current) {
        mapRef.current.remove()
        mapRef.current = null
      }
    }
  }, [session?.token])

  // Render markers on map when opsState updates
  useEffect(() => {
    const map = mapRef.current
    if (!map || !opsState) return

    markersRef.current.forEach((m) => m.remove())
    markersRef.current = []

    ;(opsState.locations || []).forEach((loc: any) => {
      if (!loc.coordinate) return
      const el = document.createElement('div')
      el.style.padding = '4px 8px'
      el.style.borderRadius = '6px'
      el.style.fontSize = '11px'
      el.style.fontWeight = 'bold'
      el.style.background = loc.active ? '#0284c7' : '#64748b'
      el.style.color = '#fff'
      el.style.border = '2px solid #fff'
      el.textContent = `${loc.code} (${loc.availableUnits}/${loc.capacityUnits})`
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
        .setPopup(
          new maplibregl.Popup().setHTML(
            `<strong>${loc.name}</strong><br/>Functions: ${(loc.activeFunctions || []).join(', ')}<br/>Regular: ${loc.availableUnits}/${loc.capacityUnits}<br/>Cooled: ${loc.cooledAvailableUnits}/${loc.cooledCapacityUnits}`
          )
        )
        .addTo(map)
      markersRef.current.push(marker)
    })

    ;(opsState.workers || []).forEach((w: any) => {
      if (!w.coordinate) return
      const el = document.createElement('div')
      el.style.padding = '3px 6px'
      el.style.borderRadius = '999px'
      el.style.fontSize = '10px'
      el.style.background = w.locationStale ? '#f59e0b' : '#10b981'
      el.style.color = '#000'
      el.style.fontWeight = 'bold'
      el.textContent = `Worker: ${w.username}`
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([w.coordinate.longitude, w.coordinate.latitude])
        .addTo(map)
      markersRef.current.push(marker)
    })

    ;(opsState.samples || []).forEach((s: any) => {
      if (!s.coordinate) return
      const el = document.createElement('div')
      el.style.padding = '3px 6px'
      el.style.borderRadius = '4px'
      el.style.fontSize = '10px'
      el.style.background = s.status === 'exception' ? '#ef4444' : '#a855f7'
      el.style.color = '#fff'
      el.textContent = `${s.sampleTypeCode} (${s.status})${s.locationStale ? ' [STALE]' : ''}`
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([s.coordinate.longitude, s.coordinate.latitude])
        .addTo(map)
      markersRef.current.push(marker)
    })
  }, [opsState])

  const inspectSample = async (sampleId: string) => {
    setSelectedSampleId(sampleId)
    try {
      const [detail, tl] = await Promise.all([
        apiCall('/api/read-sample', 'POST', { sampleId }),
        apiCall('/api/read-sample-timeline', 'POST', { sampleId })
      ])
      setSampleDetail(detail)
      setSampleTimeline(tl)
      if (detail.journeyId) {
        setSelectedJourneyId(detail.journeyId)
        const jp = await apiCall('/api/read-journey-plan', 'POST', { journeyId: detail.journeyId })
        setJourneyPlan(jp)
      }
    } catch (err: any) {
      setError(err.message)
    }
  }

  if (!session) {
    return (
      <div style={{ maxWidth: 420, margin: '80px auto', padding: 24, background: '#1e293b', borderRadius: 12 }}>
        <h2 style={{ marginTop: 0 }}>Lab Sample Pickup &amp; Delivery</h2>
        <p style={{ color: '#94a3b8', fontSize: 14 }}>Sign in with your account credentials</p>
        {error && <div style={{ padding: 10, background: '#7f1d1d', borderRadius: 6, marginBottom: 12 }}>{error}</div>}
        <form onSubmit={handleLogin} style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <input
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{ padding: 10, borderRadius: 6, border: '1px solid #334155', background: '#0f172a', color: '#fff' }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ padding: 10, borderRadius: 6, border: '1px solid #334155', background: '#0f172a', color: '#fff' }}
          />
          <button
            type="submit"
            style={{ padding: 10, borderRadius: 6, border: 'none', background: '#2563eb', color: '#fff', fontWeight: 600, cursor: 'pointer' }}
          >
            Sign In
          </button>
        </form>
      </div>
    )
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '12px 20px',
          background: '#1e293b',
          borderBottom: '1px solid #334155'
        }}
      >
        <div>
          <strong>Lab Sample Pickup &amp; Delivery System</strong>
          <span style={{ marginLeft: 16, fontSize: 13, color: '#94a3b8' }}>
            User: <strong>{session.username}</strong> | Active Role: <strong>{session.activeRole}</strong>
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 12, color: '#94a3b8' }}>Switch Role:</span>
          {session.roles.map((r) => (
            <button
              key={r}
              onClick={() => handleSwitchRole(r)}
              style={{
                padding: '6px 10px',
                borderRadius: 6,
                border: '1px solid #475569',
                background: session.activeRole === r ? '#2563eb' : '#0f172a',
                color: '#fff',
                fontSize: 12,
                cursor: 'pointer'
              }}
            >
              {r}
            </button>
          ))}
          <button
            onClick={refreshData}
            style={{ padding: '6px 10px', borderRadius: 6, border: 'none', background: '#059669', color: '#fff', cursor: 'pointer' }}
          >
            Refresh
          </button>
          <button
            onClick={handleLogout}
            style={{ padding: '6px 10px', borderRadius: 6, border: 'none', background: '#dc2626', color: '#fff', cursor: 'pointer' }}
          >
            Sign Out
          </button>
        </div>
      </header>

      {error && (
        <div style={{ margin: '10px 20px', padding: 10, background: '#7f1d1d', borderRadius: 6 }}>{error}</div>
      )}
      {notice && (
        <div style={{ margin: '10px 20px', padding: 10, background: '#065f46', borderRadius: 6 }}>{notice}</div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, padding: 20 }}>
        {/* Live MapLibre Map */}
        <div style={{ background: '#1e293b', borderRadius: 10, padding: 12, minHeight: 380 }}>
          <h3 style={{ marginTop: 0 }}>Live Network &amp; Tracking Map (PMTiles + MapLibre GL)</h3>
          <div ref={mapContainerRef} style={{ width: '100%', height: 320, borderRadius: 8, overflow: 'hidden' }} />
        </div>

        {/* Role Work Queue */}
        <div style={{ background: '#1e293b', borderRadius: 10, padding: 12 }}>
          <h3 style={{ marginTop: 0 }}>Work Queue ({session.activeRole})</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 10 }}>
            <div>
              <h4 style={{ margin: '4px 0', color: '#fbbf24' }}>Pending ({roleWork.pending.length})</h4>
              {roleWork.pending.map((item, idx) => (
                <div key={idx} style={{ padding: 8, background: '#0f172a', borderRadius: 6, marginBottom: 6, fontSize: 12 }}>
                  <div>ID: {item.assignmentId || item.sampleId}</div>
                  <div>Status: {item.status}</div>
                  {item.sampleId && (
                    <button onClick={() => inspectSample(item.sampleId)} style={{ marginTop: 4, marginRight: 4 }}>
                      Inspect Sample
                    </button>
                  )}
                  {item.assignmentId && (
                    <div style={{ marginTop: 4, display: 'flex', gap: 4 }}>
                      <button
                        onClick={async () => {
                          await apiCall('/api/accept-assignment', 'POST', {
                            assignmentId: item.assignmentId,
                            idempotencyKey: crypto.randomUUID()
                          })
                          setNotice('Assignment accepted')
                          refreshData()
                        }}
                      >
                        Accept
                      </button>
                      <button
                        onClick={async () => {
                          await apiCall('/api/decline-assignment', 'POST', {
                            assignmentId: item.assignmentId,
                            reason: 'Busy',
                            idempotencyKey: crypto.randomUUID()
                          })
                          setNotice('Assignment declined')
                          refreshData()
                        }}
                      >
                        Decline
                      </button>
                    </div>
                  )}
                </div>
              ))}
            </div>
            <div>
              <h4 style={{ margin: '4px 0', color: '#38bdf8' }}>In Progress ({roleWork.inProgress.length})</h4>
              {roleWork.inProgress.map((item, idx) => (
                <div key={idx} style={{ padding: 8, background: '#0f172a', borderRadius: 6, marginBottom: 6, fontSize: 12 }}>
                  <div>ID: {item.assignmentId || item.sampleId}</div>
                  <div>Kind: {item.kind || 'request'} | Status: {item.status}</div>
                  {item.sampleId && (
                    <button onClick={() => inspectSample(item.sampleId)} style={{ marginTop: 4 }}>
                      Inspect Sample
                    </button>
                  )}
                </div>
              ))}
            </div>
            <div>
              <h4 style={{ margin: '4px 0', color: '#4ade80' }}>Completed ({roleWork.completed.length})</h4>
              {roleWork.completed.map((item, idx) => (
                <div key={idx} style={{ padding: 8, background: '#0f172a', borderRadius: 6, marginBottom: 6, fontSize: 12 }}>
                  <div>ID: {item.assignmentId || item.sampleId}</div>
                  <div>Status: {item.status}</div>
                  {item.sampleId && (
                    <button onClick={() => inspectSample(item.sampleId)} style={{ marginTop: 4 }}>
                      Timeline
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Role-Specific Action Panels */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, padding: '0 20px 20px' }}>
        {session.activeRole === 'requester' && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Serviceability Check &amp; Collection Request</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <label>
                Origin Type:
                <select value={reqOriginType} onChange={(e) => setReqOriginType(e.target.value as any)} style={{ width: '100%' }}>
                  <option value="home">Home</option>
                  <option value="clinic">Clinic</option>
                  <option value="node">Node</option>
                </select>
              </label>
              <label>
                Sample Type:
                <input value={reqSampleType} onChange={(e) => setReqSampleType(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label>
                Latitude:
                <input value={reqLat} onChange={(e) => setReqLat(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label>
                Longitude:
                <input value={reqLng} onChange={(e) => setReqLng(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label>
                Window Start:
                <input value={reqEarliest} onChange={(e) => setReqEarliest(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label>
                Window End:
                <input value={reqLatest} onChange={(e) => setReqLatest(e.target.value)} style={{ width: '100%' }} />
              </label>
              <label style={{ gridColumn: 'span 2' }}>
                Delivery Deadline:
                <input value={reqDeadline} onChange={(e) => setReqDeadline(e.target.value)} style={{ width: '100%' }} />
              </label>
            </div>
            <div style={{ marginTop: 10, display: 'flex', gap: 8 }}>
              <button
                onClick={async () => {
                  const res = await apiCall('/api/check-serviceability', 'POST', {
                    origin: {
                      kind: reqOriginType,
                      coordinate: { latitude: parseFloat(reqLat), longitude: parseFloat(reqLng) }
                    },
                    sampleTypeCode: reqSampleType,
                    collectionWindow: { earliestAt: reqEarliest, latestAt: reqLatest },
                    deliveryDeadline: reqDeadline
                  })
                  setServiceabilityResult(res)
                }}
              >
                Dry-Run Check Serviceability
              </button>
              <button
                onClick={async () => {
                  const res = await apiCall('/api/create-collection-request', 'POST', {
                    origin: {
                      kind: reqOriginType,
                      coordinate: { latitude: parseFloat(reqLat), longitude: parseFloat(reqLng) }
                    },
                    sampleTypeCode: reqSampleType,
                    collectionWindow: { earliestAt: reqEarliest, latestAt: reqLatest },
                    deliveryDeadline: reqDeadline,
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Created sample ${res.sample.sampleId}`)
                  refreshData()
                }}
              >
                Create Collection Request
              </button>
            </div>
            {serviceabilityResult && (
              <pre style={{ marginTop: 10, background: '#0f172a', padding: 8, borderRadius: 6, fontSize: 11, overflowX: 'auto' }}>
                {JSON.stringify(serviceabilityResult, null, 2)}
              </pre>
            )}
          </div>
        )}

        {(session.activeRole === 'collection_professional' ||
          session.activeRole === 'delivery_partner' ||
          session.activeRole === 'node_handler' ||
          session.activeRole === 'laboratory_team') && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Custody, Checkpoints &amp; Field Operations</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, fontSize: 12 }}>
              <input placeholder="Sample ID" value={selectedSampleId} onChange={(e) => setSelectedSampleId(e.target.value)} />
              <input placeholder="Assignment ID" value={handoffFromAssign} onChange={(e) => setHandoffFromAssign(e.target.value)} />
              <input placeholder="Container (standard-vial / cryo-box)" value={containerType} onChange={(e) => setContainerType(e.target.value)} />
              <input placeholder="Observed Temp C" value={observedTemp} onChange={(e) => setObservedTemp(e.target.value)} />
              <input placeholder="Lat" value={workerLat} onChange={(e) => setWorkerLat(e.target.value)} />
              <input placeholder="Lng" value={workerLng} onChange={(e) => setWorkerLng(e.target.value)} />
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 10 }}>
              {(session.activeRole === 'collection_professional' || session.activeRole === 'delivery_partner') && (
                <button
                  onClick={async () => {
                    await apiCall('/api/record-worker-location', 'POST', {
                      assignmentId: handoffFromAssign,
                      coordinate: { latitude: parseFloat(workerLat), longitude: parseFloat(workerLng) },
                      recordedAt: new Date().toISOString(),
                      sequence: Math.floor(Date.now() / 1000)
                    })
                    setNotice('Location recorded')
                  }}
                >
                  Record Location
                </button>
              )}
              {session.activeRole === 'collection_professional' && (
                <button
                  onClick={async () => {
                    await apiCall('/api/collect-and-seal-sample', 'POST', {
                      sampleId: selectedSampleId,
                      assignmentId: handoffFromAssign,
                      collectedAt: new Date().toISOString(),
                      containerType,
                      observedTemperatureC: parseFloat(observedTemp),
                      idempotencyKey: crypto.randomUUID()
                    })
                    setNotice('Sample collected and sealed')
                    refreshData()
                  }}
                >
                  Collect &amp; Seal
                </button>
              )}
              <button
                onClick={async () => {
                  await apiCall('/api/record-handling-checkpoint', 'POST', {
                    sampleId: selectedSampleId,
                    assignmentId: handoffFromAssign || undefined,
                    containerType,
                    observedTemperatureC: parseFloat(observedTemp),
                    recordedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Handling checkpoint recorded')
                }}
              >
                Record Checkpoint
              </button>
              {session.activeRole === 'laboratory_team' && (
                <button
                  onClick={async () => {
                    await apiCall('/api/confirm-laboratory-receipt', 'POST', {
                      sampleId: selectedSampleId,
                      assignmentId: handoffFromAssign,
                      receivedAt: new Date().toISOString(),
                      containerType,
                      observedTemperatureC: parseFloat(observedTemp),
                      idempotencyKey: crypto.randomUUID()
                    })
                    setNotice('Laboratory receipt confirmed')
                    refreshData()
                  }}
                >
                  Confirm Lab Receipt
                </button>
              )}
            </div>
            <hr style={{ borderColor: '#334155', margin: '12px 0' }} />
            <h4>Dual-Confirmation Handoff</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6 }}>
              <input placeholder="To Assignment ID" value={handoffToAssign} onChange={(e) => setHandoffToAssign(e.target.value)} />
              <input placeholder="Receiver User ID" value={handoffReceiverId} onChange={(e) => setHandoffReceiverId(e.target.value)} />
              <input placeholder="Handoff ID" value={handoffIdInput} onChange={(e) => setHandoffIdInput(e.target.value)} />
            </div>
            <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
              <button
                onClick={async () => {
                  const h = await apiCall('/api/initiate-handoff', 'POST', {
                    sampleId: selectedSampleId,
                    fromAssignmentId: handoffFromAssign,
                    toAssignmentId: handoffToAssign,
                    receiverId: handoffReceiverId,
                    initiatedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setHandoffIdInput(h.handoffId)
                  setNotice(`Handoff initiated: ${h.handoffId}`)
                }}
              >
                Initiate Handoff
              </button>
              <button
                onClick={async () => {
                  await apiCall('/api/confirm-handoff', 'POST', {
                    handoffId: handoffIdInput,
                    confirmationSide: 'sender',
                    confirmedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Sender confirmed handoff')
                }}
              >
                Confirm (Sender)
              </button>
              <button
                onClick={async () => {
                  await apiCall('/api/confirm-handoff', 'POST', {
                    handoffId: handoffIdInput,
                    confirmationSide: 'receiver',
                    confirmedAt: new Date().toISOString(),
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice('Receiver confirmed handoff — custody transferred')
                  refreshData()
                }}
              >
                Confirm (Receiver)
              </button>
            </div>
          </div>
        )}

        {(session.activeRole === 'dispatcher' || session.activeRole === 'administrator') && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Dispatcher Monitor, Replanning &amp; Audit Search</h3>
            {opsState && (
              <div style={{ fontSize: 12, marginBottom: 10 }}>
                <div>
                  Serviceability Version: <strong>{opsState.serviceabilityVersion}</strong> | Locations:{' '}
                  {(opsState.locations || []).length} | Active Samples: {(opsState.samples || []).length} | Workers:{' '}
                  {(opsState.workers || []).length}
                </div>
                <div style={{ maxHeight: 130, overflowY: 'auto', marginTop: 6, background: '#0f172a', padding: 6, borderRadius: 6 }}>
                  {(opsState.samples || []).map((s: any) => (
                    <div key={s.sampleId} style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0' }}>
                      <span>
                        {s.sampleTypeCode} | {s.status} | Holder: {s.currentHolderUsername || 'unsealed'} |{' '}
                        {s.locationStale ? 'STALE' : 'Fresh'}
                      </span>
                      <button onClick={() => inspectSample(s.sampleId)}>Inspect</button>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
              <input
                placeholder="Journey ID"
                value={selectedJourneyId}
                onChange={(e) => setSelectedJourneyId(e.target.value)}
                style={{ flex: 1 }}
              />
              <button
                onClick={async () => {
                  const jp = await apiCall('/api/read-journey-plan', 'POST', { journeyId: selectedJourneyId })
                  setJourneyPlan(jp)
                }}
              >
                Load Plan
              </button>
              <button
                onClick={async () => {
                  if (!journeyPlan) return
                  const res = await apiCall('/api/reroute-journey', 'POST', {
                    journeyId: selectedJourneyId,
                    expectedPlanVersion: journeyPlan.planVersion,
                    reason: 'Dispatcher manual reroute',
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Rerouted: ${res.replanStatus}`)
                  refreshData()
                }}
              >
                Reroute Journey
              </button>
            </div>
            <div style={{ display: 'flex', gap: 6 }}>
              <input
                placeholder="Target Type (sample/journey/user)"
                value={auditFilterType}
                onChange={(e) => setAuditFilterType(e.target.value)}
              />
              <input placeholder="Target ID" value={auditFilterId} onChange={(e) => setAuditFilterId(e.target.value)} />
              <button
                onClick={async () => {
                  const res = await apiCall('/api/search-audit-trail', 'POST', {
                    targetType: auditFilterType || undefined,
                    targetId: auditFilterId || undefined
                  })
                  setAuditEntries(res.entries || [])
                }}
              >
                Search Audit
              </button>
            </div>
            {auditEntries.length > 0 && (
              <div style={{ maxHeight: 140, overflowY: 'auto', marginTop: 8, background: '#0f172a', padding: 6, borderRadius: 6, fontSize: 11 }}>
                {auditEntries.map((a) => (
                  <div key={a.auditId}>
                    [{a.occurredAt}] {a.actorRole} &rarr; <strong>{a.action}</strong> ({a.targetType}:{a.targetId})
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {session.activeRole === 'administrator' && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Administrator Configuration</h3>
            <h4>Upsert User</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
              <input placeholder="Username" value={newUsername} onChange={(e) => setNewUsername(e.target.value)} />
              <input placeholder="Password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} />
              <select value={newRole} onChange={(e) => setNewRole(e.target.value as Role)}>
                <option value="requester">requester</option>
                <option value="collection_professional">collection_professional</option>
                <option value="delivery_partner">delivery_partner</option>
                <option value="node_handler">node_handler</option>
                <option value="laboratory_team">laboratory_team</option>
                <option value="dispatcher">dispatcher</option>
                <option value="administrator">administrator</option>
              </select>
              <input placeholder="Qualifications (csv)" value={newQuals} onChange={(e) => setNewQuals(e.target.value)} />
              <input
                placeholder="Assigned Location ID (optional)"
                value={newAssignedLocId}
                onChange={(e) => setNewAssignedLocId(e.target.value)}
              />
              <button
                onClick={async () => {
                  await apiCall('/api/upsert-user', 'POST', {
                    username: newUsername,
                    password: newPassword,
                    roles: [newRole],
                    qualifications: newQuals.split(',').map((s) => s.trim()).filter(Boolean),
                    assignedLocationId: newAssignedLocId || undefined,
                    active: true,
                    available: true,
                    capacityUnits: 5,
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Upserted user ${newUsername}`)
                  refreshData()
                }}
              >
                Save User
              </button>
            </div>
            <h4 style={{ marginBottom: 4 }}>Upsert Network Location</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6 }}>
              <input placeholder="Code" value={locCode} onChange={(e) => setLocCode(e.target.value)} />
              <input placeholder="Name" value={locName} onChange={(e) => setLocName(e.target.value)} />
              <input placeholder="Functions (csv)" value={locFunctions} onChange={(e) => setLocFunctions(e.target.value)} />
              <input placeholder="Lat" value={locLat} onChange={(e) => setLocLat(e.target.value)} />
              <input placeholder="Lng" value={locLng} onChange={(e) => setLocLng(e.target.value)} />
              <button
                onClick={async () => {
                  await apiCall('/api/upsert-location', 'POST', {
                    code: locCode,
                    name: locName,
                    coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
                    functions: locFunctions.split(',').map((s) => s.trim()).filter(Boolean),
                    active: true,
                    handlingMinutes: 5,
                    capacityUnits: parseInt(locCap, 10),
                    cooledCapacityUnits: parseInt(locCooledCap, 10),
                    acceptedSampleTypeCodes: ['Amber', 'Indigo', 'Frost', 'Pulse'],
                    idempotencyKey: crypto.randomUUID()
                  })
                  setNotice(`Upserted location ${locCode}`)
                  refreshData()
                }}
              >
                Save Location
              </button>
            </div>
          </div>
        )}

        {/* Sample & Journey Inspector */}
        {(sampleDetail || sampleTimeline || journeyPlan) && (
          <div style={{ background: '#1e293b', borderRadius: 10, padding: 14 }}>
            <h3 style={{ marginTop: 0 }}>Sample, Custody Timeline &amp; Journey Inspector</h3>
            {sampleDetail && (
              <div style={{ fontSize: 12, marginBottom: 8 }}>
                <strong>Sample:</strong> {sampleDetail.sampleId} | <strong>Status:</strong> {sampleDetail.status} |{' '}
                <strong>Holder:</strong> {sampleDetail.currentHolderId || 'None'}
              </div>
            )}
            {sampleTimeline && (
              <div style={{ maxHeight: 160, overflowY: 'auto', background: '#0f172a', padding: 8, borderRadius: 6, fontSize: 11, marginBottom: 8 }}>
                <strong>Status Timeline &amp; Custody History:</strong>
                {(sampleTimeline.events || []).map((ev: any, i: number) => (
                  <div key={i}>
                    [{ev.occurredAt}] <strong>{ev.status}</strong> ({ev.eventType})
                  </div>
                ))}
              </div>
            )}
            {journeyPlan && (
              <pre style={{ maxHeight: 160, overflow: 'auto', background: '#0f172a', padding: 8, borderRadius: 6, fontSize: 11 }}>
                {JSON.stringify(journeyPlan, null, 2)}
              </pre>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

