package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func main() {
	ctx := context.Background()

	if len(os.Args) > 1 && (os.Args[1] == "reset" || os.Args[1] == "--reset" || os.Args[1] == "-reset") {
		pool, err := connectDB(ctx)
		if err != nil {
			log.Fatalf("connect db for reset: %v", err)
		}
		defer pool.Close()
		if err := resetDatabase(ctx, pool); err != nil {
			log.Fatalf("reset db: %v", err)
		}
		fmt.Println("Database reset complete")
		return
	}

	pool, err := connectDB(ctx)
	if err != nil {
		log.Fatalf("connect db: %v", err)
	}
	defer pool.Close()

	if err := initDatabase(ctx, pool); err != nil {
		log.Fatalf("init db: %v", err)
	}

	srv := NewServer(pool)
	mux := http.NewServeMux()

	mux.HandleFunc("/ready", srv.handleReady)
	mux.HandleFunc("/api/ready", srv.handleReady)

	// Auth & Users
	mux.HandleFunc("/api/authenticate-user", srv.handleAuthenticateUser)
	mux.HandleFunc("/api/select-active-role", srv.handleSelectActiveRole)
	mux.HandleFunc("/api/create-user", srv.handleCreateUser)
	mux.HandleFunc("/api/update-user-access", srv.handleUpdateUserAccess)
	mux.HandleFunc("/api/read-user/", srv.handleReadUser)
	mux.HandleFunc("/api/logout", func(w http.ResponseWriter, r *http.Request) {
		authHdr := strings.TrimSpace(r.Header.Get("Authorization"))
		token := strings.TrimSpace(strings.TrimPrefix(authHdr, "Bearer"))
		if token != "" {
			_, _ = srv.db.Exec(r.Context(), `DELETE FROM sessions WHERE token = $1`, token)
		}
		writeData(w, http.StatusOK, map[string]any{"loggedOut": true})
	})

	// Network & Admin
	mux.HandleFunc("/api/create-location", srv.handleCreateLocation)
	mux.HandleFunc("/api/update-location", srv.handleUpdateLocation)
	mux.HandleFunc("/api/set-location-status", srv.handleSetLocationStatus)
	mux.HandleFunc("/api/set-location-function-status", srv.handleSetLocationFunctionStatus)
	mux.HandleFunc("/api/create-connection", srv.handleCreateConnection)
	mux.HandleFunc("/api/set-connection-status", srv.handleSetConnectionStatus)
	mux.HandleFunc("/api/create-sample-type", srv.handleCreateSampleType)
	mux.HandleFunc("/api/update-sample-type", srv.handleUpdateSampleType)
	mux.HandleFunc("/api/configure-laboratory-acceptance", srv.handleConfigureLaboratoryAcceptance)
	mux.HandleFunc("/api/configure-capacity", srv.handleConfigureCapacity)
	mux.HandleFunc("/api/set-worker-availability", srv.handleSetWorkerAvailability)
	mux.HandleFunc("/api/read-serviceability-snapshot", srv.handleReadServiceabilitySnapshot)
	mux.HandleFunc("/api/check-serviceability", srv.handleCheckServiceability)

	// Requests, Samples, Custody, Assignments
	mux.HandleFunc("/api/create-collection-request", srv.handleCreateCollectionRequest)
	mux.HandleFunc("/api/ingest-presealed-sample", srv.handleIngestPresealedSample)
	mux.HandleFunc("/api/read-sample-state/", srv.handleReadSampleState)
	mux.HandleFunc("/api/read-sample-lifecycle", srv.handleReadSampleLifecycle)
	mux.HandleFunc("/api/accept-assignment", srv.handleAcceptAssignment)
	mux.HandleFunc("/api/decline-assignment", srv.handleDeclineAssignment)
	mux.HandleFunc("/api/collect-and-seal-sample", srv.handleCollectAndSealSample)
	mux.HandleFunc("/api/update-assignment-progress", srv.handleUpdateAssignmentProgress)
	mux.HandleFunc("/api/initiate-handoff", srv.handleInitiateHandoff)
	mux.HandleFunc("/api/confirm-handoff", srv.handleConfirmHandoff)
	mux.HandleFunc("/api/record-handling-checkpoint", srv.handleRecordHandlingCheckpoint)
	mux.HandleFunc("/api/confirm-laboratory-receipt", srv.handleConfirmLaboratoryReceipt)
	mux.HandleFunc("/api/record-laboratory-exception", srv.handleRecordLaboratoryException)
	mux.HandleFunc("/api/record-worker-location", srv.handleRecordWorkerLocation)

	// Journeys & Dispatch
	mux.HandleFunc("/api/read-journey-plan", srv.handleReadJourneyPlan)
	mux.HandleFunc("/api/reroute-journey", srv.handleRerouteJourney)
	mux.HandleFunc("/api/report-disruption", srv.handleReportDisruption)
	mux.HandleFunc("/api/cancel-journey", srv.handleCancelJourney)
	mux.HandleFunc("/api/merge-journeys", srv.handleMergeJourneys)
	mux.HandleFunc("/api/split-journey", srv.handleSplitJourney)
	mux.HandleFunc("/api/edit-active-plan", srv.handleEditActivePlan)

	// Views, Audit, Events, UI Bootstrap
	mux.HandleFunc("/api/list-role-work", srv.handleListRoleWork)
	mux.HandleFunc("/api/read-operations-state", srv.handleReadOperationsState)
	mux.HandleFunc("/api/search-audit-trail", srv.handleSearchAuditTrail)
	mux.HandleFunc("/api/events", srv.handleStreamRealtimeEvents)
	mux.HandleFunc("/api/ui/bootstrap", srv.handleReadUIBootstrap)

	// Map assets (PMTiles, style.json, fonts, sprites)
	mapAssetDir := os.Getenv("OFFLINE_MAP_ASSET_DIR")
	if mapAssetDir == "" {
		mapAssetDir = "/opt/arena/map-assets"
	}
	mapFileServer := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetDir)))
	mux.HandleFunc("/map-assets/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Range, Content-Type")
		w.Header().Set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges")
		mapFileServer.ServeHTTP(w, r)
	})

	// Frontend static files + SPA fallback
	frontendDist := "/workspace/frontend/dist"
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api/") {
			writeError(w, 404, "not_found", "API endpoint not found")
			return
		}
		cleanPath := filepath.Clean(r.URL.Path)
		if cleanPath == "/" || cleanPath == "." {
			http.ServeFile(w, r, filepath.Join(frontendDist, "index.html"))
			return
		}
		fullPath := filepath.Join(frontendDist, cleanPath)
		if info, err := os.Stat(fullPath); err == nil && !info.IsDir() {
			http.ServeFile(w, r, fullPath)
			return
		}
		http.ServeFile(w, r, filepath.Join(frontendDist, "index.html"))
	})

	handler := corsMiddleware(mux)

	httpSrv18082 := &http.Server{
		Addr:    "127.0.0.1:18082",
		Handler: handler,
	}
	httpSrv8080 := &http.Server{
		Addr:    "127.0.0.1:8080",
		Handler: handler,
	}

	go func() {
		log.Printf("Listening on http://127.0.0.1:8080")
		if err := httpSrv8080.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Printf("8080 server error: %v", err)
		}
	}()

	go func() {
		log.Printf("Listening on http://127.0.0.1:18082")
		if err := httpSrv18082.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("18082 server error: %v", err)
		}
	}()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	shutCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = httpSrv18082.Shutdown(shutCtx)
	_ = httpSrv8080.Shutdown(shutCtx)
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Range")
		w.Header().Set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges")
		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}
